function getConfigDescription(key) {
    if (configMetadata[key] && configMetadata[key].description) {
        return configMetadata[key].description;
    }
    return "No additional information available for this setting.";
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// Escapes a value for safe embedding inside a single-quoted JS string
// that lives inside an HTML attribute (e.g. onclick="fn('VALUE')").
// escapeHtml alone does not escape single quotes.
function escapeAttr(str) {
    if (str == null) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/'/g, '&#39;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/`/g, '&#96;');
}

function isValidIPv4(ip) {
    if (!ip) {
        return false;
    }
    const ipv4Pattern = /^(25[0-5]|2[0-4]\d|1?\d{1,2})(\.(25[0-5]|2[0-4]\d|1?\d{1,2})){3}$/;
    return ipv4Pattern.test(ip.trim());
}

document.addEventListener('DOMContentLoaded', function() {
    initializeSocket();
    initializeTabs();
    initializeMobileMenu();
    loadInitialData();
    setupAutoRefresh();
    setupEpaperAutoRefresh();
    setupEventListeners();
    initializeThreatIntelFilters();
    initializePwnUI();
    initializePwnagotchiVisibility();
    handleHeadlessMode();
    applyRusenseTabVisibility();
    applyTerminalVisibility();
    applyMeshTabVisibility();
    // localStorage gave us an instant paint above; now reconcile with the
    // server (the shared source of truth) without blocking startup.
    syncRusenseTabFromServer();
    syncTerminalFromServer();
    syncMeshTabFromServer();

});


function initializeSocket() {
    socket = io({
        reconnection: true,
        reconnectionDelay: 1000,
        reconnectionDelayMax: RECONNECT_DELAY_MAX
    });

    socket.on('connect', function() {
        console.log('Connected to Ragnar server');
        updateConnectionStatus(true);
        reconnectAttempts = 0;
        addConsoleMessage('Connected to Ragnar server', 'success');

        socket.emit('request_status');
        socket.emit('request_logs');
        refreshPwnagotchiStatus({ silent: true });
    });

    socket.on('connected', function(data) {
        // Server sends auth_configured flag on every socket connect
        if (data && typeof data.auth_configured !== 'undefined') {
            const show = data.auth_configured;
            const logoutBtn = document.getElementById('logout-btn');
            if (logoutBtn) logoutBtn.classList.toggle('hidden', !show);
            const mobileLogoutBtn = document.getElementById('mobile-logout-btn');
            if (mobileLogoutBtn) mobileLogoutBtn.classList.toggle('hidden', !show);
        }
    });

    socket.on('disconnect', function() {
        console.log('Disconnected from Ragnar server');
        updateConnectionStatus(false);
        addConsoleMessage('Disconnected from server', 'error');
        setTimeout(() => {
            if (socket && socket.disconnected) {
                console.log('Attempting manual socket reconnection');
                socket.connect();
            }
        }, 2000);
    });

    socket.on('status_update', function(data) {
        updateDashboardStatus(data);
    });

    socket.on('log_update', function(logs) {
        updateConsole(logs);
    });

    socket.on('pwnagotchi_status', function(statusPacket) {
        const previousState = pwnStatus.state;
        updatePwnagotchiUI(statusPacket);
        if (statusPacket && statusPacket.state && statusPacket.state !== previousState) {
            addConsoleMessage(`Pwnagotchi status changed: ${formatPwnStateLabel(statusPacket.state)}`, 'info');
        }
    });

    socket.on('network_update', function(data) {
        if (currentTab === 'network') {
            loadStableNetworkData();
        }
    });

    socket.on('credentials_update', function(data) {
        if (currentTab === 'discovered') {
            displayCredentialsTable(data);
        }
    });

    socket.on('loot_update', function(data) {
        if (currentTab === 'discovered') {
            displayLootTable(data);
        }
    });

    socket.on('config_updated', function(config) {
        addConsoleMessage('Configuration updated successfully', 'info');
        if (currentTab === 'config') {
            displayConfigForm(config);
        }
        updateAttackWarningBanner(Boolean(config && config.enable_attacks));
    });

    socket.on('scan_started', function(data) {
        handleScanStarted(data);
    });

    socket.on('scan_progress', function(data) {
        handleScanProgress(data);
    });

    socket.on('scan_host_update', function(data) {
        handleScanHostUpdate(data);
    });

    socket.on('scan_completed', function(data) {
        handleScanCompleted(data);
    });

    socket.on('scan_error', function(data) {
        handleScanError(data);
    });

    socket.on('deep_scan_update', function(data) {
        handleDeepScanUpdate(data);
    });

    socket.on('lynis_update', function(data) {
        handleLynisUpdate(data);
    });

    socket.on('manual_attack_update', function(data) {
        handleManualAttackUpdate(data);
    });

    socket.on('connect_error', function(error) {
        reconnectAttempts++;
        console.error('Connection error:', error);
        if (reconnectAttempts === RECONNECT_WARNING_THRESHOLD) {
            addConsoleMessage('Reconnecting to server… still attempting to reach backend', 'warning');
        } else if (reconnectAttempts > RECONNECT_WARNING_THRESHOLD && reconnectAttempts % RECONNECT_WARNING_THRESHOLD === 0) {
            addConsoleMessage(`Still reconnecting (attempt ${reconnectAttempts}). Will keep trying until successful.`, 'warning');
        }
    });
}

function updateConnectionStatus(connected) {
    const statusEl = document.getElementById('connection-status');
    if (statusEl) {
        if (connected) {
            statusEl.innerHTML = `
                <span class="w-2 h-2 bg-green-500 rounded-full pulse-glow"></span>
                <span class="text-xs text-gray-400">Connected</span>
            `;
        } else {
            statusEl.innerHTML = `
                <span class="w-2 h-2 bg-red-500 rounded-full"></span>
                <span class="text-xs text-gray-400">Disconnected</span>
            `;
        }
    }
}

function setupEventListeners() {
    document.querySelectorAll('[data-tab]').forEach(button => {
        button.addEventListener('click', function() {
            const tabName = this.getAttribute('data-tab');
            showTab(tabName);
        });
    });

    document.addEventListener('click', function(e) {
        if (e.target.classList.contains('refresh-btn')) {
            refreshCurrentTab();
        }
    });

    const clearBtn = document.getElementById('clear-console');
    if (clearBtn) {
        clearBtn.addEventListener('click', clearConsole);
    }

    const customScanBtn = document.getElementById('custom-deep-scan-btn');
    if (customScanBtn) {
        customScanBtn.addEventListener('click', handleCustomDeepScanRequest);
    }

    const customScanInput = document.getElementById('custom-deep-scan-ip');
    if (customScanInput) {
        customScanInput.addEventListener('keydown', function(event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                handleCustomDeepScanRequest();
            }
        });
    }

    const manualPortDropdown = document.getElementById('manual-port-dropdown');
    if (manualPortDropdown) {
        manualPortDropdown.addEventListener('change', () => {
            updateManualActions();
        });
    }

    const manualActionDropdown = document.getElementById('manual-action-dropdown');
    if (manualActionDropdown) {
        manualActionDropdown.addEventListener('change', () => {
            window.manualActionPreference = manualActionDropdown.value;
        });
    }

    const automationToggleBtn = document.getElementById('automation-toggle-btn');
    if (automationToggleBtn) {
        automationToggleBtn.addEventListener('click', handleAutomationToggle);
    }
}

function initializeTabs() {
    // Honor a deep-link hash so cross-unit mesh launch buttons land on the
    // right feature, e.g. #traffic, #threat-intel, #network/watchtower. Falls
    // back to the dashboard for anything unrecognised.
    if (!routeFromHash()) {
        showTab('dashboard');
    }
}

// Map a location hash to a tab (and optional subtab). Returns true if it routed.
// Known top-level tabs are driven by showTab; the network tab carries subtabs
// (integrity, watchtower, …) reached via showNetworkSubtab.
function routeFromHash() {
    const raw = (window.location.hash || '').replace(/^#/, '').trim();
    if (!raw) return false;
    const [tab, sub] = raw.split('/');
    const known = new Set([
        'dashboard', 'network', 'wifidef', 'discovered', 'rusense', 'pentest',
        'threat-intel', 'traffic', 'adv-vuln', 'wardriving', 'epaper', 'files',
        'system', 'connect', 'mesh', 'terminal', 'config',
    ]);
    if (!known.has(tab)) return false;
    try {
        showTab(tab);
        if (tab === 'network' && sub && typeof showNetworkSubtab === 'function') {
            // Integrity and Watchtower live on the Diagnostics subtab, not as
            // subtabs of their own — route there and scroll to the right card.
            const onDiag = { integrity: 'netint-card', watchtower: 'watchtower-card' };
            const realSub = onDiag[sub] ? 'diagnostics' : sub;
            const anchor = onDiag[sub];
            // Let the network tab finish mounting before selecting a subtab.
            setTimeout(() => {
                try { showNetworkSubtab(realSub); } catch (e) {}
                if (anchor) {
                    setTimeout(() => {
                        const el = document.getElementById(anchor);
                        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }, 120);
                }
            }, 60);
        }
        return true;
    } catch (e) {
        return false;
    }
}

// Re-route when the hash changes in an already-open tab (e.g. a second launch
// click into the same unit's window).
window.addEventListener('hashchange', () => { routeFromHash(); });

// ── RuSense (native RuView WiFi-CSI console, Shadow-DOM island) ─────────────
// The RuView SPA is served from /web/rusense/ and mounted into a shadow root
// under #rusense-host, so its compiled Tailwind never collides with Ragnar's
// styles. Sensing data is proxied by this Flask app (/ws/sensing, /api/v1/*).
const RUSENSE_SUBTABS = ['dashboard', 'observatory', 'sensing', 'nodes', 'training', 'settings', 'about'];
let _rusenseLoader = null;        // resolved loader module
let _rusenseLoading = null;       // in-flight import() promise
let _rusenseCurrent = 'dashboard';

function _setRusenseActive(name) {
    RUSENSE_SUBTABS.forEach(k =>
        _setSubtabActive(document.getElementById('rusense-subtab-' + k), k === name));
}

function loadRusenseLoader() {
    if (_rusenseLoader) return Promise.resolve(_rusenseLoader);
    if (!_rusenseLoading) {
        _rusenseLoading = import('/web/rusense/app/loader.js?v=20260705-calpresets')
            .then(m => { _rusenseLoader = m; return m; })
            .catch(err => { _rusenseLoading = null; throw err; });
    }
    return _rusenseLoading;
}

// Let the Observatory iframe ask the dashboard to expand it to the full
// viewport (it cannot escape its own container from inside the iframe).
let _observatoryFsInit = false;
function initObservatoryFullscreenBridge() {
    if (_observatoryFsInit) return;
    _observatoryFsInit = true;
    window.addEventListener('message', (e) => {
        if (!e.data || e.data.type !== 'observatory-fullscreen') return;
        const obs = document.getElementById('observatory-frame');
        if (!obs) return;
        const expanded = obs.classList.toggle('observatory-fullscreen');
        if (expanded) {
            const req = obs.requestFullscreen || obs.webkitRequestFullscreen;
            if (req) Promise.resolve(req.call(obs)).catch(() => { /* CSS overlay still applies */ });
        } else {
            const exit = document.exitFullscreen || document.webkitExitFullscreen;
            if (exit && (document.fullscreenElement || document.webkitFullscreenElement)) {
                Promise.resolve(exit.call(document)).catch(() => {});
            }
        }
    });
    // Keep the CSS overlay in sync when the user leaves OS fullscreen via Esc.
    document.addEventListener('fullscreenchange', () => {
        const obs = document.getElementById('observatory-frame');
        if (obs && !document.fullscreenElement) obs.classList.remove('observatory-fullscreen');
    });
}
initObservatoryFullscreenBridge();

function showRusenseSubtab(name) {
    if (!RUSENSE_SUBTABS.includes(name)) name = 'dashboard';
    _rusenseCurrent = name;
    _setRusenseActive(name);

    const host = document.getElementById('rusense-host');
    const obs = document.getElementById('observatory-frame');

    if (name === 'observatory') {
        // Full-page WebGL app: show the iframe and hide the shadow-island views.
        if (host) host.classList.add('hidden');
        if (obs) {
            obs.classList.remove('hidden');
            if (!obs.getAttribute('src')) obs.src = '/web/observatory.html?v=20260704-obsgate';
        }
        if (_rusenseLoader) { try { _rusenseLoader.suspend(); } catch (e) { /* ignore */ } }
        return;
    }

    // Regular shadow-island view: stop/hide the Observatory iframe, show the host.
    if (obs) { obs.classList.add('hidden'); if (obs.getAttribute('src')) obs.removeAttribute('src'); }
    if (host) host.classList.remove('hidden');
    loadRusenseLoader()
        .then(m => m.init(host, name))
        .catch(err => {
            console.error('[rusense] loader failed', err);
            const hint = document.getElementById('rusense-offline-hint');
            if (hint) {
                hint.textContent = 'RuSense UI failed to load: ' + (err && err.message);
                hint.classList.remove('hidden');
            }
        });
}

function initRusense() {
    showRusenseSubtab(_rusenseCurrent);
    // Reachability hint: /api/v1/status is proxied to the sensing-server.
    const hint = document.getElementById('rusense-offline-hint');
    if (hint) {
        fetch('/api/v1/status', { cache: 'no-store' })
            .then(r => hint.classList.toggle('hidden', r.ok))
            .catch(() => hint.classList.remove('hidden'));
    }
}

// ── Bundled sensing backend: install / uninstall from the RuSense tab ────────
let _sensingLogTimer = null;

function refreshSensingInstallCard() {
    const card = document.getElementById('sensing-install-card');
    if (!card) return;
    fetch('/api/sensing/status', { cache: 'no-store' })
        .then(r => r.json())
        .then(s => {
            const badge = document.getElementById('sensing-status-badge');
            const installBtn = document.getElementById('sensing-install-btn');
            const rebuildBtn = document.getElementById('sensing-rebuild-btn');
            const uninstallBtn = document.getElementById('sensing-uninstall-btn');
            const archNote = document.getElementById('sensing-arch-note');
            // Always visible in the RuSense tab: doubles as a status + management panel
            // (Install when absent, Reinstall / Uninstall when present).
            card.classList.remove('hidden');
            if (archNote) {
                archNote.textContent = s.has_prebuilt
                    ? 'Prebuilt binary bundled for this device (' + s.arch + ') — installs instantly.'
                    : 'No prebuilt binary for ' + s.arch + ' — install will fetch Rust and compile from source (slow).';
            }
            if (badge) {
                let txt = 'not installed', cls = 'bg-gray-700 text-gray-300';
                if (s.installing) { txt = 'installing…'; cls = 'bg-amber-700 text-amber-100'; }
                else if (s.installed && s.active) { txt = 'running'; cls = 'bg-green-700 text-green-100'; }
                else if (s.installed) { txt = 'stopped'; cls = 'bg-red-700 text-red-100'; }
                badge.textContent = txt;
                badge.className = 'text-xs px-2 py-0.5 rounded ' + cls;
            }
            const busy = !!s.installing;
            if (installBtn) { installBtn.disabled = busy; installBtn.textContent = s.installed ? 'Reinstall' : 'Install'; }
            if (rebuildBtn) rebuildBtn.disabled = busy;
            if (uninstallBtn) { uninstallBtn.classList.toggle('hidden', !s.installed); uninstallBtn.disabled = busy; }
            if (s.installing) startSensingLogPoll();
        })
        .catch(() => {});
}

function installSensingBackend(rebuild) {
    const logEl = document.getElementById('sensing-install-log');
    if (logEl) { logEl.classList.remove('hidden'); logEl.textContent = 'Starting…'; }
    fetch('/api/sensing/install', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rebuild: !!rebuild })
    }).then(() => startSensingLogPoll()).catch(() => {});
}

function uninstallSensingBackend() {
    if (!confirm('Stop and remove the bundled sensing backend?')) return;
    fetch('/api/sensing/uninstall', { method: 'POST' })
        .then(() => startSensingLogPoll()).catch(() => {});
}

function startSensingLogPoll() {
    if (_sensingLogTimer) return;
    const logEl = document.getElementById('sensing-install-log');
    if (logEl) logEl.classList.remove('hidden');
    const tick = () => {
        fetch('/api/sensing/install-log', { cache: 'no-store' })
            .then(r => r.json())
            .then(s => {
                if (logEl && s.log) { logEl.textContent = s.log; logEl.scrollTop = logEl.scrollHeight; }
                if (!s.installing) {
                    clearInterval(_sensingLogTimer); _sensingLogTimer = null;
                    refreshSensingInstallCard();
                    if (s.installed && s.active) {
                        const hint = document.getElementById('rusense-offline-hint');
                        if (hint) hint.classList.add('hidden');
                        showRusenseSubtab(_rusenseCurrent);
                    }
                }
            }).catch(() => {});
    };
    tick();
    _sensingLogTimer = setInterval(tick, 2000);
}

// ── RuSense tab visibility (toggle lives in Settings; hidden by default) ─────
// Stored server-side under the same key so the choice is shared across every
// browser/device (like Ragnar's other settings). localStorage is a local cache
// for instant first paint; the server value is synced in on load and wins.
const RUSENSE_TAB_KEY = 'rusense_tab_visible';

function _rusenseTabVisible() {
    return localStorage.getItem(RUSENSE_TAB_KEY) === '1';
}

function syncRusenseTabToggle() {
    const cb = document.getElementById('rusense-tab-enabled');
    if (cb) cb.checked = _rusenseTabVisible();
}

function applyRusenseTabVisibility() {
    const visible = _rusenseTabVisible();
    document.querySelectorAll('.rusense-nav').forEach(btn => btn.classList.toggle('hidden', !visible));
    // If the tab is hidden while it's the active one, fall back to the dashboard.
    if (!visible && typeof currentTab !== 'undefined' && currentTab === 'rusense') {
        showTab('dashboard');
    }
    syncRusenseTabToggle();
}

// Seed the local cache from the server config so a save on any device shows up
// here. Accepts an already-fetched config to avoid an extra round-trip; fetches
// one itself otherwise. Server wins when the key is present.
async function syncRusenseTabFromServer(config) {
    try {
        const cfg = config || await fetchAPI('/api/config');
        if (cfg && Object.prototype.hasOwnProperty.call(cfg, RUSENSE_TAB_KEY)) {
            localStorage.setItem(RUSENSE_TAB_KEY, cfg[RUSENSE_TAB_KEY] ? '1' : '0');
            applyRusenseTabVisibility();
        }
    } catch (e) { /* offline — keep the localStorage value */ }
}

function onRusenseTabToggled(cb) {
    localStorage.setItem(RUSENSE_TAB_KEY, cb.checked ? '1' : '0');
    applyRusenseTabVisibility();
    // Persist server-side so it's shared/persistent for everyone, not just here.
    postAPI('/api/config', { [RUSENSE_TAB_KEY]: cb.checked })
        .catch(err => console.warn('Failed to persist RuSense tab visibility:', err));
    if (cb.checked) showTab('rusense');
}

// ── Ragnar Mesh tab visibility (toggle in Settings; ON by default) ──────────
// Same server-backed + localStorage-cache pattern as the RuSense tab, but the
// default is VISIBLE: absent the key the tab shows, and only an explicit '0'
// hides it. Hiding is cosmetic — it never joins or leaves the mesh (that is
// mesh_enabled); it only removes the nav entry.
const MESH_TAB_KEY = 'mesh_tab_enabled';

function _meshTabVisible() {
    return localStorage.getItem(MESH_TAB_KEY) !== '0';   // default on
}

function syncMeshTabToggle() {
    const cb = document.getElementById('mesh-tab-enabled');
    if (cb) cb.checked = _meshTabVisible();
}

function applyMeshTabVisibility() {
    const visible = _meshTabVisible();
    document.querySelectorAll('.mesh-nav').forEach(btn => btn.classList.toggle('hidden', !visible));
    // If the tab is hidden while it's the active one, fall back to the dashboard.
    if (!visible && typeof currentTab !== 'undefined' && currentTab === 'mesh') showTab('dashboard');
    syncMeshTabToggle();
}

async function syncMeshTabFromServer(config) {
    try {
        const cfg = config || await fetchAPI('/api/config');
        if (cfg && Object.prototype.hasOwnProperty.call(cfg, MESH_TAB_KEY)) {
            localStorage.setItem(MESH_TAB_KEY, cfg[MESH_TAB_KEY] ? '1' : '0');
            applyMeshTabVisibility();
        }
    } catch (e) { /* offline — keep the localStorage value */ }
}

function onMeshTabToggled(cb) {
    localStorage.setItem(MESH_TAB_KEY, cb.checked ? '1' : '0');
    applyMeshTabVisibility();
    postAPI('/api/config', { [MESH_TAB_KEY]: cb.checked })
        .catch(err => console.warn('Failed to persist Mesh tab visibility:', err));
    if (cb.checked) showTab('mesh');
}
window.onMeshTabToggled = onMeshTabToggled;

// ==================== Web Terminal (xterm.js over Socket.IO) ====================
const TERMINAL_KEY = 'terminal_enabled';
let _term = null, _termFit = null, _termSocket = null, _termResizeHooked = false;

function _terminalEnabled() { return localStorage.getItem(TERMINAL_KEY) === '1'; }

function syncTerminalToggle() {
    const cb = document.getElementById('terminal-enabled');
    if (cb) cb.checked = _terminalEnabled();
}

function applyTerminalVisibility() {
    const enabled = _terminalEnabled();
    document.querySelectorAll('.terminal-nav').forEach(btn => btn.classList.toggle('hidden', !enabled));
    if (!enabled && typeof currentTab !== 'undefined' && currentTab === 'terminal') showTab('dashboard');
    syncTerminalToggle();
}

async function syncTerminalFromServer(config) {
    try {
        const cfg = config || await fetchAPI('/api/config');
        if (cfg && Object.prototype.hasOwnProperty.call(cfg, TERMINAL_KEY)) {
            localStorage.setItem(TERMINAL_KEY, cfg[TERMINAL_KEY] ? '1' : '0');
            applyTerminalVisibility();
        }
    } catch (e) { /* offline — keep the localStorage value */ }
}

function onTerminalToggled(cb) {
    localStorage.setItem(TERMINAL_KEY, cb.checked ? '1' : '0');
    applyTerminalVisibility();
    postAPI('/api/config', { [TERMINAL_KEY]: cb.checked })
        .then(() => addConsoleMessage(cb.checked ? 'Web terminal enabled' : 'Web terminal disabled', 'info'))
        .catch(err => {
            addConsoleMessage('Failed to toggle terminal: ' + err.message, 'error');
            cb.checked = !cb.checked;
            localStorage.setItem(TERMINAL_KEY, cb.checked ? '1' : '0');
            applyTerminalVisibility();
        });
    if (cb.checked) showTab('terminal'); else _termTeardown();
}

function _sendTermResize() {
    if (_term && _termSocket && _termSocket.connected) {
        _termSocket.emit('terminal_resize', { rows: _term.rows, cols: _term.cols });
    }
}

function _termTeardown() {
    try { if (_termSocket) { _termSocket.disconnect(); _termSocket = null; } } catch (e) { /* ignore */ }
}

function initTerminal() {
    const mount = document.getElementById('xterm-mount');
    const status = document.getElementById('terminal-status');
    if (!mount) return;
    if (typeof Terminal === 'undefined') {
        if (status) status.innerHTML = '<span class="text-red-400">Terminal library failed to load.</span>';
        return;
    }
    if (!_terminalEnabled()) {
        if (status) status.innerHTML = '<span class="text-amber-300">Web terminal is disabled.</span> Enable it in Config → Web Terminal.';
        _termTeardown();
        return;
    }
    if (status) status.textContent = '';

    if (!_term) {
        _term = new Terminal({ cursorBlink: true, fontSize: 13,
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
            theme: { background: '#0f172a', foreground: '#e2e8f0' } });
        _termFit = new FitAddon.FitAddon();
        _term.loadAddon(_termFit);
        _term.open(mount);
        _term.onData(d => { if (_termSocket && _termSocket.connected) _termSocket.emit('terminal_input', { data: d }); });
    }
    try { _termFit.fit(); } catch (e) { /* mount not sized yet */ }

    if (!_termSocket || !_termSocket.connected) {
        _term.reset();
        _termSocket = io('/terminal', { reconnection: false });
        _termSocket.on('connect', () => { setTimeout(() => { try { _termFit.fit(); } catch (e) {} _sendTermResize(); _term.focus(); }, 60); });
        _termSocket.on('terminal_output', d => _term.write(d.data || ''));
        _termSocket.on('terminal_exit', () => _term.write('\r\n\x1b[33m[session ended — press Reconnect for a new shell]\x1b[0m\r\n'));
        _termSocket.on('connect_error', () => _term.write('\r\n\x1b[31m[could not open terminal — is it enabled and are you logged in?]\x1b[0m\r\n'));
    }

    if (!_termResizeHooked) {
        window.addEventListener('resize', () => {
            if (typeof currentTab !== 'undefined' && currentTab === 'terminal' && _termFit) {
                try { _termFit.fit(); _sendTermResize(); } catch (e) { /* ignore */ }
            }
        });
        _termResizeHooked = true;
    }
    setTimeout(() => { try { _termFit.fit(); } catch (e) {} _sendTermResize(); }, 80);
}

function showTab(tabName) {
    // Backward-compat: these tabs are now sub-tabs of Network / Discovered
    if (tabName === 'networks') { showTab('network'); showNetworkSubtab('archive'); return; }
    if (tabName === 'network-map') { showTab('network'); showNetworkSubtab('map'); return; }
    if (tabName === 'credentials') { showTab('discovered'); showDiscoveredSubtab('credentials'); return; }
    if (tabName === 'diagnostics') { showTab('network'); showNetworkSubtab('diagnostics'); return; }

    currentTab = tabName;

    if (_rusenseLoader && tabName !== 'rusense') {
        try { _rusenseLoader.suspend(); } catch (e) { /* ignore */ }
    }

    // Leaving RuSense: stop the Observatory iframe (WebGL + WS) if it was open.
    if (tabName !== 'rusense') {
        const _obsFrame = document.getElementById('observatory-frame');
        if (_obsFrame && _obsFrame.getAttribute('src')) _obsFrame.removeAttribute('src');
    }

    if (systemMonitoringInterval && tabName !== 'system') {
        clearInterval(systemMonitoringInterval);
        systemMonitoringInterval = null;
    }
    
    document.querySelectorAll('.tab-content').forEach(tab => {
        tab.classList.add('hidden');
    });
    
    document.querySelectorAll('.nav-btn, [data-tab]').forEach(btn => {
        btn.classList.remove('bg-Ragnar-600');
        btn.classList.add('text-gray-300', 'hover:text-white', 'hover:bg-gray-700');
    });
    
    const selectedTab = document.getElementById(`${tabName}-tab`);
    if (selectedTab) {
        selectedTab.classList.remove('hidden');
    }
    
    const selectedBtn = document.querySelector(`[data-tab="${tabName}"]`);
    if (selectedBtn) {
        selectedBtn.classList.add('bg-Ragnar-600');
        selectedBtn.classList.remove('text-gray-300', 'hover:text-white', 'hover:bg-gray-700');
    }
    
    loadTabData(tabName);

    if (tabName === 'config') {
        try { refreshSensingInstallCard(); syncRusenseTabToggle(); syncTerminalToggle(); syncMeshTabToggle(); } catch (e) { /* ignore */ }
    }

    const mobileMenu = document.getElementById('mobile-menu');
    if (mobileMenu) {
        mobileMenu.classList.add('hidden');
    }
}

function _setSubtabActive(btn, active) {
    if (!btn) return;
    btn.classList.toggle('bg-Ragnar-600', active);
    btn.classList.toggle('text-white', active);
    btn.classList.toggle('text-slate-400', !active);
    btn.classList.toggle('hover:bg-slate-700', !active);
    btn.classList.toggle('hover:text-white', !active);
}

function showNetworkSubtab(name) {
    const views = {
        hosts: 'net-sub-hosts', archive: 'net-sub-archive', map: 'net-sub-map',
        diagnostics: 'net-sub-diagnostics', switch: 'net-sub-switch', interfaces: 'net-sub-interfaces',
        wifi: 'net-sub-wifi'
    };
    Object.keys(views).forEach(key => {
        const el = document.getElementById(views[key]);
        if (el) el.classList.toggle('hidden', key !== name);
        _setSubtabActive(document.getElementById('net-subtab-' + key), key === name);
    });
    if (name === 'archive') {
        loadAllNetworksData();
    } else if (name === 'map') {
        if (!_mapInitialized) { loadNetworkMap(); }
    } else if (name === 'hosts') {
        loadNetworkData();
    } else if (name === 'switch') {
        _lldpFillIfaces();
        loadLldp();
        _arpScanFillIfaces();
        _locateFillIfaces();
        _l2FillIfaces();
        _dhcpFillIfaces();
        _igmpFillIfaces();
        _ipv6FillIfaces();
        _ndpFillIfaces();
        _icmpFillIfaces();
        _ospfFillIfaces();
        _stpFillIfaces();
        _smbFillIfaces();
        _relayFillIfaces();
        _dtpFillIfaces();
        _cdpFillIfaces();
        _vtpFillIfaces();
        _eigrpFillIfaces();
        _isisFillIfaces();
        _fhrpFillIfaces();
        _bgpFillIfaces();
        dhcpSnoopStatus();
    } else if (name === 'interfaces') {
        loadNetworkIdentity();
        loadInterfaces();
    } else if (name === 'wifi') {
        wifiInit();
    } else if (name === 'diagnostics') {
        populateMtrSources();
        syncNetDiagDisplayFromServer();
        syncNetIntegrityFromServer();
        syncWatchtowerFromServer();
        _macWatchFillIfaces();
        _ntpFillIfaces();
        _snmpFillIfaces();
        _certFillIfaces();
        _tlsFillIfaces();
    }
    // Diagnostics tools run on demand; we only prefill the MTR start-point list.
}

// ============================================================================
// WiFi Spectrum Analyzer (Network > WiFi Analyzer sub-tab)
// Passive tri-band survey. Backend: /api/net/wifi/* (wifi_analyzer.py)
// ============================================================================
const _wifiState = { iface: '', band: 'all', view: 'bar', data: null, selected: null, auto: null, inited: false, bt: null, btOn: false, btBusy: false, btSelected: null,
    zb: null, zbOn: false, zbBusy: false, zbSelected: null, zbAvailable: false,
    hoverBssid: null, radius: null, fs: { open: false, wired: false, native: false },
    sdr: { available: false, running: false, band: '2.4', bandMhz: null, floor: -120, seq: 0, rows: [], maxhold: null, poll: null, statusPoll: null, error: null } };

const _WIFI_BAND_COLOR = { '2.4': '#f59e0b', '5': '#38bdf8', '6': '#a78bfa' };

function _wifiSignalColor(dbm) {
    if (dbm == null) return '#64748b';
    if (dbm >= -55) return '#22c55e';      // strong
    if (dbm >= -67) return '#84cc16';      // good
    if (dbm >= -75) return '#eab308';      // fair
    if (dbm >= -85) return '#f97316';      // weak
    return '#ef4444';                      // very weak
}

function _wifiFreqToChannel(freq) {
    const f = Math.round(freq);
    if (f === 2484) return 14;
    if (f >= 2400 && f < 2500) return Math.round((f - 2407) / 5);
    if (f === 5935) return 2;
    if (f >= 5925) return Math.round((f - 5950) / 5);
    return Math.round((f - 5000) / 5);
}

function wifiInit() {
    if (!_wifiState.inited) {
        _wifiState.inited = true;
        // Band selector
        document.querySelectorAll('#wifi-band-group .wifi-band').forEach(btn => {
            btn.addEventListener('click', () => wifiSetBand(btn.dataset.band));
        });
        _wifiState._setView = wifiSetView;   // kept: older call sites use it
        document.getElementById('wifi-view-bar').addEventListener('click', () => wifiSetView('bar'));
        document.getElementById('wifi-view-dome').addEventListener('click', () => wifiSetView('dome'));
        const wfBtn = document.getElementById('wifi-view-wf');
        if (wfBtn) wfBtn.addEventListener('click', () => { if (!wfBtn.disabled) wifiSetView('waterfall'); });
        _wifiWireCanvas(document.getElementById('wifi-spectrum'), 'wifi-tip', null);
        // Auto-refresh — refreshes the Wi-Fi survey and, when their overlays are
        // enabled, re-runs the Bluetooth and Zigbee scans too (each self-guards
        // against overlapping runs, so a slow sniff is simply skipped this tick).
        document.getElementById('wifi-auto').addEventListener('change', (e) => {
            if (_wifiState.auto) { clearInterval(_wifiState.auto); _wifiState.auto = null; }
            if (e.target.checked) _wifiState.auto = setInterval(_wifiAutoTick, 8000);
        });
        // Bluetooth overlay toggle
        const btChk = document.getElementById('wifi-bt');
        if (btChk) btChk.addEventListener('change', (e) => {
            _wifiState.btOn = e.target.checked;
            const panel = document.getElementById('wifi-bt-panel');
            if (panel) panel.classList.toggle('hidden', !_wifiState.btOn);
            if (_wifiState.btOn) wifiBtScan();
            else { if (_wifiState.data) _wifiDrawSpectrum(); }
        });
        // Zigbee overlay toggle (gated on a Huginn companion being present)
        const zbChk = document.getElementById('wifi-zb');
        if (zbChk) zbChk.addEventListener('change', (e) => {
            if (zbChk.disabled) { e.target.checked = false; return; }
            _wifiState.zbOn = e.target.checked;
            const panel = document.getElementById('wifi-zb-panel');
            if (panel) panel.classList.toggle('hidden', !_wifiState.zbOn);
            if (_wifiState.zbOn) wifiZbScan();
            else { if (_wifiState.data) _wifiDrawSpectrum(); }
        });
        ['wifi-tx', 'wifi-ple'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.addEventListener('change', () => { if (_wifiState.selected) wifiSelectAp(_wifiState.selected); });
        });
        window.addEventListener('resize', () => {
            if (_wifiState.view === 'waterfall') _wifiDrawWaterfall();
            else if (_wifiState.data) _wifiDrawSpectrum();
        });
    }
    wifiHeatmapInit();
    wifiHeatmapLoad();
    _wifiFillIfaces();
    _wifiSdrCheck();
    _wifiZbCheck();
    if (!_wifiState.sdr.statusPoll)
        _wifiState.sdr.statusPoll = setInterval(() => { _wifiSdrCheck(); _wifiZbCheck(); }, 15000);
    window.addEventListener('beforeunload', () => { if (_wifiState.sdr.running) _wifiSdrStop(); });
}

// Band + view are driven from two places now (the in-page toolbar and the
// full-screen bar), so both live here and repaint every control set.
function wifiSetBand(band) {
    _wifiState.band = band;
    _wifiSyncBandButtons();
    // In the live waterfall, a band change retunes the HackRF sweep; otherwise
    // it re-runs the passive Wi-Fi scan.
    if (_wifiState.view === 'waterfall') { _wifiSdrStop(); _wifiSdrStart(); }
    else wifiScan();
}

function _wifiSyncBandButtons() {
    document.querySelectorAll('#wifi-band-group .wifi-band').forEach(b => {
        const on = b.dataset.band === _wifiState.band;
        b.classList.toggle('bg-Ragnar-600', on); b.classList.toggle('text-white', on);
        b.classList.toggle('text-slate-300', !on);
    });
    document.querySelectorAll('#wifi-fs-band button').forEach(b => {
        const on = b.dataset.band === _wifiState.band;
        b.classList.toggle('wifi-hm-seg-on', on); b.classList.toggle('wifi-hm-seg-off', !on);
    });
}

function wifiSetView(v) {
    const prev = _wifiState.view;
    _wifiState.view = v;
    const bar = document.getElementById('wifi-view-bar'), dome = document.getElementById('wifi-view-dome'),
        wf = document.getElementById('wifi-view-wf');
    [['bar', bar], ['dome', dome], ['waterfall', wf]].forEach(([name, el]) => {
        if (!el) return;
        const on = name === v;
        el.classList.toggle('bg-Ragnar-600', on); el.classList.toggle('text-white', on);
        el.classList.toggle('text-slate-300', !on && !el.disabled);
    });
    document.querySelectorAll('#wifi-fs-view button').forEach(el => {
        const on = el.dataset.view === v;
        el.classList.toggle('wifi-hm-seg-on', on); el.classList.toggle('wifi-hm-seg-off', !on);
    });
    // Enter/leave the live SDR waterfall (a separate capture pipeline).
    if (v === 'waterfall' && prev !== 'waterfall') _wifiSdrStart();
    else if (v !== 'waterfall' && prev === 'waterfall') _wifiSdrStop();
    if (v === 'waterfall') _wifiDrawWaterfall();
    else if (_wifiState.data) _wifiDrawSpectrum();
}

// ---- Canvas interaction: hover to identify, click to inspect ---------------
// Both spectrum surfaces are hit-tested against the boxes recorded during the
// draw, so a pixel maps back to the AP that is drawn there.
function _wifiWireCanvas(canvas, tipId, readoutId) {
    if (!canvas || canvas._wifiWired) return;
    canvas._wifiWired = true;
    const tip = tipId ? document.getElementById(tipId) : null;
    const readout = readoutId ? document.getElementById(readoutId) : null;
    const at = (e) => {
        const r = canvas.getBoundingClientRect();
        return { x: e.clientX - r.left, y: e.clientY - r.top };
    };
    canvas.addEventListener('mousemove', (e) => {
        const p = at(e);
        const hit = _wifiHitTest(canvas, p.x, p.y);
        const ap = hit && (_wifiState.data.aps || []).find(a => a.bssid === hit.bssid);
        canvas.style.cursor = ap ? 'pointer' : 'crosshair';
        if (readout) {
            readout.textContent = _wifiCursorReadout(canvas, p.x, p.y);
            readout.style.visibility = readout.textContent ? 'visible' : 'hidden';
        }
        if (tip) {
            if (ap) {
                tip.innerHTML = _wifiTipHtml(ap);
                tip.classList.remove('hidden');
                // Keep the tip inside the canvas box (the tip is positioned in
                // the canvas's own coordinate space, scroll included).
                const w = tip.offsetWidth, h = tip.offsetHeight;
                const maxX = canvas.clientWidth - w - 6;
                tip.style.left = Math.max(4, Math.min(maxX, p.x + 14)) + 'px';
                tip.style.top = Math.max(4, p.y - h - 12) + 'px';
            } else tip.classList.add('hidden');
        }
        if ((ap ? ap.bssid : null) !== _wifiState.hoverBssid) {
            _wifiState.hoverBssid = ap ? ap.bssid : null;
            if (_wifiState.view !== 'waterfall' && _wifiState.data) _wifiDrawSpectrum();
        }
    });
    canvas.addEventListener('mouseleave', () => {
        if (tip) tip.classList.add('hidden');
        if (readout) { readout.textContent = ''; readout.style.visibility = 'hidden'; }
        if (_wifiState.hoverBssid) {
            _wifiState.hoverBssid = null;
            if (_wifiState.view !== 'waterfall' && _wifiState.data) _wifiDrawSpectrum();
        }
    });
    canvas.addEventListener('click', (e) => {
        const p = at(e);
        const hit = _wifiHitTest(canvas, p.x, p.y);
        if (hit) wifiSelectAp(hit.bssid);
        else if (_wifiState.selected) { _wifiState.selected = null; wifiRender(); }
    });
}

function _wifiHitTest(canvas, x, y) {
    const hits = (canvas && canvas._wifiHits) || [];
    if (!_wifiState.data) return null;
    // Reverse: hits are pushed weakest-first, so the last match is the one
    // drawn on top at this pixel.
    for (let i = hits.length - 1; i >= 0; i--) {
        const h = hits[i];
        if (x >= h.x0 && x <= h.x1 && y >= h.y0 && y <= h.y1) return h;
    }
    return null;
}

// "ch 6.4 · 2437 MHz · −72 dBm" for the cursor position — a spectrum-analyzer
// style marker readout.
function _wifiCursorReadout(canvas, x, y) {
    const g = canvas && canvas._wifiGeom;
    if (!g || x < g.padL || x > g.W - g.padR || y < g.padT || y > g.H - g.padB) return '';
    const band = g.bands.find(b => x >= g.ranges[b].x0 && x <= g.ranges[b].x1);
    const dbm = Math.round(g.dbmFor(y));
    if (!band) return `${dbm} dBm`;
    const ch = g.chFor(band, x);
    const mhz = band === '2.4' ? Math.round(2407 + ch * 5)
        : band === '6' ? Math.round(5950 + ch * 5) : Math.round(5000 + ch * 5);
    return `${band} GHz · ch ${ch.toFixed(1)} · ${mhz} MHz · ${dbm} dBm`;
}

function _wifiTipHtml(a) {
    const col = _wifiSignalColor(a.signal);
    const issue = (a.security_findings || []).length;
    return `<div><b>${_esc(a.ssid) || '<i>hidden</i>'}</b>${_wifiGenBadge(a.standard)}</div>
        <div class="k" style="font-family:ui-monospace,monospace">${_esc(a.bssid)}</div>
        <div><span class="k">${_esc(a.vendor) || 'unknown vendor'}</span></div>
        <div><b style="color:${col}">${a.signal} dBm</b>${a.snr != null ? ' <span class="k">SNR ' + a.snr + ' dB</span>' : ''}
             · ${a.band} GHz ch ${a.channel} · ${a.width} MHz${a.dfs ? ' <span style="color:#a78bfa">◆DFS</span>' : ''}</div>
        <div><span class="k">${_esc(a.security)}</span>${a.channel_util != null ? ' <span class="k">· util ' + a.channel_util + '%</span>' : ''}</div>
        ${issue ? `<div style="color:#fbbf24">⚠ ${_esc(a.security_findings.join('; '))}</div>` : ''}
        <div class="k" style="margin-top:3px">click to inspect</div>`;
}

function _wifiFillIfaces() {
    fetch('/api/net/wifi/interfaces').then(r => r.json()).then(d => {
        const sel = document.getElementById('wifi-iface');
        const ifs = (d && d.interfaces) || [];
        if (!ifs.length) { sel.innerHTML = '<option value="">No wireless interface</option>'; return; }
        // Prefer the radio that supports the most bands (the Alfa 6E dongle)
        ifs.sort((a, b) => (b.bands || []).length - (a.bands || []).length);
        sel.innerHTML = ifs.map(i =>
            `<option value="${i.iface}">${i.iface} (${(i.bands || []).join('/') || '?'} GHz)</option>`).join('');
        if (!_wifiState.iface || !ifs.some(i => i.iface === _wifiState.iface)) _wifiState.iface = ifs[0].iface;
        sel.value = _wifiState.iface;
        sel.onchange = () => { _wifiState.iface = sel.value; wifiScan(); };
        if (!_wifiState.data) wifiScan();
    }).catch(() => {});
}

function wifiScan() {
    const iface = _wifiState.iface || document.getElementById('wifi-iface').value;
    if (!iface) return;
    const btn = document.getElementById('wifi-scan-btn');
    const fsBtn = document.getElementById('wifi-fs-scan');
    const busy = (on) => { if (btn) btn.disabled = on; if (fsBtn) fsBtn.disabled = on; };
    _wifiSetStatus('Scanning (passive)…'); busy(true);
    fetch(`/api/net/wifi/scan?interface=${encodeURIComponent(iface)}&band=${_wifiState.band}`)
        .then(r => r.json()).then(d => {
            busy(false);
            if (d.error) { _wifiSetStatus('⚠ ' + d.error); return; }
            _wifiState.data = d;
            _wifiSetStatus(`${d.ap_count} AP(s) · ${new Date(d.timestamp * 1000).toLocaleTimeString()}`);
            wifiRender();
        }).catch(e => { busy(false); _wifiSetStatus('Scan failed'); });
}

// Professional AI assessment of the current connection + RF environment. Uses
// the latest scan (runs one first if needed), then POSTs it to the AI route.
async function wifiAnalyzeAI() {
    const panel = document.getElementById('wifi-ai-panel');
    const content = document.getElementById('wifi-ai-content');
    const status = document.getElementById('wifi-ai-status');
    const btn = document.getElementById('wifi-ai-btn');
    panel.classList.remove('hidden');
    if (btn) btn.disabled = true;
    status.textContent = '';
    try {
        // Ensure we have scan data (the AI reasons over the AP list).
        if (!_wifiState.data || !(_wifiState.data.aps || []).length) {
            content.innerHTML = '<span class="text-gray-400">Scanning first…</span>';
            const iface = _wifiState.iface || document.getElementById('wifi-iface').value;
            const r = await fetch(`/api/net/wifi/scan?interface=${encodeURIComponent(iface)}&band=${_wifiState.band}`);
            const d = await r.json();
            if (!d.error) { _wifiState.data = d; wifiRender(); }
        }
        content.innerHTML = '<span class="text-gray-400">Analyzing your connection and the RF environment…</span>';
        const resp = await fetch('/api/ai/wifi-analyze', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ scan: _wifiState.data || {} })
        });
        const d = await resp.json();
        if (d.enabled === false) {
            content.innerHTML = '<span class="text-amber-400">' + _esc(d.message || 'AI is not enabled.') + '</span>';
            return;
        }
        if (d.error) { content.innerHTML = '<span class="text-red-400">⚠ ' + _esc(d.error) + '</span>'; return; }
        content.innerHTML = formatAIText(d.analysis || 'No analysis returned.');
        const c = d.connected;
        status.textContent = c
            ? `${c.ssid || c.bssid} · ${c.band || '?'} GHz ch ${c.channel ?? '?'} · ${d.context ? d.context.co_channel_count + ' co-channel' : ''}`
            : 'not associated — analyzed the environment';
    } catch (e) {
        content.innerHTML = '<span class="text-red-400">AI analysis failed.</span>';
    } finally {
        if (btn) btn.disabled = false;
    }
}

// Open a printable HTML report in a new tab. POSTs the scan data the panel
// already holds to a render endpoint (no re-scan), then writes the returned
// self-contained HTML into the new window so the user can Save-as-PDF.
function _openScanReport(url, scan, emptyMsg) {
    // A WIDS capture is valid even with zero APs (a genuinely clear airspace),
    // so accept anything carrying a threat verdict; the spectrum survey needs APs.
    const hasData = !!scan && (('threat' in scan) || (Array.isArray(scan.aps) && scan.aps.length > 0));
    if (!hasData) { alert(emptyMsg); return; }
    const w = window.open('', '_blank');
    if (w) w.document.write('<!DOCTYPE html><title>Generating report…</title>'
        + '<body style="font-family:system-ui,sans-serif;padding:2rem;color:#334">Generating report…</body>');
    fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' },
                 body: JSON.stringify({ scan }) })
        .then(r => r.text())
        .then(html => { if (w) { w.document.open(); w.document.write(html); w.document.close(); } })
        .catch(() => { if (w) { try { w.document.body.textContent = 'Report generation failed.'; } catch (e) {} } });
}

// Printable Wi-Fi spectrum & channel report from the current scan.
function wifiExportReport() {
    _openScanReport('/api/net/wifi/report', _wifiState.data,
        'Run a spectrum scan first, then export the report.');
}

// One auto-refresh tick: the Wi-Fi survey plus any enabled overlays. The
// Waterfall view streams on its own poll, so it's left alone here.
function _wifiAutoTick() {
    if (_wifiState.view !== 'waterfall') wifiScan();
    if (_wifiState.btOn) wifiBtScan();
    if (_wifiState.zbOn && _wifiState.zbAvailable) wifiZbScan();
}

// ---- Bluetooth / BLE 2.4 GHz overlay ---------------------------------------
const _BT_KIND = { le: { c: '#38bdf8', t: 'BLE' }, classic: { c: '#818cf8', t: 'Classic' },
    dual: { c: '#a78bfa', t: 'Dual' } };
const _BT_PRESSURE_COLOR = { low: '#64748b', moderate: '#f59e0b', high: '#ef4444' };

function wifiBtScan() {
    if (_wifiState.btBusy) return;
    _wifiState.btBusy = true;
    const st = document.getElementById('wifi-bt-status');
    if (st) st.textContent = 'Discovering (receive-only)…';
    fetch('/api/net/bt/scan?duration=12')
        .then(r => r.json()).then(d => {
            _wifiState.btBusy = false;
            if (d.error) { if (st) st.textContent = '⚠ ' + d.error; _wifiState.bt = null; return; }
            _wifiState.bt = d;
            // Drop a selection that dropped out of range this scan.
            if (_wifiState.btSelected && !(d.devices || []).some(v => v.mac === _wifiState.btSelected))
                _wifiState.btSelected = null;
            const i = d.interference || {};
            if (st) st.textContent = `${d.device_count} BT/BLE · ${d.controller || '?'}` +
                (d.capture === 'bluetoothctl' ? ' (fallback)' : '');
            _wifiBtRender();
            _wifiFsRenderSide();
            if (_wifiState.data) _wifiDrawSpectrum();
        }).catch(() => { _wifiState.btBusy = false; if (st) st.textContent = 'BT scan failed'; });
}

function _wifiBtRender() {
    const d = _wifiState.bt; if (!d) return;
    const i = d.interference || {};
    const sum = document.getElementById('wifi-bt-summary');
    if (sum) sum.textContent = `${i.le_count || 0} BLE · ${i.classic_count || 0} Classic · ${i.strong_count || 0} close`;
    const note = document.getElementById('wifi-bt-note');
    if (note) note.textContent = (i.note || '') + '  ' + (d.coexistence_note || '');
    // Per-Wi-Fi-channel BT pressure chips
    const pr = document.getElementById('wifi-bt-pressure');
    if (pr) pr.innerHTML = (i.wifi_channels || []).map(c => {
        const col = _BT_PRESSURE_COLOR[c.level] || '#64748b';
        return `<span class="px-1.5 py-0.5 rounded" style="background:${col}22;color:${col};border:1px solid ${col}55" title="Estimated BT pressure on Wi-Fi ch ${c.wifi_channel}">ch${c.wifi_channel}: ${c.level}</span>`;
    }).join('');
    // Device table (strongest first, already sorted server-side)
    const tb = document.getElementById('wifi-bt-tbody');
    if (!tb) return;
    if (!d.devices.length) {
        tb.innerHTML = '<tr><td colspan="5" class="py-3 text-gray-500">No Bluetooth devices in range.</td></tr>';
        return;
    }
    tb.innerHTML = d.devices.map(v => {
        const k = _BT_KIND[v.kind] || { c: '#94a3b8', t: v.kind || '?' };
        const name = v.name || '<span class="text-gray-600">(no name)</span>';
        const cls = v.major_class ? v.major_class + (v.services && v.services.length ? ` · ${v.services.join(', ')}` : '') : '—';
        const rssi = (v.rssi == null) ? '—' : `${v.rssi}`;
        const rcol = (v.rssi == null) ? '#64748b' : _wifiSignalColor(v.rssi);
        const sel = _wifiState.btSelected === v.mac;
        return `<tr class="border-b border-slate-800/60 cursor-pointer hover:bg-slate-800/40${sel ? ' bg-sky-500/15' : ''}" onclick="wifiBtSelect('${v.mac}')" title="Click to highlight this device on the spectrum">
            <td class="py-1 pr-3">${sel ? '<span class="text-sky-400">▸</span> ' : ''}${name}<div class="text-[10px] text-gray-600 font-mono">${v.mac}</div></td>
            <td class="py-1 pr-3"><span style="color:${k.c}">${k.t}</span>${v.randomized ? ' <span class="text-[9px] text-gray-500">rnd</span>' : ''}</td>
            <td class="py-1 pr-3">${v.vendor || '—'}</td>
            <td class="py-1 pr-3">${cls}</td>
            <td class="py-1 pr-3 text-right font-mono" style="color:${rcol}">${rssi}</td>
        </tr>`;
    }).join('');
}

// Click a BT device row → highlight it on the 2.4 GHz spectrum (toggle off if
// the same row is clicked again). Mirrors the Wi-Fi AP select behaviour.
function wifiBtSelect(mac) {
    _wifiState.btSelected = (_wifiState.btSelected === mac) ? null : mac;
    _wifiFsRenderSide();
    _wifiBtRender();
    if (_wifiState.data) _wifiDrawSpectrum();
}

// ---- Zigbee / 802.15.4 overlay (via an on-demand Huginn sniff) -------------
// The Zigbee toggle stays greyed until a HuginnESP companion is on USB.
function _wifiZbCheck() {
    fetch('/api/net/zigbee/status').then(r => r.json()).then(st => {
        const ok = !!(st && st.available);
        _wifiState.zbAvailable = ok;
        const chk = document.getElementById('wifi-zb'), lab = document.getElementById('wifi-zb-label');
        if (chk) chk.disabled = !ok;
        if (lab) {
            lab.classList.toggle('opacity-40', !ok);
            lab.classList.toggle('cursor-not-allowed', !ok);
            lab.classList.toggle('cursor-pointer', ok);
            lab.classList.toggle('text-gray-400', ok);
            lab.title = ok ? 'Sniff Zigbee / 802.15.4 with the connected HuginnESP'
                : (st && st.error ? st.error : 'Connect a HuginnESP (ESP32-C5) companion to sniff Zigbee');
        }
        _wifiFsSyncGates();
    }).catch(() => {});
}

function wifiZbScan() {
    if (_wifiState.zbBusy) return;
    _wifiState.zbBusy = true;
    const st = document.getElementById('wifi-zb-status');
    if (st) st.textContent = 'Sniffing 802.15.4 (ch 11–26)…';
    fetch('/api/net/zigbee/scan?duration=8').then(r => r.json()).then(d => {
        _wifiState.zbBusy = false;
        if (d.error) { if (st) st.textContent = '⚠ ' + d.error; _wifiState.zb = null; if (_wifiState.data) _wifiDrawSpectrum(); return; }
        _wifiState.zb = d;
        if (_wifiState.zbSelected && !(d.devices || []).some(v => (v.addr || v.short_addr) === _wifiState.zbSelected))
            _wifiState.zbSelected = null;
        const i = d.interference || {};
        if (st) st.textContent = `${d.device_count} device(s) · ${i.channel_count || 0} ch` + (d.warning ? ' ⚠' : '');
        _wifiZbRender();
        _wifiFsRenderSide();
        if (_wifiState.data) _wifiDrawSpectrum();
    }).catch(() => { _wifiState.zbBusy = false; if (st) st.textContent = 'Zigbee scan failed'; });
}

function _wifiZbRender() {
    const d = _wifiState.zb; if (!d) return;
    const i = d.interference || {};
    const sum = document.getElementById('wifi-zb-summary');
    if (sum) sum.textContent = `${i.device_count || 0} device(s) · ${i.channel_count || 0} channel(s) · ${i.strong_count || 0} close`;
    const note = document.getElementById('wifi-zb-note');
    if (note) note.textContent = (i.note || '') + '  ' + (d.companion_note || '');
    const pr = document.getElementById('wifi-zb-pressure');
    if (pr) pr.innerHTML = (i.wifi_channels || []).map(c => {
        const col = _BT_PRESSURE_COLOR[c.level] || '#64748b';
        return `<span class="px-1.5 py-0.5 rounded" style="background:${col}22;color:${col};border:1px solid ${col}55" title="Estimated Zigbee pressure on Wi-Fi ch ${c.wifi_channel}">ch${c.wifi_channel}: ${c.level}</span>`;
    }).join('');
    const tb = document.getElementById('wifi-zb-tbody');
    if (!tb) return;
    if (!d.devices.length) {
        tb.innerHTML = '<tr><td colspan="6" class="py-3 text-gray-500">No Zigbee / 802.15.4 devices heard this sweep.</td></tr>';
        return;
    }
    tb.innerHTML = d.devices.map(v => {
        const id = v.addr || v.short_addr;
        const sel = _wifiState.zbSelected === id;
        const rssi = (v.rssi == null) ? '—' : `${v.rssi}`;
        const rcol = (v.rssi == null) ? '#64748b' : _wifiSignalColor(v.rssi);
        const pcol = v.proto === 'Thread' ? '#f472b6' : v.proto === 'Zigbee' ? '#fbbf24' : '#94a3b8';
        return `<tr class="border-b border-slate-800/60 cursor-pointer hover:bg-slate-800/40${sel ? ' bg-amber-500/15' : ''}" onclick="wifiZbSelect('${id}')" title="Click to highlight on the spectrum">
            <td class="py-1 pr-3">${sel ? '<span class="text-amber-400">▸</span> ' : ''}<span class="font-mono text-[10px]">${id}</span></td>
            <td class="py-1 pr-3"><span style="color:${pcol}">${v.proto}</span></td>
            <td class="py-1 pr-3">${v.channel != null ? v.channel : '—'}</td>
            <td class="py-1 pr-3 font-mono text-[10px]">${v.panid || '—'}</td>
            <td class="py-1 pr-3">${v.vendor || '—'}</td>
            <td class="py-1 pr-3 text-right font-mono" style="color:${rcol}">${rssi}</td>
        </tr>`;
    }).join('');
}

function wifiZbSelect(id) {
    _wifiState.zbSelected = (_wifiState.zbSelected === id) ? null : id;
    _wifiFsRenderSide();
    _wifiZbRender();
    if (_wifiState.data) _wifiDrawSpectrum();
}

// ---- True-RF waterfall (HackRF SDR) ----------------------------------------
// The Waterfall button stays greyed out until the backend actually sees a
// HackRF; this polls detection and enables/labels the button accordingly.
function _wifiSdrCheck() {
    fetch('/api/net/sdr/status').then(r => r.json()).then(st => {
        const det = (st && st.detect) || {};
        _wifiState.sdr.available = !!det.available;
        const btn = document.getElementById('wifi-view-wf');
        if (!btn) return;
        btn.disabled = !det.available;
        const off = !det.available;
        // Disabled = clearly greyed + transparent (no hover tooltip on touch).
        btn.classList.toggle('cursor-not-allowed', off);
        btn.classList.toggle('opacity-40', off);
        btn.classList.toggle('text-slate-500', off);
        if (off) { btn.classList.remove('hover:bg-slate-700', 'text-slate-300'); }
        else if (_wifiState.view !== 'waterfall') { btn.classList.add('hover:bg-slate-700', 'text-slate-300'); }
        btn.title = det.available
            ? `HackRF ready${det.board ? ' (' + det.board + ')' : ''} — true-RF waterfall`
            : (det.error || 'Connect a HackRF SDR to enable true-RF waterfall');
        _wifiFsSyncGates();
    }).catch(() => {});
}

function _wifiSdrStart() {
    const s = _wifiState.sdr;
    if (!s.available) { _wifiDrawWaterfall(); return; }
    s.rows = []; s.seq = 0; s.maxhold = null; s.error = null;
    // Match the SDR band to the analyzer's band selector where it's a real RF
    // band (2.4/5); 'all'/'6' fall back to 2.4.
    s.band = (_wifiState.band === '5') ? '5' : '2.4';
    fetch('/api/net/sdr/start', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ band: s.band }) })
        .then(r => r.json()).then(res => {
            if (res && res.error) { s.error = res.error; _wifiDrawWaterfall(); return; }
            if (s.poll) clearInterval(s.poll);
            s.running = true;
            s.poll = setInterval(_wifiSdrPoll, 400);
        }).catch(() => { s.error = 'Failed to start SDR'; _wifiDrawWaterfall(); });
}

function _wifiSdrStop() {
    const s = _wifiState.sdr;
    if (s.poll) { clearInterval(s.poll); s.poll = null; }
    s.running = false;
    fetch('/api/net/sdr/stop', { method: 'POST' }).catch(() => {});
}

function _wifiSdrPoll() {
    const s = _wifiState.sdr;
    fetch('/api/net/sdr/frames?since=' + s.seq).then(r => r.json()).then(d => {
        if (d.error) s.error = d.error;
        if (d.band_mhz) s.bandMhz = d.band_mhz;
        if (typeof d.floor_dbm === 'number') s.floor = d.floor_dbm;
        if (d.max_hold) s.maxhold = d.max_hold;
        (d.frames || []).forEach(f => { s.seq = f.seq; s.rows.unshift(f.power); });
        if (s.rows.length > 260) s.rows.length = 260;
        if (_wifiState.view === 'waterfall') _wifiDrawWaterfall();
    }).catch(() => {});
}

// Power (dBm) → waterfall colour: dark → blue → cyan → green → yellow → red.
function _wifiSdrColor(dbm, floor) {
    const top = -20, lo = (typeof floor === 'number' ? floor : -110);
    let t = (dbm - lo) / (top - lo);
    t = Math.max(0, Math.min(1, t));
    const stops = [[8, 12, 30], [30, 60, 170], [30, 190, 200], [40, 200, 70], [235, 220, 40], [235, 60, 40]];
    const seg = t * (stops.length - 1), i = Math.floor(seg), f = seg - i;
    const a = stops[i], b = stops[Math.min(stops.length - 1, i + 1)];
    return `rgb(${Math.round(a[0] + (b[0] - a[0]) * f)},${Math.round(a[1] + (b[1] - a[1]) * f)},${Math.round(a[2] + (b[2] - a[2]) * f)})`;
}

// The live-RF view: a spectrum line (current + max-hold) above a scrolling
// time × frequency × power waterfall, with Wi-Fi channel + BT markers overlaid.
function _wifiDrawWaterfall() {
    _wifiDrawWaterfallInto(document.getElementById('wifi-spectrum'), 360);
    if (_wifiState.fs.open) {
        const c = document.getElementById('wifi-spectrum-fs');
        if (c) _wifiDrawWaterfallInto(c, c.clientHeight);
    }
}

function _wifiDrawWaterfallInto(canvas, height) {
    if (!canvas) return;
    const s = _wifiState.sdr;
    const dpr = window.devicePixelRatio || 1;
    const W = canvas.clientWidth, H = Math.round(height || canvas.clientHeight || 360);
    if (W < 20 || H < 20) return;
    canvas._wifiHits = []; canvas._wifiGeom = null;   // no AP hit-testing in this view
    canvas.width = W * dpr; canvas.height = H * dpr;
    const ctx = canvas.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const padL = 44, padR = 12, padT = 14, padB = 26;
    const plotW = W - padL - padR;
    // Top spectrum-line panel — grows with the canvas so the full-screen
    // console doesn't leave it a thin sliver over a huge waterfall.
    const specH = Math.max(96, Math.min(240, Math.round(H * 0.28))), gap = 8;
    const wfTop = padT + specH + gap, wfH = H - padB - wfTop;
    const lo = s.bandMhz ? s.bandMhz[0] : (s.band === '5' ? 5150 : 2400);
    const hi = s.bandMhz ? s.bandMhz[1] : (s.band === '5' ? 5895 : 2500);

    // Not ready / not running → explain why (keeps the blind path honest).
    if (!s.available || s.error || !s.rows.length) {
        ctx.fillStyle = '#0b1220'; ctx.fillRect(padL, wfTop, plotW, wfH);
        ctx.fillStyle = '#64748b'; ctx.font = '13px sans-serif'; ctx.textAlign = 'center';
        const msg = !s.available ? '📡 Connect a HackRF SDR to see the true-RF waterfall'
            : s.error ? ('⚠ ' + s.error)
            : 'Starting HackRF sweep…';
        ctx.fillText(msg, W / 2, wfTop + wfH / 2);
        if (!s.available) {
            ctx.font = '11px sans-serif'; ctx.fillStyle = '#475569';
            ctx.fillText('Bar / Dome work from the passive Wi-Fi scan and need no SDR.', W / 2, wfTop + wfH / 2 + 20);
        }
        return;
    }

    const nb = s.rows[0].length;
    const xForBin = (bi) => padL + (bi + 0.5) / nb * plotW;
    const xForFreq = (mhz) => padL + (mhz - lo) / (hi - lo) * plotW;

    // --- Waterfall: newest row at the top, scrolling down ---
    const rowH = Math.max(1, wfH / Math.min(s.rows.length, Math.floor(wfH)));
    const colW = plotW / nb;
    for (let r = 0; r < s.rows.length; r++) {
        const y = wfTop + r * rowH;
        if (y > wfTop + wfH) break;
        const row = s.rows[r];
        for (let bi = 0; bi < nb; bi++) {
            ctx.fillStyle = _wifiSdrColor(row[bi], s.floor);
            ctx.fillRect(padL + bi * colW, y, Math.ceil(colW), Math.ceil(rowH));
        }
    }

    // --- Spectrum line panel: current frame + max-hold ---
    ctx.fillStyle = '#0b1220'; ctx.fillRect(padL, padT, plotW, specH);
    const sTop = -20, sBot = s.floor;
    const yFor = (db) => padT + (sTop - Math.max(sBot, Math.min(sTop, db))) / (sTop - sBot) * specH;
    // dB gridlines
    ctx.strokeStyle = '#1e293b'; ctx.fillStyle = '#475569'; ctx.font = '9px sans-serif'; ctx.textAlign = 'right';
    for (let v = sTop; v >= sBot; v -= 20) {
        const y = yFor(v); ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();
        ctx.fillText(v + '', padL - 3, y + 3);
    }
    const drawTrace = (arr, stroke, wdt) => {
        ctx.strokeStyle = stroke; ctx.lineWidth = wdt; ctx.beginPath();
        for (let bi = 0; bi < arr.length; bi++) {
            const x = xForBin(bi), y = yFor(arr[bi]);
            bi ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
        }
        ctx.stroke();
    };
    if (s.maxhold) drawTrace(s.maxhold, 'rgba(148,163,184,0.7)', 1);   // max-hold
    drawTrace(s.rows[0], '#22d3ee', 1.5);                             // live

    // --- Frequency axis + Wi-Fi channel & BT marker overlays ---
    ctx.strokeStyle = '#334155'; ctx.beginPath(); ctx.moveTo(padL, wfTop - 2); ctx.lineTo(W - padR, wfTop - 2); ctx.stroke();
    ctx.textAlign = 'center';
    const wifiCh = (s.band === '5')
        ? { 36: 5180, 40: 5200, 44: 5220, 48: 5240, 52: 5260, 100: 5500, 149: 5745, 157: 5785 }
        : { 1: 2412, 6: 2437, 11: 2462 };
    Object.entries(wifiCh).forEach(([ch, mhz]) => {
        if (mhz < lo || mhz > hi) return;
        const x = xForFreq(mhz);
        ctx.strokeStyle = 'rgba(52,211,153,0.25)'; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
        ctx.beginPath(); ctx.moveTo(x, wfTop); ctx.lineTo(x, wfTop + wfH); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle = '#34d399'; ctx.font = '9px sans-serif'; ctx.fillText('ch' + ch, x, wfTop - 4);
    });
    // BT advertising markers, only meaningful in 2.4 and when the overlay is on.
    if (_wifiState.btOn && _wifiState.bt && s.band === '2.4') {
        [2402, 2426, 2480].forEach((mhz, i) => {
            const x = xForFreq(mhz);
            ctx.strokeStyle = 'rgba(129,140,248,0.5)'; ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]);
            ctx.beginPath(); ctx.moveTo(x, wfTop); ctx.lineTo(x, wfTop + wfH); ctx.stroke(); ctx.setLineDash([]);
            ctx.fillStyle = '#c7d2fe'; ctx.font = 'bold 8px sans-serif'; ctx.fillText('BLE ' + [37, 38, 39][i], x, wfTop + wfH + 9);
        });
    }
    // Frequency ticks (GHz) along the very bottom
    ctx.fillStyle = '#64748b'; ctx.font = '9px sans-serif';
    const nTicks = 5;
    for (let t = 0; t <= nTicks; t++) {
        const mhz = lo + (hi - lo) * t / nTicks;
        ctx.fillText((mhz / 1000).toFixed(3), padL + plotW * t / nTicks, H - 6);
    }
    // Live badge
    ctx.fillStyle = '#22d3ee'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText(`● LIVE RF · ${s.band} GHz · HackRF`, padL + 2, padT + 10);
}

function _wifiGenBadge(std) {
    const map = { 'Wi-Fi 7': '#22d3ee', 'Wi-Fi 6E': '#34d399', 'Wi-Fi 6': '#34d399',
        'Wi-Fi 5': '#60a5fa', 'Wi-Fi 4': '#94a3b8', 'legacy': '#f87171' };
    if (!std) return '';
    const c = map[std] || '#94a3b8';
    return `<span class="text-[9px] px-1 rounded ml-1 align-middle" style="background:${c}22;color:${c};border:1px solid ${c}66">${std.replace('Wi-Fi ', 'Wi‑Fi ')}</span>`;
}

function _wifiSecBadges(a) {
    let b = '';
    if (a.enterprise) b += '<span class="text-[9px] px-1 rounded bg-blue-600/20 text-blue-300 ml-1">802.1X</span>';
    if (a.pmf === 'required') b += '<span class="text-[9px] px-1 rounded bg-green-600/20 text-green-300 ml-1" title="PMF required">PMF</span>';
    else if (a.pmf === 'disabled' && a.security !== 'Open') b += '<span class="text-[9px] px-1 rounded bg-amber-600/20 text-amber-300 ml-1" title="Protected Mgmt Frames off">PMF✗</span>';
    if (a.wps) b += '<span class="text-[9px] px-1 rounded bg-red-600/20 text-red-300 ml-1" title="WPS enabled">WPS</span>';
    const r = a.roaming || {};
    const rf = ['k', 'v', 'r'].filter(x => r[x]);
    if (rf.length) b += `<span class="text-[9px] px-1 rounded bg-slate-600/40 text-slate-300 ml-1" title="802.11 roaming">11${rf.join('/')}</span>`;
    return b;
}

function _wifiSparkline(hist, width, height) {
    if (!hist || hist.length < 2) return '';
    const w = width || 46, h = height || 12, n = hist.length;
    let lo = Math.min(...hist), hi = Math.max(...hist);
    if (hi - lo < 1) { lo -= 1; hi += 1; }
    const pts = hist.map((v, i) => {
        const x = (i / (n - 1)) * (w - 2) + 1;
        const y = h - 1 - ((v - lo) / (hi - lo)) * (h - 2);
        return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(' ');
    const last = hist[hist.length - 1];
    return `<svg width="${w}" height="${h}" class="inline-block align-middle ml-1" title="RSSI history ${lo}…${hi} dBm">
        <polyline points="${pts}" fill="none" stroke="${_wifiSignalColor(last)}" stroke-width="1" stroke-linejoin="round"/></svg>`;
}

function wifiRenderChanges() {
    const el = document.getElementById('wifi-changes');
    if (!el) return;
    const c = (_wifiState.data && _wifiState.data.changes) || {};
    const chips = [];
    (c.new_aps || []).forEach(a =>
        chips.push(`<span class="px-2 py-1 rounded bg-emerald-600/20 text-emerald-300 border border-emerald-700/50" title="${a.bssid}">＋ new: ${a.ssid || '<hidden>'} <span class="opacity-60">${a.band}G ch${a.channel} ${a.signal}dBm</span></span>`));
    (c.gone_aps || []).forEach(a =>
        chips.push(`<span class="px-2 py-1 rounded bg-slate-700/40 text-slate-400 border border-slate-600/50" title="${a.bssid}">－ gone: ${a.ssid || '<hidden>'}</span>`));
    (c.weakened || []).forEach(a =>
        chips.push(`<span class="px-2 py-1 rounded bg-amber-600/20 text-amber-300 border border-amber-700/50" title="${a.bssid} — ${a.drop}dB below its peak ${a.rssi_max}dBm">▼ weakened: ${a.ssid || '<hidden>'} <span class="opacity-60">${a.signal}dBm (−${a.drop})</span></span>`));
    el.innerHTML = chips.length
        ? `<span class="text-gray-500 self-center mr-1">Since last scan:</span>${chips.join('')}`
        : '';
}

function wifiSetApView(v) {
    _wifiState.apView = v;
    document.getElementById('wifi-view-aps').classList.toggle('bg-Ragnar-600', v === 'aps');
    document.getElementById('wifi-view-aps').classList.toggle('text-white', v === 'aps');
    document.getElementById('wifi-view-nets').classList.toggle('bg-Ragnar-600', v === 'nets');
    document.getElementById('wifi-view-nets').classList.toggle('text-white', v === 'nets');
    document.getElementById('wifi-ap-table').classList.toggle('hidden', v !== 'aps');
    document.getElementById('wifi-nets-view').classList.toggle('hidden', v !== 'nets');
    wifiRenderTable();
}

function wifiSort(key) {
    if (_wifiState.sortKey === key) _wifiState.sortDir *= -1;
    else { _wifiState.sortKey = key; _wifiState.sortDir = (key === 'ssid' || key === 'vendor') ? 1 : -1; }
    wifiRenderTable();
    _wifiFsRenderList();
}

// Filter + sort the survey the same way for every list that shows it (the
// in-page table and the full-screen console).
function _wifiFilterAps(q, std, issuesOnly) {
    const d = _wifiState.data; if (!d) return [];
    q = (q || '').toLowerCase();
    const aps = d.aps.filter(a =>
        (!q || (a.ssid || '').toLowerCase().includes(q) || (a.vendor || '').toLowerCase().includes(q) || a.bssid.includes(q))
        && (!issuesOnly || (a.security_findings && a.security_findings.length))
        && (!std || a.standard === std));
    const k = _wifiState.sortKey || 'signal', dir = _wifiState.sortDir || -1;
    return aps.slice().sort((x, y) => {
        let a = x[k], b = y[k];
        if (a == null) a = (typeof b === 'number') ? -9999 : '';
        if (b == null) b = (typeof a === 'number') ? -9999 : '';
        return (a < b ? -1 : a > b ? 1 : 0) * dir;
    });
}

function wifiRenderTable() {
    const d = _wifiState.data; if (!d) return;
    if (_wifiState.apView === 'nets') return wifiRenderNets();
    const aps = _wifiFilterAps(
        document.getElementById('wifi-ap-search').value,
        (document.getElementById('wifi-ap-std') || {}).value || '',
        document.getElementById('wifi-ap-issues').checked);
    const tb = document.getElementById('wifi-ap-tbody');
    document.getElementById('wifi-ap-count').textContent = `(${aps.length}/${d.ap_count})`;
    if (!aps.length) { tb.innerHTML = '<tr><td colspan="9" class="py-4 text-center text-gray-500">No APs match.</td></tr>'; return; }
    tb.innerHTML = aps.map(a => {
        const isSel = _wifiState.selected === a.bssid;
        const bar = a.signal == null ? 0 : Math.max(4, Math.min(100, (a.signal + 100) / 70 * 100));
        const issue = a.security_findings && a.security_findings.length;
        const flagged = _wifiState.flagged && _wifiState.flagged.bssid === a.bssid;
        // Selected row: inline Ragnar accent (custom-colour opacity classes aren't
        // in the prebuilt tailwind.css). Selection wins the left bar; WIDS red beats amber.
        const rowCls = isSel ? '' : 'hover:bg-slate-800/40' + (flagged ? ' border-l-2 border-l-red-500' : issue ? ' border-l-2 border-l-amber-500' : '');
        const rowStyle = isSel ? ' style="background-color:rgba(2,132,199,0.25);border-left:3px solid rgb(56,189,248)"' : '';
        const snr = a.snr != null ? `<span class="text-[10px] text-gray-500"> ${a.snr}dB</span>` : '';
        const rate = (a.nss ? a.nss + 'ss' : '') + (a.max_phy_mbps ? ' ' + (a.max_phy_mbps >= 1000 ? (a.max_phy_mbps / 1000).toFixed(1) + 'G' : a.max_phy_mbps + 'M') : '');
        const marker = isSel ? '<span style="color:rgb(56,189,248)" class="mr-0.5" title="selected — modelled in Signal Radius">►</span>' : '';
        return `<tr class="border-b border-slate-800/50 cursor-pointer ${rowCls}"${rowStyle} onclick="wifiSelectAp('${a.bssid}')">
            <td class="py-1 pr-2 whitespace-nowrap">${marker}${issue ? '<span title="' + a.security_findings.join('; ') + '" class="text-amber-400">⚠</span> ' : ''}${(a.ssid || '<span class=\'text-gray-500 italic\'>hidden</span>')}${_wifiGenBadge(a.standard)}${a.is_new ? ' <span class="text-[9px] px-1 rounded bg-emerald-600/30 text-emerald-300 align-middle" title="first seen this session">NEW</span>' : ''}${flagged ? ' <span class="text-[9px] px-1 rounded bg-red-600/30 text-red-300 align-middle" title="flagged by WiFi Defense">⚠ WIDS</span>' : ''}${a.dfs ? ' <span title="DFS/radar" style="color:#a78bfa">◆</span>' : ''}<div class="text-[10px] text-gray-600 font-mono">${a.bssid}${a.seen_count > 1 ? ' <span class="text-gray-700">·seen ' + a.seen_count + '×</span>' : ''}</div></td>
            <td class="py-1 pr-2 text-xs text-gray-400 whitespace-nowrap">${a.vendor || '—'}</td>
            <td class="py-1 pr-2"><span style="color:${_WIFI_BAND_COLOR[a.band]}">${a.band}</span></td>
            <td class="py-1 pr-2">${a.channel}</td>
            <td class="py-1 pr-2">${a.width}M</td>
            <td class="py-1 pr-2 text-xs whitespace-nowrap">${rate || '—'}</td>
            <td class="py-1 pr-2 whitespace-nowrap"><span style="color:${_wifiSignalColor(a.signal)}">${a.signal}</span>${snr}<span style="display:inline-block;height:6px;width:${bar}px;max-width:50px;background:${_wifiSignalColor(a.signal)};border-radius:2px;margin-left:4px"></span>${_wifiSparkline(a.rssi_history)}</td>
            <td class="py-1 pr-2 text-xs whitespace-nowrap ${a.security === 'Open' ? 'text-red-400' : 'text-gray-300'}">${a.security}${_wifiSecBadges(a)}</td>
            <td class="py-1 pr-2">${a.channel_util == null ? '—' : a.channel_util + '%'}</td>
        </tr>`;
    }).join('');
}

function wifiRenderNets() {
    const d = _wifiState.data; if (!d || !d.groups) return;
    const q = (document.getElementById('wifi-ap-search').value || '').toLowerCase();
    const std = (document.getElementById('wifi-ap-std') || {}).value || '';
    let nets = d.groups.networks.filter(n =>
        (!q || n.ssid.toLowerCase().includes(q)) && (!std || n.standard === std));
    const el = document.getElementById('wifi-nets-view');
    document.getElementById('wifi-ap-count').textContent = `(${nets.length} networks · ${d.groups.device_count} devices)`;
    el.innerHTML = nets.map(n => `<div class="flex items-center justify-between gap-2 py-1.5 border-b border-slate-800/50">
        <div class="min-w-0"><span class="font-medium">${n.ssid}</span>${_wifiGenBadge(n.standard)}
            <div class="text-[10px] text-gray-500">${n.vendor || ''}</div></div>
        <div class="flex items-center gap-3 text-xs text-gray-400 shrink-0">
            <span>${n.bands.map(b => `<span style="color:${_WIFI_BAND_COLOR[b]}">${b}</span>`).join(' ')} GHz</span>
            <span>${n.ap_count} AP${n.ap_count > 1 ? 's' : ''}</span>
            <span>${n.security}</span>
            <span style="color:${_wifiSignalColor(n.best_signal)}">${n.best_signal}dBm</span>
        </div></div>`).join('') || '<div class="py-4 text-center text-gray-500">No networks.</div>';
}

function wifiExportCsv() {
    const d = _wifiState.data; if (!d) return;
    const cols = ['ssid', 'bssid', 'vendor', 'band', 'channel', 'width', 'standard', 'nss', 'max_phy_mbps', 'signal', 'snr', 'security', 'pmf', 'enterprise', 'wps', 'channel_util', 'tx_power_dbm', 'country'];
    const rows = [cols.join(',')].concat(d.aps.map(a => cols.map(c => {
        let v = a[c]; if (v == null) v = ''; v = String(v).replace(/"/g, '""');
        return /[",\n]/.test(v) ? `"${v}"` : v;
    }).join(',')));
    const blob = new Blob([rows.join('\n')], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `wifi-survey-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}.csv`;
    a.click(); URL.revokeObjectURL(url);
}

function _esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

function wifiExportReport() {
    const d = _wifiState.data;
    // Coverage stats from the current heatmap metric.
    const samples = (_wifiHm.data && _wifiHm.data.samples) || [];
    const vals = samples.map(_wifiHmValue).filter(v => v != null);
    const mName = (_WIFI_HM_METRICS[_wifiHm.metric] || {}).unit || '';
    let cov = '';
    if (vals.length) {
        const mn = Math.min(...vals), mx = Math.max(...vals), av = vals.reduce((a, b) => a + b, 0) / vals.length;
        cov = `<p><b>${samples.length}</b> survey points · ${_wifiHm.metric.toUpperCase()} min <b>${mn.toFixed(1)}</b> / avg <b>${av.toFixed(1)}</b> / max <b>${mx.toFixed(1)}</b> ${mName}</p>`;
    }
    // Design / build plan summary (walls, columns, planned mesh nodes).
    let plan = '';
    const pWalls = _wifiHm.walls || [], pCols = _wifiHm.columns || [], pAps = _wifiHm.predictAps || [];
    if (pWalls.length || pCols.length || pAps.length) {
        const tally = (arr) => {
            const m = {}; arr.forEach(o => { const k = o.material || 'wall'; m[k] = (m[k] || 0) + 1; });
            return Object.keys(m).map(k => `${m[k]}× ${_esc(k)}`).join(', ');
        };
        plan = '<ul>';
        if (pAps.length) plan += `<li><b>${pAps.length}</b> planned AP node${pAps.length > 1 ? 's' : ''} (predictive mesh)</li>`;
        if (pWalls.length) plan += `<li><b>${pWalls.length}</b> wall${pWalls.length > 1 ? 's' : ''}: ${tally(pWalls)}</li>`;
        if (pCols.length) plan += `<li><b>${pCols.length}</b> column${pCols.length > 1 ? 's' : ''}: ${tally(pCols)}</li>`;
        plan += '</ul>';
    }
    // Heatmap image, if drawn.
    let img = '';
    try {
        const cv = document.getElementById('wifi-heatmap');
        if (cv && (samples.length || _wifiHm.floorplan)) img = `<img src="${cv.toDataURL('image/png')}" style="max-width:100%;border:1px solid #ccc;border-radius:6px">`;
    } catch (e) { /* tainted canvas (cross-origin floorplan) — skip image */ }
    // Band summary.
    let bands = '';
    if (d && d.spectrum) {
        bands = '<ul>' + Object.keys(d.spectrum).sort().map(b => {
            const s = d.spectrum[b];
            return `<li><b>${b} GHz</b>: ${s.ap_count} APs · ${_esc(s.rating)} · best ch ${(s.recommend || []).join(', ')}</li>`;
        }).join('') + '</ul>';
    }
    // Interference.
    let intf = '';
    if (d && d.interference) {
        const co = d.interference.co_channel || [], ov = d.interference.adjacent_overlap || [];
        if (co.length) intf += '<p><b>Co-channel:</b> ' + co.slice(0, 8).map(g => `${g.band}GHz ch${g.channel} (${g.count} APs)`).join(', ') + '</p>';
        if (ov.length) intf += `<p><b>2.4 GHz overlap:</b> ${ov.length} overlapping pair(s) — use ch 1/6/11.</p>`;
        if (!intf) intf = '<p>No significant co-/adjacent-channel interference.</p>';
    }
    // AP inventory table.
    const aps = (d && d.aps) || [];
    const rows = aps.map(a => `<tr><td>${_esc(a.ssid) || '<i>hidden</i>'}</td><td class="mono">${_esc(a.bssid)}</td><td>${_esc(a.vendor) || '—'}</td><td>${a.band}</td><td>${a.channel}</td><td>${a.width}M</td><td>${a.signal}</td><td>${a.snr == null ? '—' : a.snr}</td><td>${_esc(a.security)}</td></tr>`).join('');
    const now = new Date();
    const issues = aps.filter(a => a.security_findings && a.security_findings.length);
    const html = `<!doctype html><html><head><meta charset="utf-8"><title>WiFi Survey Report</title>
<style>
  body{font:13px/1.5 -apple-system,Segoe UI,Roboto,sans-serif;color:#111;max-width:900px;margin:24px auto;padding:0 16px}
  h1{font-size:22px;margin:0 0 2px} h2{font-size:15px;margin:22px 0 6px;border-bottom:1px solid #ddd;padding-bottom:3px}
  .sub{color:#666;font-size:12px;margin-bottom:14px}
  table{border-collapse:collapse;width:100%;font-size:11.5px} th,td{border:1px solid #ddd;padding:3px 6px;text-align:left}
  th{background:#f4f4f5} .mono{font-family:ui-monospace,monospace;font-size:10.5px}
  .foot{margin-top:26px;color:#999;font-size:11px} @media print{body{margin:0}}
</style></head><body>
  <h1>WiFi Survey Report</h1>
  <div class="sub">${now.toLocaleString()} · interface ${_esc(_wifiState.iface || '—')} · ${aps.length} APs heard${_wifiHm.data && _wifiHm.data.target_ssid ? ' · target ' + _esc(_wifiHm.data.target_ssid) : ''}</div>
  ${cov ? '<h2>Coverage</h2>' + cov : ''}
  ${plan ? '<h2>Build plan</h2>' + plan : ''}
  ${img ? '<h2>Heatmap</h2>' + img : ''}
  ${bands ? '<h2>Bands &amp; channel plan</h2>' + bands : ''}
  ${intf ? '<h2>Interference</h2>' + intf : ''}
  ${issues.length ? '<h2>Security issues (' + issues.length + ')</h2><ul>' + issues.map(a => `<li><b>${_esc(a.ssid) || 'hidden'}</b> (${_esc(a.bssid)}): ${_esc(a.security_findings.join('; '))}</li>`).join('') + '</ul>' : ''}
  <h2>AP inventory</h2>
  <table><thead><tr><th>SSID</th><th>BSSID</th><th>Vendor</th><th>Band</th><th>Ch</th><th>Width</th><th>RSSI</th><th>SNR</th><th>Security</th></tr></thead><tbody>${rows}</tbody></table>
  <div class="foot">Generated by Ragnar WiFi Analyzer. Passive survey — estimates, not survey-grade measurements.</div>
  <script>window.onload=function(){setTimeout(function(){window.print();},250);};<\/script>
</body></html>`;
    const w = window.open('', '_blank');
    if (!w) { alert('Allow pop-ups to generate the report.'); return; }
    w.document.open(); w.document.write(html); w.document.close();
}

function wifiRender() {
    const d = _wifiState.data; if (!d) return;
    if (!_wifiState.apView) _wifiState.apView = 'aps';
    if (!_wifiState.sortKey) { _wifiState.sortKey = 'signal'; _wifiState.sortDir = -1; }
    // Band summary chips (+ noise floor + width advice)
    const summ = document.getElementById('wifi-band-summary');
    const ratingColor = { clear: '#22c55e', moderate: '#eab308', congested: '#ef4444' };
    let chips = Object.keys(d.spectrum).sort().map(b => {
        const s = d.spectrum[b];
        const wa = s.width_advice ? ` · <span title="${s.width_advice.reason}">→ ${s.width_advice.mhz}MHz</span>` : '';
        return `<span class="px-2 py-1 rounded" style="background:${_WIFI_BAND_COLOR[b]}22;border:1px solid ${_WIFI_BAND_COLOR[b]}66">
            <b style="color:${_WIFI_BAND_COLOR[b]}">${b} GHz</b> · ${s.ap_count} AP ·
            <span style="color:${ratingColor[s.rating]}">${s.rating}</span> · best ch ${s.recommend.join(', ')}${wa}</span>`;
    }).join('');
    if (d.noise_floor != null) chips += `<span class="px-2 py-1 rounded bg-slate-800 border border-slate-700">noise floor ${d.noise_floor} dBm</span>`;
    summ.innerHTML = chips || '<span class="text-gray-500">No APs heard.</span>';
    wifiRenderChanges();
    // Legend
    document.getElementById('wifi-legend').innerHTML =
        '<span>Signal:</span>' +
        [['#22c55e', 'strong'], ['#84cc16', 'good'], ['#eab308', 'fair'], ['#f97316', 'weak'], ['#ef4444', 'v.weak']]
            .map(([c, l]) => `<span class="flex items-center gap-1"><span style="width:10px;height:10px;background:${c};border-radius:2px;display:inline-block"></span>${l}</span>`).join('') +
        '<span class="ml-2">◆ DFS/radar</span><span>⚠ security issue</span>';
    wifiRenderTable();
    // Interference
    const inf = d.interference; const ip = document.getElementById('wifi-interference');
    let html = '';
    if (inf.co_channel.length) html += '<div class="mb-2"><b class="text-amber-400">Co-channel:</b><ul class="mt-1 space-y-0.5">' +
        inf.co_channel.slice(0, 6).map(g => `<li>${g.band}GHz ch${g.channel}: ${g.count} APs sharing (${g.ssids.slice(0, 3).join(', ')})</li>`).join('') + '</ul></div>';
    if (inf.adjacent_overlap.length) html += `<div><b class="text-orange-400">2.4GHz overlap:</b> ${inf.adjacent_overlap.length} overlapping pair(s) — use only ch 1/6/11.</div>`;
    if (!html) html = '<span class="text-green-400">No significant co-/adjacent-channel interference.</span>';
    ip.innerHTML = html;
    _wifiDrawSpectrum();
    _wifiFsRender();
    if (_wifiHm.mesh) wifiHeatmapPopulateSsids(); else wifiHeatmapPopulateAps();
    // WIDS pivot: once the flagged BSSID shows up in a survey, select it
    // (applied guards recursion — wifiSelectAp() re-enters wifiRender()).
    _wifiFlagBanner();
    const f = _wifiState.flagged;
    if (f && !f.applied && d.aps.some(a => a.bssid === f.bssid)) {
        f.applied = true;
        wifiSelectAp(f.bssid);
        _wifiFlagBanner();
    }
}

// Redraw every visible spectrum surface: the in-page chart and, when it's open,
// the full-screen console.
function _wifiDrawSpectrum() {
    _wifiDrawSpectrumInto(document.getElementById('wifi-spectrum'), { height: 360 });
    if (_wifiState.fs.open) {
        const c = document.getElementById('wifi-spectrum-fs');
        if (c) _wifiDrawSpectrumInto(c, { height: c.clientHeight, big: true });
    }
}

// Draw the passive survey into one canvas. The in-page chart and the
// full-screen console differ only in scale, so they share this — `big` bumps
// type and padding for the large surface. Every AP's plotted box is recorded on
// the canvas (`_wifiHits`) together with the plot geometry (`_wifiGeom`), which
// is what lets hover and click map a pixel back to a BSSID.
function _wifiDrawSpectrumInto(canvas, opts) {
    const d = _wifiState.data; if (!d || !canvas) return;
    const o = opts || {};
    const K = o.big ? 1.3 : 1;                    // type / padding scale
    const dpr = window.devicePixelRatio || 1;
    const W = canvas.clientWidth, H = Math.round(o.height || canvas.clientHeight || 360);
    if (W < 20 || H < 20) return;
    canvas.width = W * dpr; canvas.height = H * dpr;
    canvas._wifiHits = [];
    const ctx = canvas.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const padL = Math.round(40 * K), padR = Math.round(12 * K),
        padT = Math.round(16 * K), padB = Math.round(34 * K);
    const plotW = W - padL - padR, plotH = H - padT - padB;
    const yTop = -30, yBot = -95;
    const yFor = (dbm) => padT + (yTop - Math.max(yBot, Math.min(yTop, dbm))) / (yTop - yBot) * plotH;
    const dbmFor = (y) => yTop - (y - padT) / plotH * (yTop - yBot);
    // Y gridlines
    ctx.strokeStyle = '#1e293b'; ctx.fillStyle = '#64748b'; ctx.font = `${10 * K}px sans-serif`; ctx.textAlign = 'right';
    for (let v = yTop; v >= yBot; v -= 10) {
        const y = yFor(v); ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();
        ctx.fillText(v + '', padL - 4, y + 3);
    }
    if (o.big) {
        ctx.save(); ctx.translate(12, padT + plotH / 2); ctx.rotate(-Math.PI / 2);
        ctx.textAlign = 'center'; ctx.fillStyle = '#475569'; ctx.font = '11px sans-serif';
        ctx.fillText('RSSI (dBm)', 0, 0); ctx.restore();
    }
    // Which bands to show
    let bands = _wifiState.band === 'all' ? Object.keys(d.spectrum).sort() : [_wifiState.band];
    bands = bands.filter(b => d.aps.some(a => a.band === b));
    if (!bands.length) {
        ctx.fillStyle = '#64748b'; ctx.textAlign = 'center'; ctx.font = `${11 * K}px sans-serif`;
        ctx.fillText('No APs on selected band', W / 2, H / 2);
        canvas._wifiGeom = null;
        return;
    }
    // Per-band channel range + x segment
    const gap = Math.round(14 * K), segW = (plotW - gap * (bands.length - 1)) / bands.length;
    const ranges = {};
    bands.forEach((b, i) => {
        // The range has to cover the channels an AP actually *occupies*, not
        // just its centre — otherwise a 160 MHz BSS draws off the end of its
        // band segment and over the neighbouring one.
        const list = d.aps.filter(a => a.band === b);
        const edges = [];
        list.forEach(a => {
            const c = a.center_freq ? _wifiFreqToChannel(a.center_freq) : a.channel;
            const half = (a.width || 20) / 10;
            edges.push(a.channel, c - half, c + half);
        });
        let lo = Math.min(...edges), hi = Math.max(...edges);
        if (b === '2.4') { lo = Math.min(lo, 1); hi = Math.max(hi, 13); }
        const padCh = b === '2.4' ? 0.5 : 2;
        lo -= padCh; hi += padCh; if (hi - lo < 4) { hi += 2; lo -= 2; }
        const x0 = padL + i * (segW + gap);
        ranges[b] = { lo, hi, x0, x1: x0 + segW };
    });
    const xFor = (band, ch) => { const r = ranges[band]; return r.x0 + (ch - r.lo) / (r.hi - r.lo) * (r.x1 - r.x0); };
    const chFor = (band, x) => { const r = ranges[band]; return r.lo + (x - r.x0) / (r.x1 - r.x0) * (r.hi - r.lo); };
    // Band labels + channel ticks + DFS shading
    ctx.textAlign = 'center';
    bands.forEach(b => {
        const r = ranges[b];
        ctx.fillStyle = _WIFI_BAND_COLOR[b]; ctx.font = `bold ${11 * K}px sans-serif`;
        ctx.fillText(b + ' GHz', (r.x0 + r.x1) / 2, padT - 4);
        // DFS channel shading
        (d.radar_channels[b] || []).forEach(ch => {
            if (ch < r.lo || ch > r.hi) return;
            const cx = xFor(b, ch);
            ctx.fillStyle = 'rgba(167,139,250,0.08)';
            ctx.fillRect(cx - 3 * K, padT, 6 * K, plotH);
        });
        // Channel ticks (channels present)
        ctx.fillStyle = '#64748b'; ctx.font = `${9 * K}px sans-serif`;
        const present = [...new Set(d.aps.filter(a => a.band === b).map(a => a.channel))].sort((x, y) => x - y);
        present.forEach(ch => ctx.fillText(ch + '', xFor(b, ch), H - padB + 12 * K));
        if (o.big) {
            ctx.fillStyle = '#475569'; ctx.font = '10px sans-serif';
            ctx.fillText('channel', (r.x0 + r.x1) / 2, H - padB + 28);
        }
        if (bands.length > 1) { ctx.strokeStyle = '#334155'; ctx.beginPath(); ctx.moveTo(r.x1 + gap / 2, padT); ctx.lineTo(r.x1 + gap / 2, H - padB); ctx.stroke(); }
    });
    // Baseline
    ctx.strokeStyle = '#334155'; ctx.beginPath(); ctx.moveTo(padL, H - padB); ctx.lineTo(W - padR, H - padB); ctx.stroke();
    // Sort so weaker drawn first (stronger on top)
    const aps = [...d.aps].filter(a => bands.includes(a.band)).sort((a, b) => (a.signal || -999) - (b.signal || -999));
    aps.forEach(a => {
        const centerCh = a.center_freq ? _wifiFreqToChannel(a.center_freq) : a.channel;
        const half = a.width / 10;               // channel-number half-width
        const seg = ranges[a.band];
        const clamp = (x) => Math.max(seg.x0, Math.min(seg.x1, x));
        const xC = clamp(xFor(a.band, centerCh));
        const xL = clamp(xFor(a.band, centerCh - half)), xR = clamp(xFor(a.band, centerCh + half));
        const y = yFor(a.signal); const col = _wifiSignalColor(a.signal);
        const sel = _wifiState.selected === a.bssid;
        const hov = _wifiState.hoverBssid === a.bssid;
        // Pixel box → BSSID, for hover/click. Recorded in draw order, so a
        // reverse scan finds whatever is visually on top.
        canvas._wifiHits.push({ bssid: a.bssid, x0: Math.min(xL, xC - 2), x1: Math.max(xR, xC + 2), y0: y - 12, y1: H - padB });
        if (_wifiState.view === 'bar') {
            ctx.fillStyle = col + (sel ? 'ff' : hov ? 'ee' : 'cc');
            ctx.fillRect(xL, y, Math.max(3, xR - xL), (H - padB) - y);
            ctx.strokeStyle = sel || hov ? '#fff' : col; ctx.lineWidth = sel ? 2 : hov ? 1.5 : 1;
            ctx.strokeRect(xL, y, Math.max(3, xR - xL), (H - padB) - y);
        } else {
            // Dome: bell curve centred on channel, spanning its width
            ctx.beginPath(); ctx.moveTo(xL, H - padB);
            const steps = 28;
            for (let s = 0; s <= steps; s++) {
                const t = s / steps; const x = xL + (xR - xL) * t;
                const bell = Math.cos((t - 0.5) * Math.PI);   // 0..1..0
                const yy = (H - padB) - bell * ((H - padB) - y);
                ctx.lineTo(x, yy);
            }
            ctx.lineTo(xR, H - padB); ctx.closePath();
            const grad = ctx.createLinearGradient(0, y, 0, H - padB);
            grad.addColorStop(0, col + (sel ? 'cc' : hov ? '99' : '66')); grad.addColorStop(1, col + '08');
            ctx.fillStyle = grad; ctx.fill();
            ctx.strokeStyle = sel || hov ? '#fff' : col; ctx.lineWidth = sel ? 2.5 : hov ? 2 : 1.5; ctx.stroke();
        }
        // WIDS-flagged AP: red dashed locator line + outline so it stands out
        // even in a crowded band (highlight persists until dismissed).
        if (_wifiState.flagged && _wifiState.flagged.bssid === a.bssid) {
            ctx.save();
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1; ctx.setLineDash([5, 4]);
            ctx.beginPath(); ctx.moveTo(xC, padT); ctx.lineTo(xC, H - padB); ctx.stroke();
            ctx.lineWidth = 2; ctx.setLineDash([4, 3]);
            ctx.strokeRect(xL - 2, y - 2, Math.max(3, xR - xL) + 4, (H - padB) - y + 2);
            ctx.restore();
            ctx.fillStyle = '#f87171'; ctx.font = `bold ${10 * K}px sans-serif`; ctx.textAlign = 'center';
            ctx.fillText('⚠ WIDS', xC, y - 16 * K);
        }
        // Label the SSID at the peak — with the level and channel alongside it
        // on the big surface, where there's room to read them.
        const label = a.ssid || 'hidden';
        const cap = o.big ? 22 : 14;
        ctx.fillStyle = sel || hov ? '#fff' : '#cbd5e1';
        ctx.font = (sel || hov ? 'bold ' : '') + (10 * K) + 'px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText(label.length > cap ? label.slice(0, cap - 1) + '…' : label, xC, y - 4 * K);
        if (o.big) {
            ctx.fillStyle = col; ctx.font = '10px sans-serif';
            ctx.fillText(`${a.signal} dBm · ch${a.channel}/${a.width}`, xC, y - 17);
        }
    });
    canvas._wifiGeom = { bands, ranges, padL, padR, padT, padB, W, H, K, chFor, dbmFor };
    // Bluetooth / BLE overlay on the 2.4 GHz segment (device-activity estimate)
    if (_wifiState.btOn && _wifiState.bt && ranges['2.4']) {
        _wifiDrawBtOverlay(ctx, ranges['2.4'], xFor, { padT, padB, H, plotH, yFor });
    }
    // Zigbee / 802.15.4 overlay on the 2.4 GHz segment (device-activity estimate)
    if (_wifiState.zbOn && _wifiState.zb && ranges['2.4']) {
        _wifiDrawZbOverlay(ctx, ranges['2.4'], xFor, { padT, padB, H, plotH, yFor });
    }
}

// Draw Zigbee channel markers (11–26) on the 2.4 GHz segment: a labelled tick
// per occupied channel, intensity by activity, plus a selected-device RSSI line.
function _wifiDrawZbOverlay(ctx, r24, xFor, g) {
    const i = (_wifiState.zb.interference) || {};
    const baseY = g.H - g.padB;
    const zbX = (freqMhz) => {
        const chFrac = (freqMhz - 2407) / 5;
        return Math.max(r24.x0 + 2, Math.min(r24.x1 - 2, xFor('2.4', chFrac)));
    };
    const sel = _wifiState.zbSelected
        ? (_wifiState.zb.devices || []).find(v => (v.addr || v.short_addr) === _wifiState.zbSelected)
        : null;
    const dim = sel ? 0.35 : 1.0;
    // Per-channel markers (amber), height scaled by intensity.
    (i.markers || []).forEach(m => {
        if (!m.freq_mhz) return;
        const x = zbX(m.freq_mhz);
        const intensity = Math.max(0, Math.min(100, m.intensity || 0));
        const h = (g.plotH || (baseY - g.padT)) * (0.15 + 0.35 * intensity / 100);
        const yTop = baseY - h;
        ctx.strokeStyle = `rgba(251,191,36,${(0.35 + intensity / 100 * 0.5) * dim})`;
        ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(x, yTop); ctx.lineTo(x, baseY); ctx.stroke();
        ctx.fillStyle = `rgba(253,230,138,${dim})`; ctx.font = 'bold 9px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText('Z' + m.channel, x, yTop - 3);
        if (m.count > 1) ctx.fillText('×' + m.count, x, yTop + 9);
    });
    // Selected device: RSSI level line + emphasised marker on its channel.
    if (sel && sel.rssi != null && sel.freq_mhz) {
        const yR = g.yFor(sel.rssi);
        const col = _wifiSignalColor(sel.rssi);
        ctx.strokeStyle = col; ctx.lineWidth = 1.5; ctx.setLineDash([6, 4]);
        ctx.beginPath(); ctx.moveTo(r24.x0, yR); ctx.lineTo(r24.x1, yR); ctx.stroke(); ctx.setLineDash([]);
        const x = zbX(sel.freq_mhz);
        ctx.strokeStyle = col; ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.moveTo(x, yR); ctx.lineTo(x, baseY); ctx.stroke();
        ctx.fillStyle = col; ctx.beginPath(); ctx.arc(x, yR, 4, 0, 2 * Math.PI); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
        const nm = sel.vendor || sel.addr || sel.short_addr;
        ctx.fillStyle = '#fff'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'left';
        ctx.fillText(`${(nm || '').slice(0, 20)}  ${sel.proto} ch${sel.channel}  ${sel.rssi} dBm`, r24.x0 + 3, yR - 5);
    }
}

// Draw the BLE advertising-channel markers (37/38/39) and a band-wide
// "BT hopping activity" strip onto the 2.4 GHz segment of the spectrum. This is
// a device-activity overlay, not measured RF — labelled as such in the panel.
function _wifiDrawBtOverlay(ctx, r24, xFor, g) {
    const i = (_wifiState.bt.interference) || {};
    const baseY = g.H - g.padB;
    // 1) Band-wide hopping activity strip: height scales with hopping_pressure.
    const hp = Math.max(0, Math.min(100, i.hopping_pressure || 0));
    if (hp > 0) {
        const stripH = 6 + (hp / 100) * 26;
        const x0 = r24.x0, x1 = r24.x1;
        const grad = ctx.createLinearGradient(0, baseY - stripH, 0, baseY);
        grad.addColorStop(0, 'rgba(56,189,248,0.05)');
        grad.addColorStop(1, 'rgba(56,189,248,0.28)');
        ctx.fillStyle = grad;
        ctx.fillRect(x0, baseY - stripH, x1 - x0, stripH);
        // Diagonal hatch so it reads as "hopping", distinct from a solid AP bar.
        ctx.save();
        ctx.beginPath(); ctx.rect(x0, baseY - stripH, x1 - x0, stripH); ctx.clip();
        ctx.strokeStyle = 'rgba(56,189,248,0.25)'; ctx.lineWidth = 1;
        for (let x = x0 - stripH; x < x1; x += 7) {
            ctx.beginPath(); ctx.moveTo(x, baseY); ctx.lineTo(x + stripH, baseY - stripH); ctx.stroke();
        }
        ctx.restore();
        ctx.fillStyle = '#38bdf8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'left';
        ctx.fillText('BT hopping', x0 + 3, baseY - stripH - 3);
    }
    // The x-position of a BLE advertising channel on the 2.4 GHz segment.
    const advX = (freqMhz) => {
        const chFrac = (freqMhz - 2407) / 5;
        return Math.max(r24.x0 + 2, Math.min(r24.x1 - 2, xFor('2.4', chFrac)));
    };
    // A device is selected → fade the ambient markers so the selection pops.
    const sel = _wifiState.btSelected
        ? (_wifiState.bt.devices || []).find(v => v.mac === _wifiState.btSelected)
        : null;
    const dim = sel ? 0.35 : 1.0;
    // 2) BLE advertising-channel markers at 2402/2426/2480 MHz.
    (i.adv_markers || []).forEach(m => {
        const x = advX(m.freq_mhz);
        const intensity = Math.max(0, Math.min(100, m.intensity || 0));
        const alpha = (0.25 + (intensity / 100) * 0.5) * dim;
        ctx.strokeStyle = `rgba(129,140,248,${alpha})`; ctx.lineWidth = 2; ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(x, g.padT + 4); ctx.lineTo(x, baseY); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = `rgba(199,210,254,${dim})`; ctx.font = 'bold 9px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText('BLE ' + m.adv_channel, x, g.padT + 2);
    });
    // 3) Selected device: draw its RSSI level as a horizontal line across the
    // 2.4 GHz segment (its signal vs the Wi-Fi APs), and mark where its energy
    // lands — the three advertising channels for BLE, band-wide for Classic.
    if (sel && sel.rssi != null) {
        const yR = g.yFor(sel.rssi);
        const col = _wifiSignalColor(sel.rssi);
        // Horizontal RSSI line
        ctx.strokeStyle = col; ctx.lineWidth = 1.5; ctx.setLineDash([6, 4]);
        ctx.beginPath(); ctx.moveTo(r24.x0, yR); ctx.lineTo(r24.x1, yR); ctx.stroke();
        ctx.setLineDash([]);
        const isLE = sel.kind === 'le' || sel.kind === 'dual';
        if (isLE) {
            // Emphasise the advertising channels this device beacons on.
            (i.adv_markers || []).forEach(m => {
                const x = advX(m.freq_mhz);
                ctx.strokeStyle = col; ctx.lineWidth = 2.5;
                ctx.beginPath(); ctx.moveTo(x, yR); ctx.lineTo(x, baseY); ctx.stroke();
                ctx.fillStyle = col; ctx.beginPath(); ctx.arc(x, yR, 4, 0, 2 * Math.PI); ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
            });
        } else {
            // Classic BT hops the whole band — shade the segment at its level.
            ctx.fillStyle = col + '18';
            ctx.fillRect(r24.x0, yR, r24.x1 - r24.x0, baseY - yR);
        }
        // Label the selection at the left edge of the band.
        const nm = sel.name || sel.vendor || sel.mac;
        const tag = `${nm.length > 18 ? nm.slice(0, 17) + '…' : nm}  ${sel.rssi} dBm  ${isLE ? '(BLE adv)' : '(Classic · hops band)'}`;
        ctx.fillStyle = '#fff'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'left';
        ctx.fillText(tag, r24.x0 + 3, yR - 5);
    } else if (sel) {
        // Selected but no RSSI heard this scan.
        ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'left';
        ctx.fillText(`${sel.name || sel.mac} — RSSI not heard this scan`, r24.x0 + 3, g.padT + 14);
    }
}

// ============================================================================
// Full-screen spectrum console
// ----------------------------------------------------------------------------
// The same survey, the same _wifiState — but the whole viewport: a large
// hit-testable spectrum, the AP list underneath it, and an inspector that
// shows every field the scan produced for whatever is selected.
// ============================================================================

function wifiToggleFullscreen() {
    const el = document.getElementById('wifi-fs'); if (!el) return;
    if (el.classList.contains('hidden')) _wifiFsOpen(el); else _wifiFsClose(el);
}

function _wifiFsOpen(el) {
    _wifiFsWire();
    el.classList.remove('hidden');
    el.setAttribute('aria-hidden', 'false');
    document.body.classList.add('wifi-fs-open');
    _wifiState.fs.open = true;
    document.addEventListener('keydown', _wifiFsKey);
    // Ask for real fullscreen as well — if the browser refuses, the fixed
    // overlay alone still fills the viewport.
    if (el.requestFullscreen && !document.fullscreenElement) {
        el.requestFullscreen().then(() => { _wifiState.fs.native = true; }).catch(() => {});
    }
    _wifiSyncBandButtons();
    wifiSetView(_wifiState.view);
    ['wifi-auto', 'wifi-bt', 'wifi-zb'].forEach(id => {
        const m = document.getElementById(id), f = document.getElementById(id.replace('wifi-', 'wifi-fs-'));
        if (m && f) f.checked = m.checked;
    });
    _wifiFsRender();
    // The canvas only gets a size once the overlay is laid out.
    requestAnimationFrame(() => {
        if (_wifiState.view === 'waterfall') _wifiDrawWaterfall();
        else _wifiDrawSpectrum();
    });
    if (!_wifiState.data) wifiScan();
}

function _wifiFsClose(el) {
    el.classList.add('hidden');
    el.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('wifi-fs-open');
    _wifiState.fs.open = false;
    _wifiState.hoverBssid = null;
    document.removeEventListener('keydown', _wifiFsKey);
    if (document.fullscreenElement && _wifiState.fs.native) document.exitFullscreen().catch(() => {});
    _wifiState.fs.native = false;
    if (_wifiState.view === 'waterfall') _wifiDrawWaterfall();
    else if (_wifiState.data) _wifiDrawSpectrum();
}

function _wifiFsWire() {
    if (_wifiState.fs.wired) return;
    _wifiState.fs.wired = true;
    document.querySelectorAll('#wifi-fs-band button').forEach(b =>
        b.addEventListener('click', () => wifiSetBand(b.dataset.band)));
    document.querySelectorAll('#wifi-fs-view button').forEach(b =>
        b.addEventListener('click', () => { if (!b.disabled) wifiSetView(b.dataset.view); }));
    // Overlay toggles mirror the in-page checkboxes, so the existing change
    // handlers stay the single implementation.
    [['wifi-auto', 'wifi-fs-auto'], ['wifi-bt', 'wifi-fs-bt'], ['wifi-zb', 'wifi-fs-zb']].forEach(([mainId, fsId]) => {
        const m = document.getElementById(mainId), f = document.getElementById(fsId);
        if (!m || !f) return;
        f.addEventListener('change', () => {
            if (f.disabled) { f.checked = false; return; }
            m.checked = f.checked;
            m.dispatchEvent(new Event('change'));
        });
        m.addEventListener('change', () => { f.checked = m.checked; });
    });
    const canvas = document.getElementById('wifi-spectrum-fs');
    _wifiWireCanvas(canvas, 'wifi-fs-tip', 'wifi-fs-readout');
    if (canvas && window.ResizeObserver) {
        new ResizeObserver(() => {
            if (!_wifiState.fs.open) return;
            if (_wifiState.view === 'waterfall') _wifiDrawWaterfall();
            else if (_wifiState.data) _wifiDrawSpectrum();
        }).observe(canvas.parentElement || canvas);
    }
    // Leaving native fullscreen (browser Esc / F11) should close the overlay too.
    document.addEventListener('fullscreenchange', () => {
        if (_wifiState.fs.open && _wifiState.fs.native && !document.fullscreenElement) {
            _wifiState.fs.native = false;
            _wifiFsClose(document.getElementById('wifi-fs'));
        }
    });
}

function _wifiFsKey(e) {
    if (!_wifiState.fs.open) return;
    const tag = (e.target && e.target.tagName || '').toLowerCase();
    const typing = tag === 'input' || tag === 'select' || tag === 'textarea';
    if (e.key === 'Escape') { e.preventDefault(); wifiToggleFullscreen(); return; }
    if (typing) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); _wifiFsStep(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); _wifiFsStep(-1); }
    else if (e.key === 's' || e.key === 'S') wifiScan();
    else if (e.key === 'b' || e.key === 'B') wifiSetView('bar');
    else if (e.key === 'd' || e.key === 'D') wifiSetView('dome');
    else if (e.key === 'a' || e.key === 'A') wifiSetBand('all');
    else if (e.key === '2') wifiSetBand('2.4');
    else if (e.key === '5') wifiSetBand('5');
    else if (e.key === '6') wifiSetBand('6');
}

// Walk the currently-filtered list with the arrow keys.
function _wifiFsStep(delta) {
    const aps = _wifiFsAps();
    if (!aps.length) return;
    const i = aps.findIndex(a => a.bssid === _wifiState.selected);
    const next = aps[Math.max(0, Math.min(aps.length - 1, i < 0 ? 0 : i + delta))];
    if (next) {
        wifiSelectAp(next.bssid);
        const row = document.querySelector(`#wifi-fs-list tr[data-b="${next.bssid}"]`);
        if (row && row.scrollIntoView) row.scrollIntoView({ block: 'nearest' });
    }
}

function _wifiFsAps() {
    const g = id => (document.getElementById(id) || {});
    return _wifiFilterAps(g('wifi-fs-search').value, g('wifi-fs-std').value || '', !!g('wifi-fs-issues').checked);
}

function _wifiSetStatus(text) {
    const st = document.getElementById('wifi-status');
    if (st) st.textContent = text;
    const fs = document.getElementById('wifi-fs-status');
    if (fs) fs.textContent = text;
}

// Mirror the hardware gates (HackRF present? Huginn present?) onto the
// full-screen controls — the in-page buttons are the source of truth.
function _wifiFsSyncGates() {
    const zb = document.getElementById('wifi-fs-zb'), zbl = document.getElementById('wifi-fs-zb-label');
    const zbMain = document.getElementById('wifi-zb');
    if (zb && zbMain) {
        zb.disabled = zbMain.disabled;
        if (zbl) { zbl.style.opacity = zbMain.disabled ? '.4' : '1'; zbl.style.cursor = zbMain.disabled ? 'not-allowed' : 'pointer'; }
    }
    const wf = document.getElementById('wifi-fs-view-wf'), wfMain = document.getElementById('wifi-view-wf');
    if (wf && wfMain) {
        wf.disabled = wfMain.disabled;
        wf.style.opacity = wfMain.disabled ? '.4' : '1';
        wf.style.cursor = wfMain.disabled ? 'not-allowed' : 'pointer';
        wf.title = wfMain.title;
    }
}

// Repaint everything the console owns (called after each render/scan).
function _wifiFsRender() {
    if (!_wifiState.fs.open) return;
    const d = _wifiState.data;
    const iface = document.getElementById('wifi-fs-iface');
    if (iface) iface.textContent = _wifiState.iface ? `· ${_wifiState.iface}` : '';
    const st = document.getElementById('wifi-fs-status'), main = document.getElementById('wifi-status');
    if (st && main) st.textContent = main.textContent;
    _wifiFsSyncGates();
    // Band chips — clicking one filters the spectrum to that band.
    const summ = document.getElementById('wifi-fs-summary');
    if (summ) {
        const ratingColor = { clear: '#22c55e', moderate: '#eab308', congested: '#ef4444' };
        let chips = '';
        if (d) chips = Object.keys(d.spectrum).sort().map(b => {
            const s = d.spectrum[b];
            const on = _wifiState.band === b;
            const wa = s.width_advice ? ` · <span title="${_esc(s.width_advice.reason)}">→ ${s.width_advice.mhz}MHz</span>` : '';
            return `<button onclick="wifiSetBand('${on ? 'all' : b}')" title="${on ? 'Show all bands' : 'Show only this band'}"
                style="background:${_WIFI_BAND_COLOR[b]}${on ? '33' : '18'};border:1px solid ${_WIFI_BAND_COLOR[b]}${on ? 'cc' : '55'};border-radius:6px;padding:3px 8px;cursor:pointer">
                <b style="color:${_WIFI_BAND_COLOR[b]}">${b} GHz</b> · ${s.ap_count} AP ·
                <span style="color:${ratingColor[s.rating]}">${s.rating}</span> · best ch ${s.recommend.join(', ')}${wa}</button>`;
        }).join('');
        if (d && d.noise_floor != null) chips += `<span class="wifi-fs-tag" style="padding:3px 8px">noise floor ${d.noise_floor} dBm</span>`;
        summ.innerHTML = chips || '<span class="wifi-fs-meta">No APs heard yet — hit Scan.</span>';
    }
    const leg = document.getElementById('wifi-fs-legend');
    if (leg) leg.innerHTML = '<span>Signal:</span>' +
        [['#22c55e', 'strong ≥−55'], ['#84cc16', 'good ≥−67'], ['#eab308', 'fair ≥−75'], ['#f97316', 'weak ≥−85'], ['#ef4444', 'v.weak']]
            .map(([c, l]) => `<span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:${c};border-radius:2px;display:inline-block"></span>${l}</span>`).join('') +
        '<span style="color:#a78bfa">◆ DFS/radar</span><span style="color:#fbbf24">⚠ security issue</span>' +
        '<span class="wifi-fs-meta">keys: ↑↓ select · s scan · b/d view · a/2/5/6 band · Esc exit</span>';
    _wifiFsRenderList();
    _wifiFsRenderSide();
}

function _wifiFsRenderList() {
    const box = document.getElementById('wifi-fs-list');
    if (!box || !_wifiState.fs.open) return;
    const d = _wifiState.data;
    const cnt = document.getElementById('wifi-fs-count');
    if (!d) { box.innerHTML = '<div class="wifi-fs-empty">Run a scan to populate the survey.</div>'; if (cnt) cnt.textContent = ''; return; }
    const aps = _wifiFsAps();
    if (cnt) cnt.textContent = `(${aps.length}/${d.ap_count})`;
    const cols = [['ssid', 'SSID'], ['vendor', 'Vendor'], ['band', 'Band'], ['channel', 'Ch'], ['width', 'W'],
        ['max_phy_mbps', 'Rate'], ['signal', 'Signal'], ['snr', 'SNR'], ['security', 'Security'],
        ['channel_util', 'Util'], ['stations', 'Sta']];
    const arrow = k => _wifiState.sortKey === k ? (_wifiState.sortDir > 0 ? ' ▲' : ' ▼') : '';
    const head = cols.map(([k, l]) => `<th onclick="wifiSort('${k}')">${l}${arrow(k)}</th>`).join('');
    if (!aps.length) { box.innerHTML = `<table><thead><tr>${head}</tr></thead></table><div class="wifi-fs-empty">No APs match this filter.</div>`; return; }
    const rows = aps.map(a => {
        const sel = _wifiState.selected === a.bssid;
        const issue = (a.security_findings || []).length;
        const flagged = _wifiState.flagged && _wifiState.flagged.bssid === a.bssid;
        const bar = a.signal == null ? 0 : Math.max(4, Math.min(50, (a.signal + 100) / 70 * 50));
        const rate = a.max_phy_mbps ? (a.max_phy_mbps >= 1000 ? (a.max_phy_mbps / 1000).toFixed(1) + 'G' : a.max_phy_mbps + 'M') : '—';
        return `<tr data-b="${a.bssid}" class="${sel ? 'sel' : ''}" onclick="wifiSelectAp('${a.bssid}')"
            onmouseenter="_wifiFsHoverRow('${a.bssid}')" onmouseleave="_wifiFsHoverRow(null)">
            <td>${issue ? '<span style="color:#fbbf24" title="' + _esc(a.security_findings.join('; ')) + '">⚠</span> ' : ''}${flagged ? '<span style="color:#f87171" title="flagged by WiFi Defense">🛡</span> ' : ''}${_esc(a.ssid) || '<i style="color:#64748b">hidden</i>'}${_wifiGenBadge(a.standard)}${a.is_new ? ' <span class="wifi-fs-tag" style="color:#6ee7b7;border-color:#065f46">NEW</span>' : ''}
                <div style="font-family:ui-monospace,monospace;font-size:10px;color:#475569">${_esc(a.bssid)}</div></td>
            <td style="color:#94a3b8">${_esc(a.vendor) || '—'}</td>
            <td style="color:${_WIFI_BAND_COLOR[a.band]}">${a.band}</td>
            <td>${a.channel}${a.dfs ? ' <span style="color:#a78bfa" title="DFS/radar">◆</span>' : ''}</td>
            <td>${a.width}M</td>
            <td>${rate}</td>
            <td style="color:${_wifiSignalColor(a.signal)}">${a.signal}<span style="display:inline-block;height:6px;width:${bar}px;background:${_wifiSignalColor(a.signal)};border-radius:2px;margin-left:5px"></span>${_wifiSparkline(a.rssi_history)}</td>
            <td>${a.snr == null ? '—' : a.snr}</td>
            <td style="color:${a.security === 'Open' ? '#f87171' : '#cbd5e1'}">${_esc(a.security)}${_wifiSecBadges(a)}</td>
            <td>${a.channel_util == null ? '—' : a.channel_util + '%'}</td>
            <td>${a.stations == null ? '—' : a.stations}</td>
        </tr>`;
    }).join('');
    box.innerHTML = `<table><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>`;
}

// Hovering a list row highlights the same AP in the spectrum above it.
function _wifiFsHoverRow(bssid) {
    if (_wifiState.hoverBssid === bssid) return;
    _wifiState.hoverBssid = bssid;
    if (_wifiState.view !== 'waterfall' && _wifiState.data) _wifiDrawSpectrum();
}

function _wifiFsRenderSide() {
    const side = document.getElementById('wifi-fs-side');
    if (!side || !_wifiState.fs.open) return;
    const d = _wifiState.data;
    const ap = (d && _wifiState.selected) ? d.aps.find(a => a.bssid === _wifiState.selected) : null;
    let html = ap ? _wifiApDetailHtml(ap)
        : '<div class="wifi-fs-card"><h4>Inspector</h4><div class="wifi-fs-empty">Click a signal in the spectrum — or a row in the list — to see everything this survey knows about it.</div></div>';
    if (d) {
        // Interference
        const inf = d.interference || {};
        let ih = '';
        (inf.co_channel || []).slice(0, 8).forEach(g =>
            ih += `<div>• <b style="color:#fbbf24">${g.band} GHz ch ${g.channel}</b> — ${g.count} APs sharing <span style="color:#64748b">${_esc(g.ssids.slice(0, 3).join(', '))}</span></div>`);
        if ((inf.adjacent_overlap || []).length)
            ih += `<div style="margin-top:4px;color:#fb923c">${inf.adjacent_overlap.length} overlapping 2.4 GHz pair(s) — use only ch 1/6/11.</div>`;
        if (!ih) ih = '<div style="color:#4ade80">No significant co-/adjacent-channel interference.</div>';
        html += `<div class="wifi-fs-card"><h4>Interference</h4><div style="font-size:12px;line-height:1.6">${ih}</div></div>`;
        // Since last scan
        const c = d.changes || {};
        const ch = [].concat(
            (c.new_aps || []).map(a => `<div style="color:#6ee7b7">＋ ${_esc(a.ssid) || 'hidden'} <span style="color:#64748b">${a.band}G ch${a.channel} ${a.signal}dBm</span></div>`),
            (c.weakened || []).map(a => `<div style="color:#fbbf24">▼ ${_esc(a.ssid) || 'hidden'} <span style="color:#64748b">${a.signal}dBm (−${a.drop})</span></div>`),
            (c.gone_aps || []).map(a => `<div style="color:#94a3b8">－ ${_esc(a.ssid) || 'hidden'} gone</div>`));
        if (ch.length) html += `<div class="wifi-fs-card"><h4>Since last scan</h4><div style="font-size:12px;line-height:1.6">${ch.join('')}</div></div>`;
    }
    // Live 2.4 GHz neighbours from the overlays, clickable like the AP list.
    if (_wifiState.btOn && _wifiState.bt) {
        const devs = (_wifiState.bt.devices || []).slice(0, 40);
        const i = _wifiState.bt.interference || {};
        html += `<div class="wifi-fs-card"><h4>📶 Bluetooth / BLE (${_wifiState.bt.device_count || devs.length})</h4>
            <div style="font-size:11px;color:#64748b;margin-bottom:5px">hopping pressure ${i.hopping_pressure == null ? '—' : i.hopping_pressure + '%'}</div>
            ${devs.map(v => `<div class="wifi-fs-devrow ${_wifiState.btSelected === v.mac ? 'sel' : ''}" onclick="wifiBtSelect('${v.mac}')">
                <span>${_esc(v.name || v.vendor || v.mac)}</span>
                <span style="color:${_wifiSignalColor(v.rssi)}">${v.rssi == null ? '—' : v.rssi}</span></div>`).join('')
                || '<div class="wifi-fs-empty">No devices heard.</div>'}</div>`;
    }
    if (_wifiState.zbOn && _wifiState.zb) {
        const devs = (_wifiState.zb.devices || []).slice(0, 40);
        html += `<div class="wifi-fs-card"><h4>🐝 Zigbee / 802.15.4 (${_wifiState.zb.device_count || devs.length})</h4>
            ${devs.map(v => { const id = v.addr || v.short_addr;
                return `<div class="wifi-fs-devrow ${_wifiState.zbSelected === id ? 'sel' : ''}" onclick="wifiZbSelect('${id}')">
                    <span>${_esc(v.vendor || id)} <span style="color:#64748b">ch${v.channel}</span></span>
                    <span style="color:${_wifiSignalColor(v.rssi)}">${v.rssi == null ? '—' : v.rssi}</span></div>`; }).join('')
                || '<div class="wifi-fs-empty">No devices heard.</div>'}</div>`;
    }
    side.innerHTML = html;
}

// Everything the passive survey produced for one AP. Fields the scan didn't
// yield are shown as "—" rather than hidden, so an empty column reads as
// "the beacon didn't say", not "we forgot to look".
function _wifiApDetailHtml(a) {
    const col = _wifiSignalColor(a.signal);
    const quality = a.signal == null ? 'unknown' : a.signal >= -55 ? 'excellent' : a.signal >= -67 ? 'good'
        : a.signal >= -75 ? 'fair' : a.signal >= -85 ? 'weak' : 'very weak';
    const kv = rows => '<dl class="wifi-fs-kv">' + rows.filter(Boolean)
        .map(([k, v]) => `<dt>${k}</dt><dd>${v == null || v === '' ? '—' : v}</dd>`).join('') + '</dl>';
    const yn = (v, on, off) => v == null ? '—' : (v ? (on || 'yes') : (off || 'no'));
    const r = a.roaming || {};
    const roam = ['k', 'v', 'r'].filter(x => r[x]).map(x => '802.11' + x).join(', ') || 'none advertised';
    const findings = (a.security_findings || []);
    const util = a.channel_util;
    const utilBar = util == null ? '' :
        `<div style="height:6px;border-radius:3px;background:#1e293b;margin-top:4px">
            <div style="height:6px;border-radius:3px;width:${Math.min(100, util)}%;background:${util > 60 ? '#ef4444' : util > 30 ? '#eab308' : '#22c55e'}"></div></div>`;
    // Coverage model, when the radius endpoint has answered for this BSSID.
    const rad = (_wifiState.radius && _wifiState.radius.bssid === a.bssid) ? _wifiState.radius : null;
    const radHtml = rad ? `<div class="wifi-fs-card"><h4>Modelled coverage</h4>
        <div style="font-size:12px">You are ~<b>${rad.current_distance_m} m</b> away.</div>
        ${(rad.rings || []).map(x => `<div style="font-size:12px">• <b>${x.radius_m} m</b> — ${_esc(x.label)} <span style="color:#64748b">(≤${x.threshold_dbm} dBm)</span></div>`).join('')}
        <div style="font-size:10px;color:#64748b;margin-top:4px">Tx ${rad.assumptions.tx_dbm} dBm (${_esc(rad.assumptions.tx_source)}), n=${rad.assumptions.path_loss_exponent}, ref ${rad.assumptions.rssi_at_1m} dBm@1m. Estimate only.</div></div>` : '';
    return `
    <div class="wifi-fs-card">
        <h4>Selected AP</h4>
        <div style="font-size:16px;font-weight:600">${_esc(a.ssid) || '<i style="color:#64748b">hidden SSID</i>'}${_wifiGenBadge(a.standard)}</div>
        <div style="font-family:ui-monospace,monospace;font-size:11px;color:#64748b">${_esc(a.bssid)}</div>
        <div style="font-size:11px;color:#94a3b8;margin-bottom:8px">${_esc(a.vendor) || 'unknown vendor'}</div>
        <div style="display:flex;align-items:flex-end;gap:10px">
            <span class="wifi-fs-big" style="color:${col}">${a.signal == null ? '—' : a.signal}<span style="font-size:12px;font-weight:400"> dBm</span></span>
            <span style="font-size:11px;color:#94a3b8;padding-bottom:4px">${quality}${a.snr != null ? ' · SNR ' + a.snr + ' dB' : ''}</span>
        </div>
        ${_wifiSparkline(a.rssi_history, 330, 40) || '<div style="font-size:11px;color:#475569;margin-top:4px">RSSI history builds up over repeat scans.</div>'}
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
            <button class="wifi-hm-btn" onclick="wifiFsCopy('${a.bssid}')">⧉ Copy BSSID</button>
            <button class="wifi-hm-btn" onclick="wifiFsSurveyAp('${a.bssid}')" title="Make this the target of the coverage heatmap">🗺 Survey this AP</button>
            <button class="wifi-hm-btn" onclick="wifiFsFilterSsid('${encodeURIComponent(a.ssid || '')}')" title="Filter the list to this SSID">⌕ Same SSID</button>
            <button class="wifi-hm-btn" onclick="wifiFsClearSelection()">✕ Clear</button>
        </div>
    </div>
    <div class="wifi-fs-card"><h4>Radio</h4>${kv([
        ['Band', `<span style="color:${_WIFI_BAND_COLOR[a.band]}">${a.band} GHz</span>`],
        ['Channel', `${a.channel}${a.dfs ? ' <span style="color:#a78bfa">◆ DFS / radar</span>' : ''}`],
        ['Width', a.width + ' MHz'],
        ['Frequency', a.freq ? a.freq + ' MHz' : null],
        ['Centre freq', a.center_freq ? a.center_freq + ' MHz' : null],
        ['Generation', a.standard],
        ['PHY mode', a.phy_mode],
        ['Spatial streams', a.nss ? a.nss + '×' : null],
        ['Max PHY rate', a.max_phy_mbps ? (a.max_phy_mbps >= 1000 ? (a.max_phy_mbps / 1000).toFixed(1) + ' Gbps' : a.max_phy_mbps + ' Mbps') : null],
        ['Tx power', a.tx_power_dbm != null ? a.tx_power_dbm + ' dBm (advertised)' : null],
        ['Country', a.country],
    ])}</div>
    <div class="wifi-fs-card"><h4>Load &amp; timing</h4>${kv([
        ['Ch. utilisation', util == null ? null : util + '%' + utilBar],
        ['Stations', a.stations],
        ['Beacon int.', a.beacon_interval != null ? a.beacon_interval + ' TU' : null],
        ['DTIM', a.dtim],
        ['Last beacon', a.last_seen_ms != null ? (a.last_seen_ms / 1000).toFixed(1) + ' s ago' : null],
        ['Seen', a.seen_count ? a.seen_count + '× this session' : null],
        ['First seen', a.is_new ? 'this scan' : 'earlier session'],
        ['RSSI samples', (a.rssi_history || []).length || null],
    ])}</div>
    <div class="wifi-fs-card"><h4>Security</h4>${kv([
        ['Suite', `<span style="color:${a.security === 'Open' ? '#f87171' : '#e2e8f0'}">${_esc(a.security)}</span>`],
        ['PMF (802.11w)', a.pmf ? _esc(a.pmf) : null],
        ['802.1X', yn(a.enterprise, 'enterprise', 'personal/none')],
        ['WPS', yn(a.wps, '<span style="color:#f87171">enabled</span>', 'off')],
        ['Roaming', roam],
        ['Hidden SSID', yn(a.hidden)],
    ])}
    ${findings.length
        ? '<div style="margin-top:7px;font-size:12px;color:#fbbf24">' + findings.map(f => `<div>⚠ ${_esc(f)}</div>`).join('') + '</div>'
        : '<div style="margin-top:7px;font-size:12px;color:#4ade80">No security findings.</div>'}
    </div>
    ${radHtml}`;
}

function wifiFsCopy(bssid) {
    if (navigator.clipboard) navigator.clipboard.writeText(bssid).catch(() => {});
    _wifiSetStatus('copied ' + bssid);
}

function wifiFsClearSelection() {
    _wifiState.selected = null;
    _wifiState.radius = null;
    wifiRender();
}

function wifiFsFilterSsid(ssidEnc) {
    const s = decodeURIComponent(ssidEnc || '');
    const box = document.getElementById('wifi-fs-search');
    if (box) { box.value = s; _wifiFsRenderList(); }
}

// Hand the AP to the coverage heatmap and drop back to the page, where the
// walk-around survey lives.
function wifiFsSurveyAp(bssid) {
    const sel = document.getElementById('wifi-hm-ap');
    if (sel && [...sel.options].some(o => o.value === bssid)) sel.value = bssid;
    if (_wifiState.fs.open) wifiToggleFullscreen();
    const card = document.getElementById('wifi-heatmap');
    if (card && card.scrollIntoView) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
}

// ---- WiFi Defense → Analyzer pivot -----------------------------------------
// WIDS detections link here: jump to the Spectrum Analyzer, select the
// offending BSSID and keep it highlighted (red, ⚠ WIDS) until dismissed.
function wifiPivotFromDefense(bssid, ssidEnc) {
    _wifiState.flagged = { bssid: (bssid || '').toLowerCase(),
        ssid: ssidEnc ? decodeURIComponent(ssidEnc) : '', applied: false };
    // Widen to all bands so the band filter can't hide the target.
    _wifiState.band = 'all';
    document.querySelectorAll('#wifi-band-group .wifi-band').forEach(b => {
        const on = b.dataset.band === 'all';
        b.classList.toggle('bg-Ragnar-600', on); b.classList.toggle('text-white', on);
        b.classList.toggle('text-slate-300', !on);
    });
    showTab('network');
    showNetworkSubtab('wifi');      // wifiInit() — auto-scans when there's no survey yet
    _wifiFlagBanner();
    if (_wifiState.data) {
        if (_wifiState.data.aps.some(a => a.bssid === _wifiState.flagged.bssid)) {
            _wifiState.flagged.applied = true;
            wifiSelectAp(_wifiState.flagged.bssid);
            _wifiFlagBanner();
        } else {
            wifiScan();             // stale survey — the rogue may only just have appeared
        }
    }
}

function wifiClearFlag() {
    _wifiState.flagged = null;
    _wifiFlagBanner();
    if (_wifiState.data) wifiRender();
}

function _wifiFlagBanner() {
    const el = document.getElementById('wifi-flag-banner'); if (!el) return;
    const f = _wifiState.flagged;
    if (!f) { el.className = 'hidden'; el.innerHTML = ''; return; }
    const found = !!(_wifiState.data && _wifiState.data.aps.some(a => a.bssid === f.bssid));
    const state = !_wifiState.data ? 'surveying…'
        : found ? 'highlighted in the spectrum below'
            : 'not heard in the latest survey — it may be down, out of range, or beaconing intermittently';
    el.className = 'flex flex-wrap items-center gap-2 mb-3 text-xs px-3 py-2 rounded-lg bg-red-950/50 border border-red-800 text-red-200';
    el.innerHTML = '<span>🛡 Flagged by WiFi Defense:</span>'
        + `<b>${_esc(f.ssid) || '<span class="italic">hidden SSID</span>'}</b>`
        + `<span class="font-mono">${_esc(f.bssid)}</span>`
        + `<span style="color:rgba(252,165,165,.8)">· ${state}</span>`
        + '<button onclick="wifiClearFlag()" class="ml-auto px-2 py-0.5 rounded bg-red-900/60 hover:bg-red-800 text-red-100" title="Clear the WIDS highlight">✕ dismiss</button>';
}

function wifiSelectAp(bssid) {
    if (_wifiState.selected !== bssid) _wifiState.radius = null;
    _wifiState.selected = bssid;
    wifiRender();
    const iface = _wifiState.iface;
    // Prefill TX with the AP's advertised power (TPC report) when it has one.
    const ap = (_wifiState.data && _wifiState.data.aps || []).find(a => a.bssid === bssid);
    const txBox = document.getElementById('wifi-tx');
    if (ap && ap.tx_power_dbm != null && !txBox._userset) txBox.value = ap.tx_power_dbm;
    txBox.onchange = () => { txBox._userset = true; if (_wifiState.selected) wifiSelectAp(_wifiState.selected); };
    ['wifi-ple', 'wifi-rssi-offset', 'wifi-ant-gain', 'wifi-cable-loss'].forEach(id => {
        const el = document.getElementById(id);
        if (el && !el._wired) {
            el._wired = true;
            el.onchange = () => {
                // Typing n directly means the preset no longer matches → mark custom.
                if (id === 'wifi-ple') _wifiSyncEnvPreset();
                if (_wifiState.selected) wifiSelectAp(_wifiState.selected);
            };
        }
    });
    const tx = txBox.value || 'auto';
    const ple = document.getElementById('wifi-ple').value || 3.0;
    const rssiOffset = document.getElementById('wifi-rssi-offset').value || 0;
    const antGain = document.getElementById('wifi-ant-gain').value || 0;
    const cableLoss = document.getElementById('wifi-cable-loss').value || 0;
    const rssi0 = _wifiState.calRssi0 != null ? `&rssi0=${_wifiState.calRssi0}` : '';
    // Hand back the row we're already showing so the server needn't re-scan
    // (a fresh scan can momentarily miss the AP → "bssid not found").
    let known = '';
    if (ap && ap.signal != null) {
        known = `&signal=${ap.signal}&freq=${ap.freq || ''}&center_freq=${ap.center_freq || ''}`
            + `&band=${encodeURIComponent(ap.band || '')}&channel=${ap.channel != null ? ap.channel : ''}`
            + `&ssid=${encodeURIComponent(ap.ssid || '')}`
            + `&tx_measured=${ap.tx_power_dbm != null ? ap.tx_power_dbm : ''}`;
    }
    document.getElementById('wifi-radius-controls').style.display = 'flex';
    document.getElementById('wifi-cal-details').style.display = 'block';
    fetch(`/api/net/wifi/radius?interface=${encodeURIComponent(iface)}&bssid=${encodeURIComponent(bssid)}&tx=${tx}&ple=${ple}&rssi_offset=${rssiOffset}&antenna_gain=${antGain}&cable_loss=${cableLoss}${rssi0}${known}`)
        .then(r => r.json()).then(d => {
            if (d.error) {
                document.getElementById('wifi-radius-info').innerHTML = '<span class="text-amber-400">' + d.error + '</span>';
                _wifiState.radius = null; _wifiFsRenderSide();
                return;
            }
            // Kept for the full-screen inspector, which shows the same model.
            _wifiState.radius = d;
            _wifiFsRenderSide();
            _wifiDrawRadius(d);
            document.getElementById('wifi-radius-target').textContent = '· ' + (d.ssid || bssid);
            const srcMap = { measured: '<span class="text-green-400">measured</span>', calibrated: '<span class="text-cyan-400">calibrated</span>' };
            const src = srcMap[d.assumptions.tx_source] || 'assumed';
            const a = d.assumptions;
            const adj = (d.signal_adjusted != null && d.signal_adjusted !== d.signal) ? ` (adj ${d.signal_adjusted})` : '';
            const cal = (a.rssi_offset || a.antenna_gain || a.cable_loss)
                ? `<div class="text-[10px] text-gray-600">Cal: offset ${a.rssi_offset || 0} dB · ant ${a.antenna_gain || 0} dBi · cable ${a.cable_loss || 0} dB</div>` : '';
            document.getElementById('wifi-radius-info').innerHTML =
                `<div class="mb-1">Measured <b style="color:${_wifiSignalColor(d.signal)}">${d.signal} dBm</b>${adj} → you are ~<b>${d.current_distance_m} m</b> from this AP.</div>` +
                d.rings.map(r => `<div>• <b>${r.radius_m} m</b> — ${r.label} (≤${r.threshold_dbm} dBm)</div>`).join('') +
                `<div class="text-[10px] text-gray-600 mt-1">Model: Tx ${a.tx_dbm} dBm (${src}), n=${a.path_loss_exponent}, ref ${a.rssi_at_1m} dBm@1m. Estimate only.</div>` + cal;
        }).catch(() => {});
}

function wifiSetEnvPreset(v) {
    // Preset dropdown → path-loss exponent n. "custom" leaves the field as-is.
    if (v !== 'custom') document.getElementById('wifi-ple').value = v;
    if (_wifiState.selected) wifiSelectAp(_wifiState.selected);
}

function _wifiSyncEnvPreset() {
    // Reflect a manually-typed n back into the preset dropdown (custom if no match).
    // Compare numerically so 5, 5.0 and "5.0" all match the same option.
    const sel = document.getElementById('wifi-env-preset'); if (!sel) return;
    const n = parseFloat(document.getElementById('wifi-ple').value);
    const match = [...sel.options].find(o => o.value !== 'custom' && parseFloat(o.value) === n);
    sel.value = match ? match.value : 'custom';
}

function wifiCalibrate() {
    const g = id => document.getElementById(id).value;
    const st = document.getElementById('wifi-cal-status');
    const qs = `d1=${g('wifi-cal-d1')}&rssi1=${g('wifi-cal-r1')}&d2=${g('wifi-cal-d2')}&rssi2=${g('wifi-cal-r2')}`;
    fetch(`/api/net/wifi/calibrate?${qs}`).then(r => r.json()).then(d => {
        if (d.error) { st.textContent = '⚠ ' + d.error; return; }
        _wifiState.calRssi0 = d.rssi_at_1m;
        document.getElementById('wifi-ple').value = d.path_loss_exponent;
        _wifiSyncEnvPreset();
        st.innerHTML = `n=<b>${d.path_loss_exponent}</b>, ref <b>${d.rssi_at_1m}</b> dBm@1m — applied`;
        if (_wifiState.selected) wifiSelectAp(_wifiState.selected);
    }).catch(() => { st.textContent = 'calibration failed'; });
}

function wifiCalibrateReset() {
    _wifiState.calRssi0 = null;
    const st = document.getElementById('wifi-cal-status');
    if (st) st.textContent = 'cleared — using TX/FSPL model';
    if (_wifiState.selected) wifiSelectAp(_wifiState.selected);
}

function _wifiDrawRadius(d) {
    const canvas = document.getElementById('wifi-radius-canvas'); if (!canvas) return;
    canvas.style.display = 'block';
    const dpr = window.devicePixelRatio || 1;
    const W = canvas.clientWidth, H = 220;
    canvas.width = W * dpr; canvas.height = H * dpr;
    const ctx = canvas.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const cx = W / 2, cy = H / 2;
    const maxR = Math.max(...d.rings.map(r => r.radius_m));
    const scale = (Math.min(W, H) / 2 - 24) / maxR;
    const ringColors = { voice: '#22c55e', data: '#eab308', edge: '#ef4444' };
    [...d.rings].reverse().forEach(r => {
        const rad = r.radius_m * scale;
        ctx.beginPath(); ctx.arc(cx, cy, rad, 0, 2 * Math.PI);
        ctx.fillStyle = (ringColors[r.name] || '#38bdf8') + '18'; ctx.fill();
        ctx.strokeStyle = (ringColors[r.name] || '#38bdf8') + 'aa'; ctx.lineWidth = 1.5; ctx.stroke();
        ctx.fillStyle = '#94a3b8'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText(r.radius_m + 'm', cx, cy - rad + 10);
    });
    // AP at center
    ctx.beginPath(); ctx.arc(cx, cy, 6, 0, 2 * Math.PI); ctx.fillStyle = _WIFI_BAND_COLOR[d.band] || '#38bdf8'; ctx.fill();
    // Your position (on the data ring direction)
    if (d.current_distance_m) {
        const yr = Math.min(d.current_distance_m * scale, Math.min(W, H) / 2 - 6);
        const px = cx + yr * 0.71, py = cy - yr * 0.71;
        ctx.beginPath(); ctx.arc(px, py, 4, 0, 2 * Math.PI); ctx.fillStyle = '#fff'; ctx.fill();
        ctx.fillStyle = '#cbd5e1'; ctx.font = '9px sans-serif'; ctx.textAlign = 'left';
        ctx.fillText('you (' + d.current_distance_m + 'm)', px + 6, py);
    }
}

// ---- WiFi coverage heatmap (walk-around survey) ----------------------------
const _wifiHm = { floorplan: null, data: null, inited: false, metric: 'rssi',
    mode: 'survey', tool: 'wall', walls: [], columns: [], predictAps: [], predicting: true,
    wallStart: null, mesh: false, drag: null, dragMoved: false, suppressClick: false,
    view: { zoom: 1, cx: 0.5, cy: 0.5 }, pan: null };

// ---- Floor scale + zoomable viewport ---------------------------------------
// The floor is a square of `floorM` × `floorM` metres; every stored coordinate
// stays normalized 0..1 across that square (backend-compatible). The viewport
// maps a zoomed/panned window of the floor onto the plot area of the canvas,
// leaving margins for the metre rulers.
function _wifiHmFloorM() {
    const el = document.getElementById('wifi-hm-scale');
    const v = parseFloat(el && el.value);
    return (v && v > 0) ? v : 10;
}

function _wifiHmViewport(W, H) {
    const ML = 34, MR = 10, MT = 20, MB = 24;  // equal totals → the floor plot stays square
    const pw = W - ML - MR, ph = H - MT - MB;
    const v = _wifiHm.view;
    const span = 1 / v.zoom;                    // visible fraction of the floor
    const x0 = v.cx - span / 2, y0 = v.cy - span / 2;
    return {
        ML, MT, pw, ph, x0, y0, span,
        toX: wx => ML + (wx - x0) / span * pw,
        toY: wy => MT + (wy - y0) / span * ph,
        fromX: px => x0 + (px - ML) / pw * span,
        fromY: py => y0 + (py - MT) / ph * span,
    };
}

function _wifiHmClampView() {
    const v = _wifiHm.view;
    v.zoom = Math.max(1, Math.min(16, v.zoom));
    const half = 0.5 / v.zoom;
    v.cx = Math.max(half, Math.min(1 - half, v.cx));
    v.cy = Math.max(half, Math.min(1 - half, v.cy));
}

// Zoom by `factor`, keeping the point under (px,py) canvas px fixed (or the
// view centre when called from the ± buttons).
function wifiHmZoom(factor, px, py) {
    const cv = document.getElementById('wifi-heatmap'); if (!cv) return;
    const vp = _wifiHmViewport(cv.clientWidth, cv.clientHeight || cv.clientWidth);
    const v = _wifiHm.view;
    const ax = px != null ? vp.fromX(px) : v.cx;
    const ay = py != null ? vp.fromY(py) : v.cy;
    const oldZoom = v.zoom;
    v.zoom = Math.max(1, Math.min(16, v.zoom * factor));
    const k = oldZoom / v.zoom;
    v.cx = ax - (ax - v.cx) * k;
    v.cy = ay - (ay - v.cy) * k;
    _wifiHmClampView();
    wifiHeatmapRender();
}

function wifiHmZoomReset() {
    _wifiHm.view = { zoom: 1, cx: 0.5, cy: 0.5 };
    wifiHeatmapRender();
}

function _wifiHmSyncScaleUI() {
    const m = _wifiHmFloorM();
    const area = document.getElementById('wifi-hm-area');
    if (area) area.textContent = Math.round(m * m).toLocaleString() + ' m²';
}

// Floor-size input changed: keep the modelled APs' real-world size in sync
// (predictions use metres), remember the choice, redraw the rulers.
function wifiHmScaleChanged() {
    const m = _wifiHmFloorM();
    _wifiHmSyncScaleUI();
    if (_wifiHm.predictAps.length) {
        _wifiHm.predictAps.forEach(ap => { ap.width_m = m; ap.height_m = m; });
        _wifiHmPersistAp();
    }
    try { localStorage.setItem('wifiHmFloorM', String(m)); } catch (_) {}
    wifiHeatmapRender();
}

// Distinct colours for mesh nodes (serving-node map + legend).
const _WIFI_MESH_COLORS = ['#38bdf8', '#a78bfa', '#f472b6', '#34d399', '#fbbf24',
    '#fb7185', '#22d3ee', '#c084fc', '#4ade80', '#f59e0b'];
function _wifiMeshNodeList() {
    const reg = (_wifiHm.data && _wifiHm.data.mesh_nodes) || {};
    return Object.keys(reg).sort();
}
function _wifiMeshColor(bssid) {
    const list = _wifiMeshNodeList();
    const i = list.indexOf(bssid);
    return _WIFI_MESH_COLORS[(i < 0 ? 0 : i) % _WIFI_MESH_COLORS.length];
}

// Building-material attenuation (dB), mirrors wifi_analyzer._WALL_MATERIALS.
const _WIFI_WALL_DB = { drywall: 3, wood: 4, glass: 6, brick: 10, concrete: 15, metal: 20 };
// Colour-code construction materials so walls/columns read at a glance.
const _WIFI_MAT_COLORS = {
    brick: '#dc2626',    // red
    glass: '#f8fafc',    // white
    concrete: '#9ca3af', // grey
    metal: '#3b82f6',    // blue (steel)
    drywall: '#d8c39a',  // beige
    wood: '#8b5a2b',     // brown
};
const _WIFI_MAT_LABELS = { brick: 'Brick', glass: 'Glass', concrete: 'Concrete',
    metal: 'Steel', drywall: 'Drywall', wood: 'Wood' };
function _wifiMatColor(mat) { return _WIFI_MAT_COLORS[mat] || '#0ea5e9'; }

// Calibrated metric scales: [lo (red), hi (green)] and labelled break points.
// (For latency, lo>hi so lower = greener.)
const _WIFI_HM_METRICS = {
    rssi: { lo: -90, hi: -30, unit: 'dBm', field: 'rssi',
        marks: [[-30, 'excellent'], [-67, 'good'], [-72, 'fair'], [-80, 'weak'], [-90, 'dead']] },
    snr:  { lo: 5, hi: 40, unit: 'dB', field: 'snr',
        marks: [[40, 'excellent'], [25, 'good'], [15, 'fair'], [10, 'marginal'], [5, 'unusable']] },
    throughput_down: { lo: 0, hi: 500, unit: 'Mbps', field: 'down_mbps',
        marks: [[500, 'excellent'], [200, 'great'], [50, 'ok'], [10, 'weak'], [1, 'poor']] },
    throughput_up: { lo: 0, hi: 300, unit: 'Mbps', field: 'up_mbps',
        marks: [[300, 'excellent'], [100, 'great'], [25, 'ok'], [5, 'weak'], [1, 'poor']] },
    latency: { lo: 150, hi: 5, unit: 'ms', field: 'latency_ms',
        marks: [[5, 'excellent'], [20, 'good'], [50, 'fair'], [100, 'poor'], [150, 'bad']] },
};

function _wifiHmValue(sp) {
    // Selected metric value for a sample (null if this sample lacks it → grey).
    const m = _WIFI_HM_METRICS[_wifiHm.metric] || _WIFI_HM_METRICS.rssi;
    const v = sp[m.field];
    return v == null ? null : v;
}

function _wifiHeatColor(val) {
    const m = _WIFI_HM_METRICS[_wifiHm.metric] || _WIFI_HM_METRICS.rssi;
    const t = Math.max(0, Math.min(1, (val - m.lo) / (m.hi - m.lo)));
    const stops = [[239, 68, 68], [245, 158, 11], [234, 179, 8], [132, 204, 22], [34, 197, 94]];
    const seg = Math.min(stops.length - 2, Math.floor(t * (stops.length - 1)));
    const f = t * (stops.length - 1) - seg;
    const c = stops[seg].map((v, i) => Math.round(v + (stops[seg + 1][i] - v) * f));
    return c;
}

function wifiHeatmapSetMetric(v) {
    _wifiHm.metric = (_WIFI_HM_METRICS[v] || v === 'serving' || v === 'handoff') ? v : 'rssi';
    wifiHeatmapRender();
}

function wifiHeatmapRenderLegend() {
    const el = document.getElementById('wifi-hm-legend'); if (!el) return;
    // Mesh maps have their own legends (node colours / hand-off bands).
    if (_wifiHm.mode !== 'design' && (_wifiHm.metric === 'serving' || _wifiHm.metric === 'handoff')) {
        if (_wifiHm.metric === 'serving') {
            const nodes = _wifiMeshNodeList();
            const reg = (_wifiHm.data && _wifiHm.data.mesh_nodes) || {};
            el.innerHTML = '<span>Serving node:</span> ' + (nodes.length ? nodes.map((b, i) =>
                `<span class="flex items-center gap-1"><span style="width:10px;height:10px;border-radius:2px;display:inline-block;background:${_wifiMeshColor(b)}"></span>${String.fromCharCode(65 + i)} <span class="text-gray-500 font-mono text-[10px]">${b.slice(9)}</span><span class="text-gray-600">${reg[b] ? ' ' + reg[b].band + 'G ch' + reg[b].channel : ''}</span></span>`
            ).join('') : '<span class="text-gray-500">walk the space to map which node serves where</span>');
        } else {
            el.innerHTML = '<span>Hand-off overlap:</span>'
                + '<span class="flex items-center gap-1"><span style="width:10px;height:10px;border-radius:2px;display:inline-block;background:#22c55e"></span>good (&lt;6 dB)</span>'
                + '<span class="flex items-center gap-1"><span style="width:10px;height:10px;border-radius:2px;display:inline-block;background:#eab308"></span>marginal</span>'
                + '<span class="flex items-center gap-1"><span style="width:10px;height:10px;border-radius:2px;display:inline-block;background:#ef4444"></span>sticky (&gt;12 dB)</span>'
                + '<span class="flex items-center gap-1"><span style="width:10px;height:10px;border-radius:2px;display:inline-block;background:#64748b"></span>single node</span>';
        }
        return;
    }
    // While predicting we always colour by modelled RSSI, so show that legend.
    const effMetric = (_wifiHm.mode === 'design' && _wifiHm.predicting) ? 'rssi' : _wifiHm.metric;
    const saved = _wifiHm.metric; _wifiHm.metric = effMetric;
    const m = _WIFI_HM_METRICS[effMetric] || _WIFI_HM_METRICS.rssi;
    const bar = '<span style="width:56px;height:8px;display:inline-block;border-radius:2px;background:linear-gradient(90deg,#ef4444,#f59e0b,#eab308,#84cc16,#22c55e)"></span>';
    const marks = m.marks.map(([v, l]) =>
        `<span class="flex items-center gap-1"><span style="width:9px;height:9px;border-radius:2px;display:inline-block;background:rgb(${_wifiHeatColor(v).join(',')})"></span>${v} <span class="text-gray-600">${l}</span></span>`
    ).join('');
    const tag = effMetric === 'rssi' && _wifiHm.mode === 'design' ? 'Predicted RSSI' : effMetric.toUpperCase();
    el.innerHTML = `<span>${tag} (${m.unit}):</span> ${bar} <span class="text-gray-600">${m.lo}→${m.hi}</span> ${marks} <span class="ml-1 text-gray-500">● live sample</span>`;
    _wifiHm.metric = saved;
}

function wifiHeatmapInit() {
    if (_wifiHm.inited) return;
    _wifiHm.inited = true;
    wifiSurveyRefresh();
    const file = document.getElementById('wifi-hm-file');
    if (file) file.addEventListener('change', (e) => {
        const f = e.target.files[0]; if (!f) return;
        const rd = new FileReader();
        rd.onload = () => {
            const sel = document.getElementById('wifi-hm-ap');
            const bssid = sel.value || null;
            const ap = (_wifiState.data && _wifiState.data.aps || []).find(a => a.bssid === bssid);
            fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'floorplan', floorplan: rd.result, bssid: bssid, ssid: ap && ap.ssid }) })
                .then(() => wifiHeatmapLoad());
        };
        rd.readAsDataURL(f);
    });
    const sc = document.getElementById('wifi-hm-scale');
    try { const s = localStorage.getItem('wifiHmFloorM'); if (sc && s) sc.value = s; } catch (_) {}
    _wifiHmSyncScaleUI();
    window.addEventListener('resize', () => { if (document.getElementById('wifi-heatmap')) _wifiHmDragRender(); });
    const cv = document.getElementById('wifi-heatmap');
    if (cv) cv.addEventListener('click', (e) => {
        // A just-finished drag/pan (or a press on an existing object) must not
        // also place a new AP / sample here.
        if (_wifiHm.suppressClick) { _wifiHm.suppressClick = false; return; }
        const rect = cv.getBoundingClientRect();
        const vp = _wifiHmViewport(cv.clientWidth, cv.clientHeight || cv.clientWidth);
        const x = vp.fromX(e.clientX - rect.left);
        const y = vp.fromY(e.clientY - rect.top);
        if (x < 0 || x > 1 || y < 0 || y > 1) return;  // ruler margin / outside the floor
        if (_wifiHm.mode === 'design') { _wifiHmDesignClick(x, y); return; }
        const sel = document.getElementById('wifi-hm-ap');
        const val = sel.value;
        const st = document.getElementById('wifi-hm-status');
        if (!val) { st.textContent = _wifiHm.mesh ? 'Pick a mesh SSID first.' : 'Pick a target AP first.'; return; }
        const active = document.getElementById('wifi-hm-active').checked;
        const body = _wifiHm.mesh
            ? { action: 'sample_mesh', interface: _wifiState.iface, x, y, ssid: val }
            : { action: 'sample_live', interface: _wifiState.iface, x, y, bssid: val };
        if (active) {
            body.active = true;
            body.iperf_server = (document.getElementById('wifi-hm-iperf').value || '').trim();
            body.seconds = parseInt(document.getElementById('wifi-hm-tp-secs').value) || 5;
            st.textContent = 'Reading + throughput test (~' + (body.seconds * 2 + 5) + 's)…';
        } else {
            st.textContent = 'Reading…';
        }
        fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body) })
            .then(r => r.json()).then(d => {
                if (d.error) { st.textContent = '⚠ ' + d.error; return; }
                st.textContent = (d.samples ? d.samples.length : 0) + ' sample(s)';
                wifiHeatmapLoad();
            }).catch(() => { st.textContent = 'sample failed'; });
    });
    // --- Zoom (wheel) + pan (drag) + drag existing AP nodes / walls ---
    if (cv) {
        const norm = (e) => {
            const r = cv.getBoundingClientRect();
            const px = e.clientX - r.left, py = e.clientY - r.top;
            const vp = _wifiHmViewport(cv.clientWidth, cv.clientHeight || cv.clientWidth);
            return { px, py, wx: vp.fromX(px), wy: vp.fromY(py), vp };
        };
        cv.addEventListener('wheel', (e) => {
            e.preventDefault();
            const r = cv.getBoundingClientRect();
            wifiHmZoom(e.deltaY < 0 ? 1.25 : 0.8, e.clientX - r.left, e.clientY - r.top);
        }, { passive: false });
        cv.addEventListener('pointerdown', (e) => {
            _wifiHm.suppressClick = false;  // fresh press — never carry a stale flag
            const p = norm(e);
            // Design objects win the press (but not the 2nd click of a wall).
            if (_wifiHm.mode === 'design' && !_wifiHm.wallStart) {
                const hit = _wifiHmHitTest(p);
                if (hit) {
                    _wifiHm.drag = hit; _wifiHm.dragMoved = false;
                    try { cv.setPointerCapture(e.pointerId); } catch (_) {}
                    cv.style.cursor = hit.kind === 'column-resize' ? 'nwse-resize' : 'grabbing';
                    e.preventDefault();
                    return;
                }
            }
            // Empty area: a drag pans the zoomed view. At 100% there is nothing
            // to pan, so leave the press alone (it stays a plain sample click).
            if (_wifiHm.view.zoom > 1 || e.shiftKey || e.button === 1) {
                _wifiHm.pan = { sx: e.clientX, sy: e.clientY,
                    cx: _wifiHm.view.cx, cy: _wifiHm.view.cy, active: false };
                try { cv.setPointerCapture(e.pointerId); } catch (_) {}
            }
        });
        cv.addEventListener('pointermove', (e) => {
            if (_wifiHm.pan) {
                const dx = e.clientX - _wifiHm.pan.sx, dy = e.clientY - _wifiHm.pan.sy;
                if (!_wifiHm.pan.active && Math.hypot(dx, dy) > 4) _wifiHm.pan.active = true;
                if (_wifiHm.pan.active) {
                    const vp = _wifiHmViewport(cv.clientWidth, cv.clientHeight || cv.clientWidth);
                    _wifiHm.view.cx = _wifiHm.pan.cx - dx / vp.pw * vp.span;
                    _wifiHm.view.cy = _wifiHm.pan.cy - dy / vp.ph * vp.span;
                    _wifiHmClampView();
                    cv.style.cursor = 'grabbing';
                    _wifiHmDragRender();
                }
                return;
            }
            const p = norm(e);
            if (!_wifiHm.drag) {
                if (_wifiHm.mode === 'design' && !_wifiHm.wallStart) {
                    const hit = _wifiHmHitTest(p);
                    cv.style.cursor = hit ? (hit.kind === 'column-resize' ? 'nwse-resize' : 'grab') : '';
                }
                return;
            }
            _wifiHmApplyDrag(p.wx, p.wy);
            _wifiHm.dragMoved = true;
            _wifiHmDragRender();
        });
        const endDrag = (e) => {
            if (_wifiHm.pan) {
                if (_wifiHm.pan.active) _wifiHm.suppressClick = true;  // a pan is not a click
                _wifiHm.pan = null; cv.style.cursor = '';
                try { cv.releasePointerCapture(e.pointerId); } catch (_) {}
                return;
            }
            if (!_wifiHm.drag) return;
            if (_wifiHm.dragMoved) {
                if (_wifiHm.drag.kind === 'ap') _wifiHmPersistAp();
                else if (_wifiHm.drag.kind === 'column' || _wifiHm.drag.kind === 'column-resize') _wifiHmPersistColumns();
                else _wifiHmPersistWalls();
            }
            _wifiHm.suppressClick = true;   // swallow the click that follows this press
            _wifiHm.drag = null; cv.style.cursor = '';
            try { cv.releasePointerCapture(e.pointerId); } catch (_) {}
            wifiHeatmapRender();
        };
        cv.addEventListener('pointerup', endDrag);
        cv.addEventListener('pointercancel', endDrag);
    }
}

function wifiThroughputTest() {
    const st = document.getElementById('wifi-hm-tp-status');
    const iperf = (document.getElementById('wifi-hm-iperf').value || '').trim();
    const secs = parseInt(document.getElementById('wifi-hm-tp-secs').value) || 5;
    st.textContent = 'Testing (~' + (iperf ? secs * 2 + 5 : secs + 3) + 's)…';
    fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'throughput', iperf_server: iperf, seconds: secs }) })
        .then(r => r.json()).then(d => {
            const dn = d.down_mbps != null ? d.down_mbps + '↓' : '—';
            const up = d.up_mbps != null ? ' ' + d.up_mbps + '↑' : '';
            const lat = d.latency_ms != null ? ` · ${d.latency_ms}ms` : '';
            const loss = d.loss_pct ? ` · ${d.loss_pct}% loss` : '';
            st.innerHTML = `<b>${dn}${up}</b> Mbps${lat}${loss} <span class="text-gray-600">(${d.method})</span>`
                + (d.error ? ` <span class="text-amber-400">⚠ ${d.error}</span>` : '');
        }).catch(() => { st.textContent = 'test failed'; });
}

// ---- Design / predictive coverage ------------------------------------------
function wifiHmSetMode(m) {
    _wifiHm.mode = m;
    const survey = m === 'survey';
    document.getElementById('wifi-hm-mode-survey').className =
        'wifi-hm-seg-btn ' + (survey ? 'wifi-hm-seg-on' : 'wifi-hm-seg-off');
    document.getElementById('wifi-hm-mode-design').className =
        'wifi-hm-seg-btn ' + (!survey ? 'wifi-hm-seg-on' : 'wifi-hm-seg-off');
    document.getElementById('wifi-hm-design-tools').classList.toggle('hidden', survey);
    _wifiHm.wallStart = null;
    wifiHeatmapRender();
}

function wifiHmSetTool(t) {
    _wifiHm.tool = t;
    _wifiHm.wallStart = null;
    const sel = (id, on) => { const el = document.getElementById(id); if (el)
        el.className = 'wifi-hm-seg-btn ' + (on ? 'wifi-hm-seg-on' : 'wifi-hm-seg-off'); };
    sel('wifi-hm-tool-wall', t === 'wall');
    sel('wifi-hm-tool-ap', t === 'ap');
    sel('wifi-hm-tool-column', t === 'column');
    const st = document.getElementById('wifi-hm-design-status');
    const msg = { wall: 'Click two points to draw a wall — or drag an existing wall to move it.',
        ap: 'Click the plan to drop an AP node (add several for a mesh) — or drag a node to move it.',
        column: 'Click to drop a structural column (pillar) — drag it to move, or drag its white edge handle to resize. Columns shadow WiFi behind them.' };
    if (st) st.textContent = msg[t] || '';
}

// ---- Drag existing objects (AP nodes + walls) ------------------------------
function _wifiPtSegDistPx(px, py, x1, y1, x2, y2) {
    const dx = x2 - x1, dy = y2 - y1;
    const len2 = dx * dx + dy * dy;
    let t = len2 ? ((px - x1) * dx + (py - y1) * dy) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

// Screen-space radius (px) a column is drawn at — kept in sync with _wifiHmDrawDesign.
function _wifiHmColumnPxRadius(c, vp) {
    const floorM = _wifiHmFloorM();
    const pxPerM = vp.pw / (vp.span * floorM);
    return Math.max(5, (c.radius_m || 0.3) * pxPerM);
}

// Hit-test a pointer position (p = {px,py,wx,wy,vp} from norm()) against AP
// nodes (top), column resize handles, column bodies, then wall endpoints, then
// wall bodies. Returns a drag descriptor (offsets in world/normalized coords)
// or null. Distances in CSS px.
function _wifiHmHitTest(p) {
    const { px, py, wx, wy, vp } = p, R = 12;
    for (let i = _wifiHm.predictAps.length - 1; i >= 0; i--) {
        const ap = _wifiHm.predictAps[i];
        if (Math.hypot(vp.toX(ap.x) - px, vp.toY(ap.y) - py) <= R)
            return { kind: 'ap', idx: i, ox: ap.x - wx, oy: ap.y - wy };
    }
    // Resize handle sits on the column's edge (45°) — checked before the body
    // hit-test below so it wins even though it's inside the column's own radius.
    for (let i = _wifiHm.columns.length - 1; i >= 0; i--) {
        const c = _wifiHm.columns[i];
        const rpx = _wifiHmColumnPxRadius(c, vp);
        const hx = vp.toX(c.x) + rpx * Math.SQRT1_2, hy = vp.toY(c.y) + rpx * Math.SQRT1_2;
        if (Math.hypot(hx - px, hy - py) <= 8)
            return { kind: 'column-resize', idx: i };
    }
    for (let i = _wifiHm.columns.length - 1; i >= 0; i--) {
        const c = _wifiHm.columns[i];
        const rpx = _wifiHmColumnPxRadius(c, vp);
        if (Math.hypot(vp.toX(c.x) - px, vp.toY(c.y) - py) <= Math.max(R, rpx))
            return { kind: 'column', idx: i, ox: c.x - wx, oy: c.y - wy };
    }
    for (let i = _wifiHm.walls.length - 1; i >= 0; i--) {
        const w = _wifiHm.walls[i];
        if (Math.hypot(vp.toX(w.x1) - px, vp.toY(w.y1) - py) <= R)
            return { kind: 'wall-end', idx: i, end: 1, ox: w.x1 - wx, oy: w.y1 - wy };
        if (Math.hypot(vp.toX(w.x2) - px, vp.toY(w.y2) - py) <= R)
            return { kind: 'wall-end', idx: i, end: 2, ox: w.x2 - wx, oy: w.y2 - wy };
    }
    for (let i = _wifiHm.walls.length - 1; i >= 0; i--) {
        const w = _wifiHm.walls[i];
        if (_wifiPtSegDistPx(px, py, vp.toX(w.x1), vp.toY(w.y1), vp.toX(w.x2), vp.toY(w.y2)) <= 8)
            return { kind: 'wall', idx: i, ox: wx, oy: wy };  // ox/oy = last anchor
    }
    return null;
}

const _clamp01 = v => Math.max(0, Math.min(1, v));

function _wifiHmApplyDrag(nx, ny) {
    const d = _wifiHm.drag; if (!d) return;
    if (d.kind === 'ap') {
        const ap = _wifiHm.predictAps[d.idx]; if (!ap) return;
        ap.x = _clamp01(nx + d.ox); ap.y = _clamp01(ny + d.oy);
    } else if (d.kind === 'column') {
        const c = _wifiHm.columns[d.idx]; if (!c) return;
        c.x = _clamp01(nx + d.ox); c.y = _clamp01(ny + d.oy);
    } else if (d.kind === 'column-resize') {
        const c = _wifiHm.columns[d.idx]; if (!c) return;
        const floorM = _wifiHmFloorM();
        const distM = Math.hypot((nx - c.x) * floorM, (ny - c.y) * floorM);
        c.radius_m = Math.max(0.05, Math.min(3, Math.round(distM * 20) / 20));
    } else if (d.kind === 'wall-end') {
        const w = _wifiHm.walls[d.idx]; if (!w) return;
        if (d.end === 1) { w.x1 = _clamp01(nx + d.ox); w.y1 = _clamp01(ny + d.oy); }
        else { w.x2 = _clamp01(nx + d.ox); w.y2 = _clamp01(ny + d.oy); }
    } else if (d.kind === 'wall') {
        const w = _wifiHm.walls[d.idx]; if (!w) return;
        const mx = nx - d.ox, my = ny - d.oy;  // incremental delta from last anchor
        w.x1 = _clamp01(w.x1 + mx); w.y1 = _clamp01(w.y1 + my);
        w.x2 = _clamp01(w.x2 + mx); w.y2 = _clamp01(w.y2 + my);
        d.ox = nx; d.oy = ny;
    }
}

function _wifiHmDragRender() {
    if (_wifiHm._rafPending) return;
    _wifiHm._rafPending = true;
    requestAnimationFrame(() => { _wifiHm._rafPending = false; wifiHeatmapRender(); });
}

function _wifiHmDesignClick(x, y) {
    const st = document.getElementById('wifi-hm-design-status');
    if (_wifiHm.tool === 'ap') {
        // The floor is a square of floorM × floorM metres (matches the rulers).
        const m = _wifiHmFloorM();
        _wifiHm.predictAps.push({ x, y, tx_dbm: 20, freq: 5200, ple: 3.0, width_m: m, height_m: m });
        _wifiHmPersistAp();
        const n = _wifiHm.predictAps.length;
        if (st) st.textContent = `${n} node${n > 1 ? 's' : ''} placed — click to add more, or tick “Predict coverage”.`;
        wifiHeatmapRender();
        return;
    }
    if (_wifiHm.tool === 'column') {
        const mat = document.getElementById('wifi-hm-col-mat').value;
        const rad = parseFloat(document.getElementById('wifi-hm-col-rad').value) || 0.3;
        _wifiHm.columns.push({ x, y, radius_m: rad, loss_db: _WIFI_WALL_DB[mat] || 15, material: mat });
        _wifiHmPersistColumns();
        const n = _wifiHm.columns.length;
        if (st) st.textContent = `${n} column${n > 1 ? 's' : ''} placed — they shadow WiFi behind them.`;
        wifiHeatmapRender();
        return;
    }
    // Wall tool: first click = start, second = end.
    if (!_wifiHm.wallStart) {
        _wifiHm.wallStart = { x, y };
        if (st) st.textContent = 'Click the wall’s end point…';
        wifiHeatmapRender();
    } else {
        const mat = document.getElementById('wifi-hm-wall-mat').value;
        _wifiHm.walls.push({ x1: _wifiHm.wallStart.x, y1: _wifiHm.wallStart.y, x2: x, y2: y,
            loss_db: _WIFI_WALL_DB[mat] || 5, material: mat });
        _wifiHm.wallStart = null;
        _wifiHmPersistWalls();
        if (st) st.textContent = `${_wifiHm.walls.length} wall(s).`;
        wifiHeatmapRender();
    }
}

function wifiHmUndoWall() {
    _wifiHm.walls.pop(); _wifiHm.wallStart = null;
    _wifiHmPersistWalls(); wifiHeatmapRender();
}

function wifiHmClearWalls() {
    _wifiHm.walls = []; _wifiHm.wallStart = null;
    _wifiHmPersistWalls(); wifiHeatmapRender();
}

function wifiHmUndoColumn() {
    _wifiHm.columns.pop();
    _wifiHmPersistColumns(); wifiHeatmapRender();
}

function wifiHmClearColumns() {
    _wifiHm.columns = [];
    _wifiHmPersistColumns(); wifiHeatmapRender();
}

function wifiHmTogglePredict() {
    _wifiHm.predicting = document.getElementById('wifi-hm-predict').checked;
    const st = document.getElementById('wifi-hm-design-status');
    if (_wifiHm.predicting && !_wifiHm.predictAps.length && st)
        st.textContent = 'Place at least one node first (Place AP → click the plan).';
    wifiHeatmapRender();
}

function wifiHmUndoAp() {
    _wifiHm.predictAps.pop();
    _wifiHmPersistAp();
    const st = document.getElementById('wifi-hm-design-status');
    const n = _wifiHm.predictAps.length;
    if (st) st.textContent = n ? `${n} node${n > 1 ? 's' : ''} placed.` : 'No nodes placed.';
    wifiHeatmapRender();
}

function wifiHmClearAps() {
    _wifiHm.predictAps = [];
    _wifiHmPersistAp();
    const st = document.getElementById('wifi-hm-design-status');
    if (st) st.textContent = 'Nodes cleared.';
    wifiHeatmapRender();
}

// ---- Mesh survey (whole-SSID, per-node coverage) ---------------------------
function wifiHmToggleMesh() {
    _wifiHm.mesh = document.getElementById('wifi-hm-mesh').checked;
    document.getElementById('wifi-hm-target-label').textContent = _wifiHm.mesh ? 'Mesh SSID' : 'Target AP';
    document.querySelectorAll('.wifi-hm-mesh-metric').forEach(o => { o.hidden = !_wifiHm.mesh; });
    const msel = document.getElementById('wifi-hm-metric');
    if (!_wifiHm.mesh && (msel.value === 'serving' || msel.value === 'handoff')) {
        msel.value = 'rssi'; _wifiHm.metric = 'rssi';
    }
    if (_wifiHm.mesh) wifiHeatmapPopulateSsids(); else wifiHeatmapPopulateAps();
    wifiHeatmapRender();
}

function wifiHeatmapPopulateSsids() {
    const sel = document.getElementById('wifi-hm-ap'); if (!sel) return;
    const cur = sel.value;
    const nets = (_wifiState.data && _wifiState.data.groups && _wifiState.data.groups.networks) || [];
    const named = nets.filter(n => n.ssid);
    sel.innerHTML = named.length ? named.map(n =>
        `<option value="${_esc(n.ssid)}">${_esc(n.ssid)} · ${n.ap_count} node${n.ap_count > 1 ? 's' : ''}${n.ap_count > 1 ? ' 🕸' : ''} · ${n.best_signal}dBm</option>`).join('')
        : '<option value="">No networks — scan first</option>';
    if (cur && named.some(n => n.ssid === cur)) sel.value = cur;
}

function _wifiMeshInterp(wx, wy, bssid, samples, floorM) {
    let num = 0, den = 0;
    for (const sp of samples) {
        const v = sp.nodes && sp.nodes[bssid];
        if (v == null) continue;
        // IDW in real metres, so the falloff matches the floor scale.
        const dx = (sp.x - wx) * floorM, dy = (sp.y - wy) * floorM, d2 = dx * dx + dy * dy;
        const w = 1 / (d2 + 0.25); num += w * v; den += w;
    }
    return den ? num / den : null;
}

function _wifiRenderMeshGrid(ctx, vp, floorM, mode) {
    const samples = ((_wifiHm.data && _wifiHm.data.samples) || []).filter(s => s.nodes);
    if (!samples.length) return;
    const nodes = _wifiMeshNodeList();
    const cell = 12;
    for (let gx = vp.ML; gx < vp.ML + vp.pw; gx += cell) {
        for (let gy = vp.MT; gy < vp.MT + vp.ph; gy += cell) {
            const px = vp.fromX(gx + cell / 2), py = vp.fromY(gy + cell / 2);
            if (px < 0 || px > 1 || py < 0 || py > 1) continue;
            const est = nodes.map(b => ({ bssid: b, rssi: _wifiMeshInterp(px, py, b, samples, floorM) }))
                .filter(n => n.rssi != null).sort((a, b) => b.rssi - a.rssi);
            if (!est.length) continue;
            const top1 = est[0], top2 = est[1];
            let fill;
            if (mode === 'serving') {
                const [r, g, b] = _wifiHexToRgb(_wifiMeshColor(top1.bssid));
                const a = Math.max(0.12, Math.min(0.6, (top1.rssi + 90) / 50));
                fill = `rgba(${r},${g},${b},${a})`;
            } else { // handoff
                if (!top2) { fill = 'rgba(100,116,139,0.15)'; }        // single node here
                else {
                    const margin = top1.rssi - top2.rssi;
                    const c = margin < 6 ? [34, 197, 94] : margin < 12 ? [234, 179, 8] : [239, 68, 68];
                    fill = `rgba(${c[0]},${c[1]},${c[2]},0.4)`;
                }
            }
            ctx.fillStyle = fill; ctx.fillRect(gx, gy, cell, cell);
        }
    }
}

function _wifiHexToRgb(hex) {
    const n = parseInt(hex.slice(1), 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function _wifiHmPersistWalls() {
    fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'walls', walls: _wifiHm.walls }) }).catch(() => {});
}
function _wifiHmPersistAp() {
    fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'predict_aps', aps: _wifiHm.predictAps }) }).catch(() => {});
}
function _wifiHmPersistColumns() {
    fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'columns', columns: _wifiHm.columns }) }).catch(() => {});
}

// Segment intersection + predicted RSSI — mirror of wifi_analyzer.py.
function _wifiSegCross(a, b, c, d) {
    const ccw = (px, py, qx, qy, rx, ry) => (ry - py) * (qx - px) > (qy - py) * (rx - px);
    return ccw(a.x, a.y, c.x, c.y, d.x, d.y) !== ccw(b.x, b.y, c.x, c.y, d.x, d.y)
        && ccw(a.x, a.y, b.x, b.y, c.x, c.y) !== ccw(a.x, a.y, b.x, b.y, d.x, d.y);
}
// Distance from a column centre to the AP→point line (metres) <= radius => shadow.
function _wifiSegCircleHit(ax, ay, bx, by, cx, cy, r) {
    const dx = bx - ax, dy = by - ay, len2 = dx * dx + dy * dy;
    let t = len2 ? ((cx - ax) * dx + (cy - ay) * dy) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(cx - (ax + t * dx), cy - (ay + t * dy)) <= r;
}
function _wifiPredictRssiOne(px, py, ap) {
    const fspl1m = 20 * Math.log10(ap.freq) - 27.55;
    const rssi0 = ap.tx_dbm - fspl1m;
    const dx = (px - ap.x) * ap.width_m, dy = (py - ap.y) * ap.height_m;
    const dist = Math.max(0.5, Math.hypot(dx, dy));
    let rssi = rssi0 - 10 * ap.ple * Math.log10(dist);
    const a = { x: ap.x, y: ap.y }, b = { x: px, y: py };
    for (const w of _wifiHm.walls) {
        if (_wifiSegCross(a, b, { x: w.x1, y: w.y1 }, { x: w.x2, y: w.y2 })) rssi -= (w.loss_db || 5);
    }
    // Columns shadow the line in metres (same floor size as the AP).
    for (const c of _wifiHm.columns) {
        if (_wifiSegCircleHit(ap.x * ap.width_m, ap.y * ap.height_m, px * ap.width_m, py * ap.height_m,
                c.x * ap.width_m, c.y * ap.height_m, c.radius_m || 0.3)) rssi -= (c.loss_db || 15);
    }
    return rssi;
}
// Predicted coverage of a mesh = the BEST signal any placed node delivers here
// (each spot is served by its strongest node), matching real mesh behaviour.
function _wifiPredictRssi(px, py) {
    const aps = _wifiHm.predictAps; if (!aps || !aps.length) return null;
    let best = -Infinity;
    for (const ap of aps) best = Math.max(best, _wifiPredictRssiOne(px, py, ap));
    return best;
}

function wifiHeatmapPopulateAps() {
    const sel = document.getElementById('wifi-hm-ap'); if (!sel) return;
    const cur = sel.value;
    const aps = (_wifiState.data && _wifiState.data.aps) || [];
    sel.innerHTML = aps.length ? aps.map(a =>
        `<option value="${a.bssid}">${(a.ssid || 'hidden')} · ${a.band}GHz ch${a.channel} · ${a.signal}dBm</option>`).join('')
        : '<option value="">No APs — scan first</option>';
    if (cur && aps.some(a => a.bssid === cur)) sel.value = cur;
    else if (_wifiHm.data && _wifiHm.data.target_bssid) sel.value = _wifiHm.data.target_bssid;
}

function wifiHeatmapLoad() {
    fetch('/api/net/wifi/heatmap').then(r => r.json()).then(d => {
        _wifiHm.data = d;
        _wifiHm.walls = d.walls || [];
        _wifiHm.columns = d.columns || [];
        _wifiHm.predictAps = d.predict_aps || (d.predict_ap ? [d.predict_ap] : []);
        // A loaded design carries its real floor size — reflect it in the UI.
        const sc = document.getElementById('wifi-hm-scale');
        if (sc && _wifiHm.predictAps.length && _wifiHm.predictAps[0].width_m)
            sc.value = _wifiHm.predictAps[0].width_m;
        _wifiHmSyncScaleUI();
        const st = document.getElementById('wifi-hm-status');
        if (st && d.samples) st.textContent = d.samples.length + ' sample(s)';
        if (d.floorplan) {
            const img = new Image();
            img.onload = () => { _wifiHm.floorplan = img; wifiHeatmapRender(); };
            img.src = d.floorplan;
        } else { _wifiHm.floorplan = null; wifiHeatmapRender(); }
    }).catch(() => {});
}

function wifiHeatmapRender() {
    const cv = document.getElementById('wifi-heatmap'); if (!cv) return;
    const dpr = window.devicePixelRatio || 1;
    const W = cv.clientWidth, H = cv.clientHeight || W;
    if (!W) return;
    cv.width = W * dpr; cv.height = H * dpr;
    const ctx = cv.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    _wifiHmClampView();
    const vp = _wifiHmViewport(W, H);
    const floorM = _wifiHmFloorM();
    const zl = document.getElementById('wifi-hm-zoom-pct');
    if (zl) zl.textContent = Math.round(_wifiHm.view.zoom * 100) + '%';
    // Floor plot background; everything on the floor is clipped to it so the
    // ruler margins stay clean while zoomed.
    ctx.fillStyle = '#0b1220';
    ctx.fillRect(vp.ML, vp.MT, vp.pw, vp.ph);
    ctx.save();
    ctx.beginPath(); ctx.rect(vp.ML, vp.MT, vp.pw, vp.ph); ctx.clip();
    // Floorplan (contain, centred on the square floor)
    if (_wifiHm.floorplan) {
        const im = _wifiHm.floorplan;
        const s = Math.min(1 / im.width, 1 / im.height);   // world units per image px
        const iw = im.width * s, ih = im.height * s;
        const pxPerWorld = vp.pw / vp.span;
        ctx.globalAlpha = 0.85;
        ctx.drawImage(im, vp.toX((1 - iw) / 2), vp.toY((1 - ih) / 2), iw * pxPerWorld, ih * pxPerWorld);
        ctx.globalAlpha = 1;
    }
    const design = _wifiHm.mode === 'design';
    // --- Predicted coverage grid (design mode) — modelled RSSI everywhere ---
    if (design && _wifiHm.predicting && _wifiHm.predictAps.length) {
        const savedMetric = _wifiHm.metric; _wifiHm.metric = 'rssi';
        const cell = 10;
        for (let gx = vp.ML; gx < vp.ML + vp.pw; gx += cell) {
            for (let gy = vp.MT; gy < vp.MT + vp.ph; gy += cell) {
                const wx = vp.fromX(gx + cell / 2), wy = vp.fromY(gy + cell / 2);
                if (wx < 0 || wx > 1 || wy < 0 || wy > 1) continue;
                const val = _wifiPredictRssi(wx, wy);
                const [r, g, b] = _wifiHeatColor(val);
                ctx.fillStyle = `rgba(${r},${g},${b},0.45)`;
                ctx.fillRect(gx, gy, cell, cell);
            }
        }
        _wifiHm.metric = savedMetric;
    }
    // --- Mesh serving-node / hand-off map (survey mode, mesh metrics) ---
    const meshMode = !design && (_wifiHm.metric === 'serving' || _wifiHm.metric === 'handoff');
    if (meshMode) _wifiRenderMeshGrid(ctx, vp, floorM, _wifiHm.metric);
    // --- Survey samples (shown in both modes as the base layer; skip IDW when showing a mesh map) ---
    const allSamples = (_wifiHm.data && _wifiHm.data.samples) || [];
    const samples = (meshMode ? [] : allSamples).filter(sp => _wifiHmValue(sp) != null);
    if (samples.length >= 1) {
        const cell = 12;
        for (let gx = vp.ML; gx < vp.ML + vp.pw; gx += cell) {
            for (let gy = vp.MT; gy < vp.MT + vp.ph; gy += cell) {
                const wx = vp.fromX(gx + cell / 2), wy = vp.fromY(gy + cell / 2);
                if (wx < 0 || wx > 1 || wy < 0 || wy > 1) continue;
                let num = 0, den = 0, near = 1e9;
                samples.forEach(sp => {
                    // IDW in real metres so the blend matches the floor scale.
                    const dx = (sp.x - wx) * floorM, dy = (sp.y - wy) * floorM;
                    const d2 = dx * dx + dy * dy; near = Math.min(near, d2);
                    const w = 1 / (d2 + 0.25);
                    num += w * _wifiHmValue(sp); den += w;
                });
                if (den === 0) continue;
                const [r, g, b] = _wifiHeatColor(num / den);
                // Fade with metre distance to the nearest sample.
                const a = Math.max(0.08, Math.min(0.5, 1 - Math.sqrt(near) / (floorM * 0.6)));
                ctx.fillStyle = `rgba(${r},${g},${b},${a})`;
                ctx.fillRect(gx, gy, cell, cell);
            }
        }
    }
    allSamples.forEach(sp => {
        const x = vp.toX(sp.x), y = vp.toY(sp.y);
        ctx.beginPath(); ctx.arc(x, y, 5, 0, 2 * Math.PI);
        if (meshMode) {
            // Dot coloured by the node serving that spot; label = node index.
            ctx.fillStyle = sp.serving ? _wifiMeshColor(sp.serving) : '#64748b';
            ctx.fill(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.stroke();
            const idx = _wifiMeshNodeList().indexOf(sp.serving);
            ctx.fillStyle = '#e2e8f0'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
            ctx.fillText(idx >= 0 ? String.fromCharCode(65 + idx) : '?', x, y - 8);
            return;
        }
        const val = _wifiHmValue(sp);
        const [r, g, b] = val == null ? [100, 116, 139] : _wifiHeatColor(val);
        ctx.fillStyle = `rgb(${r},${g},${b})`; ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.stroke();
        ctx.fillStyle = '#e2e8f0'; ctx.font = '9px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText(val == null ? '—' : Math.round(val), x, y - 8);
    });
    // --- Design overlays: walls + modelled AP ---
    if (design) _wifiHmDrawDesign(ctx, vp);
    if (!allSamples.length && !_wifiHm.floorplan && !design) {
        ctx.fillStyle = '#475569'; ctx.font = '13px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText(_wifiHm.mesh ? 'Pick a mesh SSID, then click where you are standing to map every node.'
            : 'Pick a target AP, then click on the plan where you are standing to drop RSSI samples.',
            vp.ML + vp.pw / 2, vp.MT + vp.ph / 2);
    }
    ctx.restore();
    _wifiHmDrawRulers(ctx, vp, floorM);
    wifiHeatmapRenderLegend();
}

// Metre rulers along the left + bottom edges, with a matching grid across the
// floor. Tick spacing adapts to zoom so labels stay ~44 px apart.
function _wifiHmDrawRulers(ctx, vp, floorM) {
    const mPerPx = (floorM * vp.span) / vp.pw;
    const steps = [0.01, 0.02, 0.05, 0.1, 0.2, 0.25, 0.5, 1, 2, 2.5, 5, 10, 20, 25, 50, 100];
    const step = steps.find(s => s / mPerPx >= 44) || 200;
    const fmt = m => String(Math.round(m * 100) / 100);
    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1;
    ctx.strokeRect(vp.ML + 0.5, vp.MT + 0.5, vp.pw - 1, vp.ph - 1);
    ctx.font = '9px sans-serif';
    const x0m = vp.x0 * floorM, x1m = (vp.x0 + vp.span) * floorM;
    const y0m = vp.y0 * floorM, y1m = (vp.y0 + vp.span) * floorM;
    for (let i = Math.ceil(x0m / step - 1e-6); i * step <= x1m + 1e-6; i++) {
        const m = i * step, px = vp.toX(m / floorM);
        ctx.strokeStyle = 'rgba(148,163,184,0.12)';
        ctx.beginPath(); ctx.moveTo(px, vp.MT); ctx.lineTo(px, vp.MT + vp.ph); ctx.stroke();
        ctx.strokeStyle = '#475569';
        ctx.beginPath(); ctx.moveTo(px, vp.MT + vp.ph); ctx.lineTo(px, vp.MT + vp.ph + 4); ctx.stroke();
        ctx.fillStyle = '#64748b'; ctx.textAlign = 'center'; ctx.textBaseline = 'top';
        ctx.fillText(fmt(m), px, vp.MT + vp.ph + 6);
    }
    for (let i = Math.ceil(y0m / step - 1e-6); i * step <= y1m + 1e-6; i++) {
        const m = i * step, py = vp.toY(m / floorM);
        ctx.strokeStyle = 'rgba(148,163,184,0.12)';
        ctx.beginPath(); ctx.moveTo(vp.ML, py); ctx.lineTo(vp.ML + vp.pw, py); ctx.stroke();
        ctx.strokeStyle = '#475569';
        ctx.beginPath(); ctx.moveTo(vp.ML - 4, py); ctx.lineTo(vp.ML, py); ctx.stroke();
        ctx.fillStyle = '#64748b'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
        ctx.fillText(fmt(m), vp.ML - 6, py);
    }
    // Context line above the plot: floor size (+ visible window when zoomed).
    const vis = floorM * vp.span;
    ctx.fillStyle = '#64748b'; ctx.font = '10px sans-serif';
    ctx.textAlign = 'left'; ctx.textBaseline = 'bottom';
    ctx.fillText(`floor ${floorM} × ${floorM} m (${Math.round(floorM * floorM)} m²) · axes in metres`
        + (_wifiHm.view.zoom > 1.001 ? ` · viewing ${vis.toFixed(1)} × ${vis.toFixed(1)} m` : ''),
        vp.ML, vp.MT - 5);
}

function _wifiHmDrawDesign(ctx, vp) {
    // Walls
    ctx.lineCap = 'round';
    _wifiHm.walls.forEach(w => {
        const col = _wifiMatColor(w.material);
        ctx.beginPath();
        ctx.moveTo(vp.toX(w.x1), vp.toY(w.y1)); ctx.lineTo(vp.toX(w.x2), vp.toY(w.y2));
        // Dark casing for contrast on any floorplan, then the material colour.
        ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 4.5; ctx.stroke();
        ctx.strokeStyle = col; ctx.lineWidth = 2.5; ctx.stroke();
        // Draggable endpoint handles, tinted to the material.
        [[w.x1, w.y1], [w.x2, w.y2]].forEach(([ex, ey]) => {
            ctx.beginPath(); ctx.arc(vp.toX(ex), vp.toY(ey), 3.5, 0, 2 * Math.PI);
            ctx.fillStyle = col; ctx.fill();
            ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 1.5; ctx.stroke();
        });
    });
    // Wall-in-progress preview (tinted to the currently-selected material)
    if (_wifiHm.wallStart) {
        const s = _wifiHm.wallStart;
        const matEl = document.getElementById('wifi-hm-wall-mat');
        ctx.beginPath(); ctx.arc(vp.toX(s.x), vp.toY(s.y), 4, 0, 2 * Math.PI);
        ctx.fillStyle = _wifiMatColor(matEl && matEl.value); ctx.fill();
        ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 1.5; ctx.stroke();
    }
    // Structural columns — round pillars drawn to scale, coloured by material
    _wifiHm.columns.forEach(c => {
        const x = vp.toX(c.x), y = vp.toY(c.y);
        const rpx = _wifiHmColumnPxRadius(c, vp);
        ctx.beginPath(); ctx.arc(x, y, rpx, 0, 2 * Math.PI);
        ctx.fillStyle = _wifiMatColor(c.material); ctx.globalAlpha = 0.9; ctx.fill(); ctx.globalAlpha = 1;
        ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 2; ctx.stroke();
        // cross-hatch to read as "solid structure"
        ctx.strokeStyle = 'rgba(11,18,32,0.5)'; ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x - rpx * 0.7, y - rpx * 0.7); ctx.lineTo(x + rpx * 0.7, y + rpx * 0.7);
        ctx.moveTo(x - rpx * 0.7, y + rpx * 0.7); ctx.lineTo(x + rpx * 0.7, y - rpx * 0.7);
        ctx.stroke();
        // Resize handle on the edge (45°) — drag to change radius.
        const hx = x + rpx * Math.SQRT1_2, hy = y + rpx * Math.SQRT1_2;
        ctx.beginPath(); ctx.arc(hx, hy, 4, 0, 2 * Math.PI);
        ctx.fillStyle = '#fff'; ctx.fill();
        ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 1.5; ctx.stroke();
    });
    // Modelled AP nodes (a planned mesh) — labelled AP1, AP2, …
    _wifiHm.predictAps.forEach((ap, i) => {
        const x = vp.toX(ap.x), y = vp.toY(ap.y);
        ctx.beginPath(); ctx.arc(x, y, 8, 0, 2 * Math.PI);
        ctx.fillStyle = '#22d3ee'; ctx.fill();
        ctx.strokeStyle = '#0b1220'; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center';
        ctx.fillText('AP' + (i + 1), x, y - 12);
    });
}

function wifiHeatmapClear() {
    fetch('/api/net/wifi/heatmap', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'clear' }) }).then(() => wifiHeatmapLoad());
}

// ---- Named surveys (save / load / delete a floorplan+samples set) ----------
function wifiSurveyRefresh(list) {
    const done = (d) => {
        const sel = document.getElementById('wifi-hm-survey'); if (!sel) return;
        const cur = sel.value;
        const surveys = (d && d.surveys) || [];
        sel.innerHTML = surveys.length
            ? surveys.map(s => `<option value="${s.name}">${s.name} · ${s.samples} pts${s.target_ssid ? ' · ' + s.target_ssid : ''}</option>`).join('')
            : '<option value="">— none saved —</option>';
        if (cur && surveys.some(s => s.name === cur)) sel.value = cur;
    };
    if (list) return done(list);
    fetch('/api/net/wifi/surveys').then(r => r.json()).then(done).catch(() => {});
}

function wifiSurveySave() {
    const name = (document.getElementById('wifi-hm-survey-name').value || '').trim();
    const st = document.getElementById('wifi-hm-survey-status');
    if (!name) { if (st) st.textContent = 'name it first'; return; }
    fetch('/api/net/wifi/surveys', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'save', name }) })
        .then(r => r.json()).then(d => {
            if (d.error) { if (st) st.textContent = '⚠ ' + d.error; return; }
            if (st) st.textContent = 'saved “' + name + '”';
            document.getElementById('wifi-hm-survey-name').value = '';
            wifiSurveyRefresh(d);
        }).catch(() => { if (st) st.textContent = 'save failed'; });
}

function wifiSurveyLoad() {
    const name = document.getElementById('wifi-hm-survey').value;
    const st = document.getElementById('wifi-hm-survey-status');
    if (!name) return;
    fetch('/api/net/wifi/surveys', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'load', name }) })
        .then(r => r.json()).then(d => {
            if (d.error) { if (st) st.textContent = '⚠ ' + d.error; return; }
            if (st) st.textContent = 'loaded “' + name + '”';
            wifiHeatmapLoad();
        }).catch(() => { if (st) st.textContent = 'load failed'; });
}

function wifiSurveyDelete() {
    const name = document.getElementById('wifi-hm-survey').value;
    const st = document.getElementById('wifi-hm-survey-status');
    if (!name) return;
    fetch('/api/net/wifi/surveys', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delete', name }) })
        .then(r => r.json()).then(d => { if (st) st.textContent = 'deleted “' + name + '”'; wifiSurveyRefresh(d); })
        .catch(() => { if (st) st.textContent = 'delete failed'; });
}

// ============================================================================
// WiFi Defense — 802.11 frame monitor / WIDS (top-level tab)
// Backend: /api/wifidef/* (wifi_defense.py)
// ============================================================================
const _wifidef = { iface: '', monitor: null, data: null, continuous: false, timer: null, abort: null };

const _WIFIDEF_THREAT = {
    clear: ['CLEAR', 'bg-green-600/20 text-green-300 border border-green-600/50'],
    warning: ['WARNING', 'bg-amber-600/20 text-amber-300 border border-amber-600/50'],
    critical: ['⚠ UNDER ATTACK', 'bg-red-600/25 text-red-300 border border-red-600/60'],
};

function initWifiDefense() {
    _wifidefFillIfaces();
    // Load the persisted beacon-flood threshold into the control.
    fetch('/api/wifidef/thresholds').then(r => r.json()).then(t => {
        const el = document.getElementById('wifidef-flood-ssids');
        if (el && t && t.beacon_ssids) el.value = t.beacon_ssids;
    }).catch(() => {});
    const auto = document.getElementById('wifidef-auto');
    if (auto && !auto._wired) {
        auto._wired = true;
        auto.addEventListener('change', (e) => {
            if (e.target.checked) _wifidefStartContinuous();
            else wifidefStopContinuous();
        });
    }
    _wifidefUpdateRunUI();
}

// Continuous mode chains scans: the next capture starts only after the previous
// one finishes (each capture already runs for `seconds`), instead of a fixed
// interval that would stack overlapping captures.
function _wifidefStartContinuous() {
    if (_wifidef.continuous) return;
    _wifidef.continuous = true;
    _wifidefUpdateRunUI();
    _wifidefLoop();
}

function _wifidefLoop() {
    if (!_wifidef.continuous) return;
    wifidefScan().finally(() => {
        if (_wifidef.continuous) _wifidef.timer = setTimeout(_wifidefLoop, 800);
    });
}

// Printable WIDS incident report from the latest capture.
function wifidefExportReport() {
    _openScanReport('/api/wifidef/report', _wifidef.data,
        'Run a WiFi Defense scan first, then export the report.');
}

function wifidefStopContinuous() {
    _wifidef.continuous = false;
    if (_wifidef.timer) { clearTimeout(_wifidef.timer); _wifidef.timer = null; }
    if (_wifidef.abort) { try { _wifidef.abort.abort(); } catch (e) {} _wifidef.abort = null; }
    const cb = document.getElementById('wifidef-auto'); if (cb) cb.checked = false;
    _wifidefUpdateRunUI();
    const st = document.getElementById('wifidef-status');
    if (st) st.textContent = 'Continuous scan stopped';
}

function _wifidefUpdateRunUI() {
    const scan = document.getElementById('wifidef-scan-btn');
    const stop = document.getElementById('wifidef-stop-btn');
    if (scan) scan.classList.toggle('hidden', _wifidef.continuous);
    if (stop) stop.classList.toggle('hidden', !_wifidef.continuous);
}

// Must match wifi_defense.py `_BUILD`. If the running service reports something
// else, the webapp is executing an OLD wifi_defense module (service not restarted
// after a git pull) — the #1 cause of "the fix didn't work in the web UI".
const WIFIDEF_BUILD = '20260730-panel-iface2';

function _wifidefFillIfaces() {
    fetch('/api/wifidef/interfaces').then(r => r.json()).then(d => {
        const sel = document.getElementById('wifidef-iface');
        const ifs = (d && d.interfaces) || [];
        _wifidef.monitor = d.active_monitor || null;
        _wifidef.mode = d.mode || null;
        _wifidef.dedicated = !!d.dedicated;
        const st = document.getElementById('wifidef-status');
        if (d.build && d.build !== WIFIDEF_BUILD && st) {
            st.innerHTML = '<span class="text-amber-400">⚠ WiFi Defense service is running old code (build '
                + _esc(d.build) + ', page expects ' + WIFIDEF_BUILD
                + '). Restart it: <code>sudo systemctl restart ragnar</code></span>';
        }
        if (!ifs.length) { sel.innerHTML = '<option value="">No wireless adapter</option>'; }
        else {
            sel.innerHTML = ifs.map(i =>
                `<option value="${i.iface}"${i.monitor_capable ? '' : ' disabled'}>${i.iface}${i.monitor_capable ? '' : ' (no monitor)'}${i.is_monitor ? ' • MONITOR' : ''}</option>`).join('');
            const cap = ifs.find(i => i.monitor_capable) || ifs[0];
            // Never let the base selection be our own monitor vif; base_iface is
            // only trusted if it's actually in the (vif-excluded) adapter list.
            const baseOk = d.base_iface && ifs.some(i => i.iface === d.base_iface);
            if (!_wifidef.iface || !ifs.some(i => i.iface === _wifidef.iface && i.monitor_capable))
                _wifidef.iface = (baseOk ? d.base_iface : cap.iface);
            sel.value = _wifidef.iface;
            sel.onchange = () => { _wifidef.iface = sel.value; };
        }
        // Per-panel wlan-only selectors (Airtime, Isolation) — independent of the
        // shared adapter picker so each panel can target a different wlan*.
        _wifidefFillPanelIface('wifidef-at-iface', ifs);
        _wifidefFillPanelIface('wifidef-iso-iface', ifs);
        _wifidefUpdateMonBtn();
    }).catch(() => {});
}

function _wifidefFillPanelIface(id, ifs) {
    const sel = document.getElementById(id);
    if (!sel) return;
    // /api/wifidef/interfaces is already wireless-only (from `iw dev`), so every
    // entry is a wlan* / wlx* / wlp* adapter or its monitor vif — list them all;
    // a name filter would wrongly drop USB (wlxNNN) and PCI (wlpNNN) adapters.
    const wlans = ifs || [];
    const prev = sel.value;
    if (!wlans.length) { sel.innerHTML = '<option value="">No wireless adapter</option>'; return; }
    sel.innerHTML = wlans.map(i =>
        `<option value="${i.iface}"${i.monitor_capable ? '' : ' disabled'}>${i.iface}${i.monitor_capable ? '' : ' (no monitor)'}${i.is_monitor ? ' • MONITOR' : ''}</option>`).join('');
    // Keep the prior choice if still present, else fall back to the shared iface
    // or the first monitor-capable adapter.
    const has = v => wlans.some(i => i.iface === v);
    sel.value = has(prev) ? prev
        : (has(_wifidef.iface) ? _wifidef.iface : (wlans.find(i => i.monitor_capable) || wlans[0]).iface);
}

function _wifidefUpdateMonBtn() {
    const btn = document.getElementById('wifidef-mon-btn');
    if (!btn) return;
    // A boot-dedicated adapter is owned by the systemd unit, not the UI: it's
    // always in monitor mode by design, so don't offer a toggle that would hand
    // it back to NetworkManager and defeat the whole point.
    if (_wifidef.dedicated) {
        btn.textContent = 'Dedicated monitor (' + (_wifidef.monitor || '') + ') — boot-managed';
        btn.classList.remove('text-red-300');
        btn.disabled = true;
        btn.classList.add('opacity-60', 'cursor-not-allowed');
        return;
    }
    btn.disabled = false;
    btn.classList.remove('opacity-60', 'cursor-not-allowed');
    if (_wifidef.monitor) {
        btn.textContent = 'Disable monitor (' + _wifidef.monitor + ')';
        btn.classList.add('text-red-300');
    } else {
        btn.textContent = 'Enable monitor';
        btn.classList.remove('text-red-300');
    }
}

function wifidefToggleMonitor() {
    const st = document.getElementById('wifidef-status');
    // Boot-dedicated monitor is managed by systemd; the UI must not toggle it.
    if (_wifidef.dedicated) {
        if (st) st.textContent = 'Adapter is a boot-dedicated monitor (managed by ragnar-wifidef-monitor.service)';
        return;
    }
    if (_wifidef.monitor) {
        // Stop any continuous scan first — otherwise its next loop would
        // immediately auto-re-enable the monitor and "disable" would look broken.
        if (_wifidef.continuous) wifidefStopContinuous();
        st.textContent = 'Disabling monitor…';
        fetch('/api/wifidef/monitor', { method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'disable' }) })
            .then(r => r.json()).then(d => { _wifidef.monitor = null; _wifidefUpdateMonBtn(); st.textContent = 'Monitor disabled'; }).catch(() => {});
        return;
    }
    const iface = _wifidef.iface || document.getElementById('wifidef-iface').value;
    if (!iface) return;
    st.textContent = 'Enabling monitor…';
    fetch('/api/wifidef/monitor', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'enable', interface: iface }) })
        .then(r => r.json()).then(d => {
            if (d.error) { st.textContent = '⚠ ' + d.error; return; }
            _wifidef.monitor = d.mon_iface;
            _wifidefUpdateMonBtn();
            st.textContent = d.warning ? ('⚠ ' + d.warning) : ('Monitor up on ' + d.mon_iface + (d.mode === 'vif' ? ' (link kept)' : ''));
        }).catch(() => { st.textContent = 'Enable failed'; });
}

// ---- Capture progress (live countdown for fixed-length captures) -----------
// Every WiFi Defense action captures for a KNOWN number of seconds, so show a
// real countdown + progress bar while the request is in flight. Past the
// capture window (monitor setup, channel tuning, analysis) it switches to a
// pulsing "analyzing…" state, so the user always sees work happening. Returns
// a handle whose done() stops the ticker; write the final status after that.
function _wifidefProgress(st, secs, label) {
    if (!st) return { done: () => {} };
    const t0 = Date.now(), total = Math.max(1, secs) * 1000;
    // Track colour is inline — bg-slate-700/80 isn't in the compiled Tailwind.
    const bar = (pct, pulse, text) =>
        '<span class="inline-flex items-center gap-1.5 align-middle">'
        + '<span class="inline-block w-28 h-1.5 rounded overflow-hidden" style="background:rgba(51,65,85,.8)">'
        + `<span class="block h-full rounded bg-Ragnar-500${pulse ? ' animate-pulse' : ''}" style="width:${pct}%"></span></span>`
        + `<span>${text}</span></span>`;
    const render = () => {
        const el = Date.now() - t0;
        if (el < total) {
            const left = Math.ceil((total - el) / 1000);
            st.innerHTML = bar(Math.min(100, Math.round(el / total * 100)), false,
                `${label} · ${left}s left`);
        } else {
            st.innerHTML = bar(100, true, 'capture done — analyzing…');
        }
    };
    render();
    const timer = setInterval(render, 500);
    return { done() { clearInterval(timer); } };
}

function wifidefScan() {
    const iface = _wifidef.iface || document.getElementById('wifidef-iface').value;
    if (!iface) return Promise.resolve();
    const secs = document.getElementById('wifidef-secs').value || 15;
    let ch = (document.getElementById('wifidef-channel').value || 'hop').trim();
    const chParam = /^\d+$/.test(ch) ? ch : 'auto';
    const st = document.getElementById('wifidef-status');
    const btn = document.getElementById('wifidef-scan-btn');
    const ctrl = new AbortController();
    _wifidef.abort = ctrl;
    const prog = _wifidefProgress(st, parseInt(secs) || 15,
        (_wifidef.continuous ? 'Continuous — capturing' : 'Capturing') + (chParam !== 'auto' ? ' ch ' + chParam : ''));
    if (btn) btn.disabled = true;
    return fetch(`/api/wifidef/scan?interface=${encodeURIComponent(iface)}&seconds=${secs}&channel=${chParam}`,
        { signal: ctrl.signal })
        .then(r => r.json()).then(d => {
            prog.done();
            if (d.error) { st.textContent = '⚠ ' + d.error; return; }
            _wifidef.monitor = d.monitor || _wifidef.monitor;
            _wifidefUpdateMonBtn();
            _wifidef.data = d;
            st.textContent = `${d.frames} frames · ${new Date(d.timestamp * 1000).toLocaleTimeString()}`
                + (_wifidef.continuous ? ' · live' : '');
            wifidefRender();
        }).catch((e) => {
            prog.done();
            if (e && e.name === 'AbortError') { st.textContent = 'Stopped.'; return; }
            st.textContent = 'Scan failed';
        }).finally(() => {
            prog.done();
            if (_wifidef.abort === ctrl) _wifidef.abort = null;
            if (btn) btn.disabled = false;
        });
}

function wifidefTrust() {
    const st = document.getElementById('wifidef-status');
    // Prefer trusting exactly what the last scan showed (accumulates into the
    // baseline, no separate capture that would see a different set of BSSIDs).
    const aps = (_wifidef.data && _wifidef.data.aps) || [];
    let body, prog = { done: () => {} };
    if (aps.length) {
        st.textContent = `Trusting ${aps.length} shown AP(s)…`;
        body = { aps: aps.map(a => ({ ssid: a.ssid, bssid: a.bssid })) };
    } else {
        const iface = _wifidef.iface || document.getElementById('wifidef-iface').value;
        if (!iface) { st.textContent = 'Run a scan first, then Trust.'; return; }
        prog = _wifidefProgress(st, 20, 'Learning trusted APs');
        body = { interface: iface, seconds: 20 };
    }
    fetch('/api/wifidef/baseline', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body) })
        .then(r => r.json()).then(d => {
            prog.done();
            st.textContent = d.error ? ('⚠ ' + d.error)
                : (`✓ Trusted — baseline now covers ${d.ssids} SSID(s)` + (d.added ? ` (+${d.added} added)` : '') + '. Hit Scan to re-check.');
        }).catch(() => { prog.done(); st.textContent = 'Baseline failed'; });
}

function wifidefSetThreshold() {
    const el = document.getElementById('wifidef-flood-ssids');
    const st = document.getElementById('wifidef-status');
    const v = parseInt(el.value);
    if (!v || v < 10) return;
    fetch('/api/wifidef/thresholds', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ beacon_ssids: v }) })
        .then(r => r.json()).then(t => {
            if (t && t.beacon_ssids) el.value = t.beacon_ssids;
            if (st) st.textContent = `Beacon-flood threshold = ${t.beacon_ssids} SSIDs (applies on next scan)`;
        }).catch(() => {});
}

function wifidefResetBaseline() {
    const st = document.getElementById('wifidef-status');
    if (!confirm('Clear the trusted-AP baseline? Evil-twin detection will have nothing to compare against until you Trust again.')) return;
    fetch('/api/wifidef/baseline', { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'clear' }) })
        .then(r => r.json()).then(() => { st.textContent = 'Baseline cleared'; })
        .catch(() => { st.textContent = 'Clear failed'; });
}

function wifidefAirtime() {
    const iface = (document.getElementById('wifidef-at-iface') || {}).value
        || _wifidef.iface || document.getElementById('wifidef-iface').value;
    if (!iface) return;
    const secs = document.getElementById('wifidef-at-secs').value || 10;
    const chRaw = (document.getElementById('wifidef-at-channel').value || '').trim();
    const ch = /^\d+$/.test(chRaw) ? chRaw : '';
    const st = document.getElementById('wifidef-at-status');
    const btn = document.getElementById('wifidef-at-btn');
    const prog = _wifidefProgress(st, parseInt(secs) || 10,
        'Capturing' + (ch ? ' ch ' + ch : ' (hopping)'));
    if (btn) btn.disabled = true;
    fetch(`/api/wifidef/airtime?interface=${encodeURIComponent(iface)}&seconds=${secs}${ch ? '&channel=' + ch : ''}`)
        .then(r => r.json()).then(d => {
            prog.done();
            if (btn) btn.disabled = false;
            if (d.error) { st.textContent = '⚠ ' + d.error; return; }
            st.textContent = `${d.frames} frames${d.hopping ? ' · hopping (airtime % approx)' : ''}`;
            wifidefRenderAirtime(d);
        }).catch(() => { prog.done(); if (btn) btn.disabled = false; st.textContent = 'Airtime scan failed'; });
}

function wifidefRenderAirtime(d) {
    const fnd = document.getElementById('wifidef-at-findings');
    fnd.innerHTML = (d.findings || []).map(f => {
        const cls = f.type === 'roaming_churn' ? 'bg-amber-600/20 text-amber-300 border-amber-700/50'
            : f.type === 'airtime_hog' ? 'bg-orange-600/20 text-orange-300 border-orange-700/50'
            : f.type === 'slow_client' ? 'bg-red-600/20 text-red-300 border-red-700/50'
            : (f.type === 'erp_protection' || f.type === 'ht_protection_mixed') ? 'bg-fuchsia-600/20 text-fuchsia-300 border-fuchsia-700/50'
            : (f.type === 'weak_security' || f.type.startsWith('cipher_')) ? 'bg-rose-600/20 text-rose-300 border-rose-700/50'
            : f.type.startsWith('wps_') ? 'bg-purple-600/20 text-purple-300 border-purple-700/50'
            : f.type === 'legacy_client' ? 'bg-amber-600/20 text-amber-300 border-amber-700/50'
            : 'bg-red-600/20 text-red-300 border-red-700/50';
        return `<span class="px-2 py-1 rounded border ${cls}">${f.detail}</span>`;
    }).join('') || '<span class="text-green-400 text-xs">✓ No link-quality issues in this capture.</span>';
    const tb = document.getElementById('wifidef-at-tbody');
    const aps = d.aps || [];
    if (!aps.length) { tb.innerHTML = '<tr><td colspan="9" class="py-4 text-center text-gray-500">No frames captured (wrong channel? adapter idle?).</td></tr>'; }
    else tb.innerHTML = aps.map(a => {
        const retryCol = a.retry_pct >= 30 ? 'text-red-400' : a.retry_pct >= 15 ? 'text-amber-400' : 'text-gray-300';
        const airCol = a.airtime_pct >= 50 ? 'text-orange-400' : 'text-gray-300';
        const rate = a.rate_med != null ? `${a.rate_min}/${a.rate_med}/${a.rate_max}` : '—';
        const secCol = (a.security === 'Open' || a.security === 'WEP') ? 'text-red-400'
            : (a.security === 'WPA') ? 'text-amber-400'
            : a.security ? 'text-gray-300' : 'text-gray-600';
        const legacyPhy = a.ap_phy && /802\.11[bg]|802\.11a /.test(a.ap_phy);
        const phyCol = legacyPhy ? 'text-red-300' : a.ap_phy ? 'text-gray-300' : 'text-gray-600';
        // WPS posture badge: red when the PIN surface is exposed, grey otherwise.
        const w = a.wps;
        let wpsBadge = '';
        if (w && w.present) {
            const exposed = w.pin_method && w.locked !== true;
            const label = exposed ? (w.version2 ? 'WPS-PIN' : 'WPS-1.0') : 'WPS';
            const bcls = exposed ? 'bg-purple-600/30 text-purple-200 border-purple-500/60'
                : 'bg-slate-700/40 text-gray-400 border-slate-600/50';
            const tip = exposed ? 'WPS PIN enrollment exposed — brute-forceable' : 'WPS enabled';
            wpsBadge = ` <span class="text-[9px] px-1 rounded border ${bcls}" title="${tip}">${label}</span>`;
        }
        // Cipher suffix on the security cell (TKIP is the throughput-relevant one).
        const cipher = a.group_cipher && a.group_cipher !== 'CCMP-128'
            ? ` <span class="text-[10px] ${a.group_cipher === 'TKIP' ? 'text-rose-400' : 'text-gray-500'}">${a.group_cipher}</span>` : '';
        const htMix = a.ht_protection === 3
            ? ' <span class="text-[9px] px-1 rounded bg-fuchsia-600/20 text-fuchsia-300 border border-fuchsia-700/50" title="HT Protection = Non-HT Mixed: a pre-11n station is associated">MIXED</span>' : '';
        return `<tr class="border-b border-slate-800/50 cursor-pointer hover:bg-slate-800/40" title="Open in Spectrum Analyzer" onclick="wifiPivotFromDefense('${a.bssid}','${encodeURIComponent(a.ssid || '').replace(/'/g, '%27')}')">
            <td class="py-1 pr-2" data-label="SSID">${a.ssid ? _esc(a.ssid) : '<span class="text-gray-600">—</span>'}${a.erp_protection ? ' <span class="text-[9px] px-1 rounded bg-fuchsia-600/20 text-fuchsia-300 border border-fuchsia-700/50" title="ERP protection ON — a legacy 802.11b client is taxing this BSS">ERP</span>' : ''}${wpsBadge}</td>
            <td class="py-1 pr-2 font-mono text-[11px]" data-label="BSSID">${a.bssid}</td>
            <td class="py-1 pr-2 text-xs ${secCol}" data-label="Security">${a.security || '—'}${cipher}</td>
            <td class="py-1 pr-2 text-xs ${phyCol}" data-label="PHY">${a.ap_phy || '—'}${htMix}</td>
            <td class="py-1 pr-2" data-label="Frames">${a.frames} <span class="text-gray-600 text-[10px]">(${a.data_frames} data)</span></td>
            <td class="py-1 pr-2 ${retryCol}" data-label="Retry %">${a.retry_pct}%</td>
            <td class="py-1 pr-2 ${airCol}" data-label="Airtime %">${a.airtime_pct}%</td>
            <td class="py-1 pr-2 text-xs" data-label="Rate min/med/max">${rate} <span class="text-gray-600">Mbps</span></td>
            <td class="py-1 pr-2" data-label="RSSI">${a.rssi == null ? '—' : a.rssi + ' dBm'}</td></tr>`;
    }).join('');
    // Per-client airtime attribution — pinpoints the offending device.
    const cwrap = document.getElementById('wifidef-at-clients-wrap');
    _wifidefClients = d.clients || [];
    if (_wifidefClients.length) {
        cwrap.classList.remove('hidden');
        // Populate the SSID filter with the networks actually seen this capture.
        const sel = document.getElementById('wifidef-at-client-filter');
        const groups = new Map();               // key -> label (ssid, else BSSID)
        _wifidefClients.forEach(c => {
            const key = c.ssid || c.bssid || '';
            if (key && !groups.has(key)) groups.set(key, c.ssid || c.bssid);
        });
        const prev = sel.value;
        sel.innerHTML = '<option value="">All SSIDs</option>' +
            [...groups.entries()].map(([k, label]) =>
                `<option value="${_esc(k)}">${_esc(label)}</option>`).join('');
        sel.value = [...groups.keys()].includes(prev) ? prev : '';
        wifidefFilterClients();
    } else {
        cwrap.classList.add('hidden');
        document.getElementById('wifidef-at-clients-tbody').innerHTML = '';
    }
    const roam = document.getElementById('wifidef-at-roam');
    roam.innerHTML = (d.roaming && d.roaming.length)
        ? '<b class="text-gray-300">Roaming clients:</b> ' + d.roaming.map(r =>
            `<span class="font-mono">${r.client}</span> (${r.reassoc + r.auth}×)`).join(', ')
        : '';
}

// Clients from the last airtime scan, kept so the SSID filter can re-render.
let _wifidefClients = [];

function _wifidefClientRow(c) {
    const airCol = c.airtime_pct >= 20 ? 'text-orange-400' : 'text-gray-300';
    const rate = c.rate_med != null ? `${c.rate_min}/${c.rate_med}/${c.rate_max}` : '—';
    // Confidence: 'declared' (from the client's capability element) is strong;
    // 'observed' (rates only) is a guess and marked with a ~.
    const conf = c.confidence === 'observed' ? '<span class="text-gray-500" title="inferred from rates only — a modern client at the cell edge can look legacy">~</span>' : '';
    const phyCls = c.is_11b ? 'text-red-300' : c.legacy ? 'text-amber-300' : 'text-gray-400';
    const phyTip = c.is_11b ? 'title="802.11b CCK — forces protection overhead on the whole cell"' : '';
    const phy = `<span class="${phyCls}" ${phyTip}>${conf}${c.phy || '—'}</span>`;
    // Disproportion: airtime share ÷ byte share. >1 = eating more airtime than
    // its traffic justifies; this is the number that names the culprit.
    const disp = c.disproportion != null && c.disproportion >= 2
        ? ` <span class="text-orange-400 text-[10px]" title="airtime share ÷ byte share">${c.disproportion}×</span>` : '';
    const name = c.hostname || c.device_label || c.vendor;
    const sub = [c.hostname ? (c.device_label || c.vendor) : c.vendor, c.ip]
        .filter(Boolean).join(' · ');
    const device = name
        ? `<span class="text-gray-200">${_esc(name)}</span>${sub ? ` <span class="text-gray-500 text-[10px]">${_esc(sub)}</span>` : ''}`
        : '<span class="text-gray-600" title="Not in the host inventory — run a network scan on the connected radio to name it">unidentified</span>';
    const ssid = c.ssid ? _esc(c.ssid)
        : (c.bssid ? `<span class="text-gray-600 font-mono text-[10px]" title="AP SSID not seen in this capture">${c.bssid}</span>` : '<span class="text-gray-600">—</span>');
    return `<tr class="border-b border-slate-800/50 ${c.legacy ? 'bg-red-900/10' : ''}">
        <td class="py-1 pr-2 font-mono text-[11px]" data-label="Client">${c.client}</td>
        <td class="py-1 pr-2 text-xs" data-label="Device">${device}</td>
        <td class="py-1 pr-2 text-xs" data-label="SSID">${ssid}</td>
        <td class="py-1 pr-2 text-xs" data-label="PHY">${phy}</td>
        <td class="py-1 pr-2" data-label="Frames">${c.frames}</td>
        <td class="py-1 pr-2 ${airCol}" data-label="Airtime %">${c.airtime_pct}%${disp}</td>
        <td class="py-1 pr-2 text-xs" data-label="Rate min/med/max">${rate} <span class="text-gray-600">Mbps</span></td>
        <td class="py-1 pr-2" data-label="RSSI">${c.rssi == null ? '—' : c.rssi + ' dBm'}</td></tr>`;
}

// Re-render the per-client table filtered to the SSID chosen in the dropdown.
function wifidefFilterClients() {
    const sel = document.getElementById('wifidef-at-client-filter');
    const key = sel ? sel.value : '';
    const rows = _wifidefClients.filter(c => !key || (c.ssid || c.bssid) === key);
    const ctb = document.getElementById('wifidef-at-clients-tbody');
    ctb.innerHTML = rows.length
        ? rows.map(_wifidefClientRow).join('')
        : '<tr><td colspan="8" class="py-3 text-center text-gray-500">No clients on this SSID in the capture.</td></tr>';
}

// ---- Client-isolation observer (passive AP/mesh peer-traffic audit) --------
const _WIFIDEF_ISO_VERDICT = {
    open: ['OPEN — clients reach each other', 'bg-red-600/20 text-red-300 border-red-700/50'],
    broadcast_open: ['PARTIAL — broadcasts forwarded', 'bg-amber-600/20 text-amber-300 border-amber-700/50'],
    isolating: ['ISOLATING — peer traffic blocked', 'bg-green-600/20 text-green-300 border-green-700/50'],
    no_evidence: ['no evidence', 'bg-slate-700/40 text-gray-400 border-slate-600/50'],
};

function wifidefIsolation() {
    const iface = (document.getElementById('wifidef-iso-iface') || {}).value
        || _wifidef.iface || document.getElementById('wifidef-iface').value;
    if (!iface) return;
    const secs = document.getElementById('wifidef-iso-secs').value || 30;
    const chRaw = (document.getElementById('wifidef-iso-channel').value || '').trim();
    const ch = /^\d+$/.test(chRaw) ? chRaw : '';
    const st = document.getElementById('wifidef-iso-status');
    const btn = document.getElementById('wifidef-iso-btn');
    const prog = _wifidefProgress(st, parseInt(secs) || 30,
        'Observing' + (ch ? ' ch ' + ch : ' (hopping — weak evidence)'));
    if (btn) btn.disabled = true;
    fetch(`/api/wifidef/isolation?interface=${encodeURIComponent(iface)}&seconds=${secs}${ch ? '&channel=' + ch : ''}`)
        .then(r => r.json()).then(d => {
            prog.done();
            if (btn) btn.disabled = false;
            if (d.error) { st.textContent = '⚠ ' + d.error; return; }
            st.textContent = `${d.frames} data frames · ${(d.bss || []).length} BSS`
                + (d.hopping ? ' · hopping (dwell on one channel for solid verdicts)' : '');
            wifidefRenderIsolation(d);
        }).catch(() => { prog.done(); if (btn) btn.disabled = false; st.textContent = 'Observation failed'; });
}

function wifidefRenderIsolation(d) {
    const badge = (v) => {
        const [label, cls] = _WIFIDEF_ISO_VERDICT[v] || _WIFIDEF_ISO_VERDICT.no_evidence;
        return `<span class="px-2 py-0.5 rounded border text-[11px] whitespace-nowrap ${cls}">${label}</span>`;
    };
    // Mesh/ESS rollup chips (multi-node SSIDs only)
    const ess = document.getElementById('wifidef-iso-ess');
    ess.innerHTML = (d.ess || []).map(m =>
        `<span class="px-2 py-1 rounded border bg-slate-800/60 border-slate-700 flex items-center gap-2">🕸 <b>${_esc(m.ssid)}</b> <span class="text-gray-500">${m.node_count} nodes · ${m.clients} clients${m.cross_relays ? ` · ${m.cross_relays} cross-node relays` : ''}</span> ${badge(m.verdict)}</span>`
    ).join('') + ((d.wds_frames) ? `<span class="px-2 py-1 rounded border bg-slate-800/60 border-slate-700 text-gray-400">${d.wds_frames} WDS/backhaul frames heard</span>` : '');
    const tb = document.getElementById('wifidef-iso-tbody');
    const bss = d.bss || [];
    if (!bss.length) {
        tb.innerHTML = '<tr><td colspan="7" class="py-4 text-center text-gray-500">No data frames captured — wrong channel, or the air is idle.</td></tr>';
    } else tb.innerHTML = bss.map(b => `<tr class="border-b border-slate-800/50 cursor-pointer hover:bg-slate-800/40" title="Open in Spectrum Analyzer" onclick="wifiPivotFromDefense('${b.bssid}','${encodeURIComponent(b.ssid || '').replace(/'/g, '%27')}')">
            <td class="py-1 pr-2">${b.ssid ? _esc(b.ssid) : '<span class="text-gray-600">—</span>'}</td>
            <td class="py-1 pr-2 font-mono text-[11px]">${b.bssid}</td>
            <td class="py-1 pr-2">${b.clients}</td>
            <td class="py-1 pr-2 ${b.attempts ? 'text-gray-200' : 'text-gray-600'}">${b.attempts}</td>
            <td class="py-1 pr-2 ${b.relays ? 'text-red-400 font-semibold' : 'text-gray-600'}">${b.relays}</td>
            <td class="py-1 pr-2 text-gray-400">${b.bcast_sent}/${b.bcast_relays}</td>
            <td class="py-1 pr-2">${badge(b.verdict)}</td></tr>`).join('');
    // Talking pairs = the concrete isolation-off evidence.
    const pr = document.getElementById('wifidef-iso-pairs');
    const pairs = bss.flatMap(b => (b.pairs || []).map(p =>
        `<span class="font-mono">${p[0]} ⇄ ${p[1]}</span> ×${p[2]}`));
    pr.innerHTML = pairs.length
        ? '<b class="text-gray-300">Clients seen talking through the AP:</b> ' + pairs.join(' · ')
        : '';
}

// A BSSID that pivots to the Spectrum Analyzer (Network → WiFi Analyzer),
// where it's selected + highlighted in the spectrum. ssid may be undefined.
function _wifidefMacLink(mac, ssid) {
    if (!mac) return '';
    const s = encodeURIComponent(ssid || '').replace(/'/g, '%27');
    return `<a href="javascript:void(0)" onclick="event.stopPropagation();wifiPivotFromDefense('${mac}','${s}')"`
        + ` class="underline decoration-dotted hover:text-white" title="Open in Spectrum Analyzer">${mac}</a>`;
}

function wifidefRender() {
    const d = _wifidef.data; if (!d) return;
    const [label, cls] = _WIFIDEF_THREAT[d.threat] || ['—', 'bg-slate-700 text-slate-300'];
    const tb = document.getElementById('wifidef-threat');
    tb.textContent = label; tb.className = 'shrink-0 px-4 py-2 rounded-lg text-sm font-bold ' + cls;
    // Detection cards
    const det = document.getElementById('wifidef-detections');
    if (!d.detections.length) {
        det.innerHTML = '<div class="glass rounded-xl p-4 text-sm text-green-300 md:col-span-2">✓ No wireless attacks detected in this capture.</div>';
    } else {
        det.innerHTML = d.detections.map(x => {
            const crit = ['flood', 'evil_twin', 'karma'].includes(x.severity);
            const border = crit ? 'border-l-4 border-red-500' : 'border-l-4 border-amber-500';
            let title = '', body = '';
            if (x.type === 'deauth') {
                title = x.severity === 'flood' ? '💥 Deauth/Disassoc FLOOD' : 'Deauth/Disassoc frames seen';
                const scopeTag = x.scope ? ` <span class="text-gray-500">(${x.scope}${x.unprotected === x.count && x.count ? ', unprotected' : ''})</span>` : '';
                body = `<div>${x.count} frames.${scopeTag}</div>` + (x.attackers || []).map(a =>
                    `<div class="font-mono text-[11px] text-gray-400">${_wifidefMacLink(a.src)} → ${a.dst} ×${a.count}</div>`).join('');
            } else if (x.type === 'beacon_flood') {
                title = x.severity === 'flood' ? '📡 Beacon flood (fake APs)' : '📡 Dense airspace (beacon)';
                const laTag = (x.la_ratio != null) ? ` · <span class="${x.la_ratio >= 0.5 ? 'text-red-300' : 'text-gray-500'}">${Math.round(x.la_ratio * 100)}% randomized MACs</span>` : '';
                body = `<div>${x.ssids} SSIDs from ${x.bssids} BSSIDs${laTag}.</div>`;
            } else if (x.type === 'karma') {
                title = '🎣 KARMA / MANA rogue AP';
                body = `<div class="font-mono text-[11px] text-gray-400">${_wifidefMacLink(x.bssid)}</div><div>answered ${x.ssid_count} SSIDs: ${(x.ssids || []).join(', ')}</div>`;
            } else if (x.type === 'rogue_ap') {
                title = x.severity === 'evil_twin' ? '👿 Evil twin (untrusted BSSID)' : '⚠ Duplicate SSID';
                body = `<div>SSID <b>${x.ssid}</b></div><div class="font-mono text-[11px] text-gray-400">${(x.rogue_bssids || x.bssids || []).map(b => _wifidefMacLink(b, x.ssid)).join(', ')}</div>`;
            }
            return `<div class="glass rounded-xl p-4 ${border}"><div class="font-semibold text-sm mb-1">${title}</div><div class="text-sm text-gray-300">${body}</div><div class="text-[11px] text-gray-500 mt-1">${x.detail || ''}${body.indexOf('wifiPivotFromDefense') >= 0 ? ' <span class="text-gray-600">· click a MAC to inspect it in the Spectrum Analyzer</span>' : ''}</div></div>`;
        }).join('');
    }
    // Counts
    const c = d.counts || {};
    let chips = [['frames', d.frames], ['deauth', c.deauth], ['beacons', c.beacon], ['probe-req', c.probe_req], ['probe-resp', c.probe_resp]]
        .map(([k, v]) => `<span class="px-3 py-1 rounded bg-slate-800 border border-slate-700"><b>${v || 0}</b> <span class="text-gray-400">${k}</span></span>`).join('');
    // Airspace density vs the flood threshold — lets the user calibrate.
    const a = d.airspace;
    if (a) {
        const near = a.ssids >= a.beacon_ssid_threshold;
        chips += `<span class="px-3 py-1 rounded bg-slate-800 border ${near ? 'border-red-600/60 text-red-300' : 'border-slate-700'}" title="Distinct SSIDs / BSSIDs heard this capture, vs the beacon-flood threshold. Raise the threshold above your normal density.">`
            + `<b>${a.ssids}</b> SSIDs · <b>${a.bssids}</b> BSSIDs <span class="text-gray-500">(flood ≥ ${a.beacon_ssid_threshold})</span></span>`;
    }
    document.getElementById('wifidef-counts').innerHTML = chips;
    // AP table
    document.getElementById('wifidef-ap-count').textContent = `(${(d.aps || []).length})`;
    const body = document.getElementById('wifidef-ap-tbody');
    const trusted = null;
    if (!d.aps || !d.aps.length) body.innerHTML = '<tr><td colspan="5" class="py-4 text-center text-gray-500">No beacons captured (wrong channel? try “hop”).</td></tr>';
    else body.innerHTML = d.aps.map(a => `<tr class="border-b border-slate-800/50 cursor-pointer hover:bg-slate-800/40" title="Open in Spectrum Analyzer" onclick="wifiPivotFromDefense('${a.bssid}','${encodeURIComponent(a.ssid || '').replace(/'/g, '%27')}')">
        <td class="py-1 pr-2">${a.ssid || '<span class=\'text-gray-500 italic\'>hidden</span>'}</td>
        <td class="py-1 pr-2 font-mono text-[11px]">${a.bssid}</td>
        <td class="py-1 pr-2">${a.channel == null ? '—' : a.channel}</td>
        <td class="py-1 pr-2">${a.rssi == null ? '—' : a.rssi + ' dBm'}</td>
        <td class="py-1 pr-2">${a.beacons}</td></tr>`).join('');
}

// ============================================================================
// Network diagnostics (Diagnostics / Switch & L2 / Interfaces sub-tabs)
// Backend: /api/net/* (see network_diagnostics.py)
// ============================================================================

// Last-fetched payloads for each net panel, so "Export CSV" has data to dump.
let _ndLastLldp = [], _ndLastArp = null, _ndLastIfaces = [],
    _ndLastMtr = null, _ndLastIdentity = null, _ndLastIsp = [],
    _ndLastMacWatch = null;

// Build a CSV from a header row + rows (arrays of cells) and download it.
function _ndDownloadCsv(nameBase, header, rows) {
    if (!rows || !rows.length) {
        addConsoleMessage('Nothing to export yet — run it first', 'warning');
        return;
    }
    const q = (c) => `"${String(c == null ? '' : c).replace(/"/g, '""')}"`;
    const csv = [header].concat(rows).map(r => r.map(q).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ragnar_${nameBase}_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
}

function exportLldpCsv() {
    _ndDownloadCsv('switch_neighbors',
        ['Local IF', 'Protocol', 'Switch', 'Switch descr', 'Port', 'VLAN ID', 'VLAN name', 'PoE', 'Mgmt IP'],
        (_ndLastLldp || []).map(n => [n.local_interface, n.protocol, n.switch_name,
            n.switch_descr, (n.port_descr || n.port_id), n.vlan_id, n.vlan_name, _poeText(n.poe), n.mgmt_ip]));
}

function exportArpCsv() {
    const d = _ndLastArp;
    _ndDownloadCsv('arp_scan' + (d && d.interface ? '_' + d.interface : ''),
        ['IP', 'MAC', 'Vendor'],
        (d && d.hosts || []).map(h => [h.ip, h.mac, h.vendor]));
}

function exportInterfacesCsv() {
    _ndDownloadCsv('interfaces',
        ['Name', 'Type', 'Operstate', 'Link detected', 'Speed', 'Duplex', 'Auto-neg',
         'IP method', 'IPv4', 'IPv6', 'MAC', 'VLAN ID', 'VLAN proto'],
        (_ndLastIfaces || []).map(i => [i.name, i.type, i.operstate, i.link_detected,
            i.speed, i.duplex, i.autoneg, i.ip_method, (i.ipv4 || []).join(' '),
            (i.ipv6 || []).join(' '), i.mac, i.vlan_id, i.vlan_proto]));
}

function exportMtrCsv() {
    const d = _ndLastMtr;
    if (!d) { addConsoleMessage('Run MTR first', 'warning'); return; }
    const base = 'mtr_' + String(d.target || 'target').replace(/[^a-z0-9._-]/gi, '_');
    _ndDownloadCsv(base,
        ['Hop', 'Host', 'Loss %', 'Sent', 'Last', 'Avg', 'Best', 'Worst', 'Jitter (StDev)'],
        (d.hops || []).map(h => [h.hop, h.host, h.loss_pct, h.sent, h.last, h.avg, h.best, h.worst, h.stdev]));
}

function exportIdentityCsv() {
    const d = _ndLastIdentity;
    if (!d) { addConsoleMessage('Load Network Identity first', 'warning'); return; }
    const domain = (d.domains && d.domains.length) ? d.domains.join(' ')
        : (d.guessed_domain ? d.guessed_domain + ' (guessed)' : '');
    _ndDownloadCsv('network_identity', ['Field', 'Value'], [
        ['Domain / search', domain],
        ['Hostname', d.hostname],
        ['FQDN', d.fqdn],
        ['Nameservers', (d.nameservers || []).join(' ')],
        ['DNS via stub', d.dns_stub],
        ['Gateway IP', d.gateway ? d.gateway.ip : ''],
        ['Gateway PTR', d.gateway ? d.gateway.ptr : ''],
        ['Sources', (d.sources || []).join(' ')],
    ]);
}

function _ndBusy(btn, busy, busyLabel) {
    if (!btn) return;
    if (busy) {
        btn.dataset._orig = btn.innerHTML;
        btn.disabled = true;
        btn.classList.add('opacity-60');
        btn.innerHTML = '<span class="inline-block animate-spin">⟳</span> ' + (busyLabel || 'Running…');
    } else {
        btn.disabled = false;
        btn.classList.remove('opacity-60');
        if (btn.dataset._orig) btn.innerHTML = btn.dataset._orig;
    }
}

async function _ndRunText(inputId, resultId, endpoint, verb, rerunFnName) {
    const input = document.getElementById(inputId);
    const out = document.getElementById(resultId);
    const target = (input.value || '').trim();
    if (!target) { input.focus(); return; }
    const btn = event && event.target ? event.target : null;
    _ndBusy(btn, true, verb);
    out.classList.remove('hidden');
    out.textContent = verb + ' ' + target + '…';
    try {
        const data = await postAPI(endpoint, { target });
        if (data.success) {
            out.textContent = data.output || '(no output)';
        } else if (data.missing_tool && rerunFnName) {
            out.innerHTML = _ndMissingTool(data, rerunFnName);
        } else {
            out.textContent = 'Error: ' + (data.error || 'failed');
        }
    } catch (e) {
        out.textContent = 'Failed: ' + e.message;
    } finally {
        _ndBusy(btn, false);
    }
}

