// ---------------------------------------------------------------------------
// Host-investigation enrichment: beacons, JA3 fingerprints, IRC sessions,
// and alerts filtered to the host. Each helper returns an HTML string and
// renders nothing when there's no data for the host.
// ---------------------------------------------------------------------------

async function fetchHostInvestigationData(ip) {
    const tryFetch = async (url) => {
        try {
            const r = await fetch(url);
            if (!r.ok) return null;
            return await r.json();
        } catch { return null; }
    };
    const [bRes, jRes, iRes, aRes] = await Promise.all([
        tryFetch('/api/traffic/beacons?limit=200'),
        tryFetch('/api/traffic/ja3?limit=200'),
        tryFetch('/api/traffic/irc?limit=200'),
        tryFetch('/api/traffic/alerts?limit=200'),
    ]);
    const beacons = (bRes && bRes.success ? bRes.beacons || [] : [])
        .filter(b => b.src_ip === ip || b.dst_ip === ip);
    const ja3 = (jRes && jRes.success ? jRes.fingerprints || [] : [])
        .filter(r => r.src_ip === ip);
    const irc = (iRes && iRes.success ? iRes.sessions || [] : [])
        .filter(s => s.client_ip === ip || s.server_ip === ip);
    const alerts = (aRes && aRes.success ? aRes.alerts || [] : [])
        .filter(a => a.src_ip === ip || a.dst_ip === ip);
    return [beacons, ja3, irc, alerts];
}

function renderHostBeaconSection(beacons, ip) {
    if (!beacons || beacons.length === 0) return '';
    const rows = beacons.slice(0, 10).map(b => {
        const scorePct = Math.round((b.score || 0) * 100);
        const scoreColor = scorePct >= 85 ? 'text-red-400'
            : scorePct >= 70 ? 'text-orange-400' : 'text-yellow-400';
        const peer = b.src_ip === ip ? b.dst_ip : b.src_ip;
        return `
            <div class="p-2 bg-slate-700 bg-opacity-50 rounded text-xs">
                <div class="flex items-center justify-between mb-1">
                    <span class="font-mono">→ ${escapeHtml(peer)}:${b.dst_port}</span>
                    <span class="${scoreColor} font-bold">score ${scorePct}/100</span>
                </div>
                <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-gray-400">
                    <div>Interval <span class="text-gray-200">~${b.mean_interval_s}s</span></div>
                    <div>Jitter (CV) <span class="text-gray-200">${b.interval_cv}</span></div>
                    <div>Avg size <span class="text-gray-200">${b.mean_size_bytes} B</span></div>
                    <div>Samples <span class="text-gray-200">${b.samples}</span></div>
                </div>
            </div>`;
    }).join('');
    return `
        <div class="p-4 bg-red-900 bg-opacity-20 border border-red-700 rounded-lg">
            <h4 class="text-sm font-semibold text-red-300 mb-3 flex items-center gap-2">
                <span>🛰</span> C2 Beacon Candidates (${beacons.length})
                <span class="text-xs font-normal text-gray-400">MITRE T1071 / T1573</span>
            </h4>
            <div class="space-y-2">${rows}</div>
        </div>`;
}

function renderHostJA3Section(records, ip) {
    if (!records || records.length === 0) return '';
    const rows = records.slice(0, 10).map(r => {
        const m = r.match;
        const labelBlock = m
            ? `<span class="px-2 py-0.5 rounded ${m.category === 'malware' ? 'bg-red-900 text-red-300' : m.category === 'iot' ? 'bg-yellow-900 text-yellow-300' : 'bg-cyan-900 text-cyan-300'}">${escapeHtml(m.label)} (${escapeHtml(m.confidence)})</span>`
            : '<span class="text-gray-500">unclassified</span>';
        const sni = r.sni ? `<span class="text-cyan-300">${escapeHtml(r.sni)}</span>` : '<span class="text-gray-500">no SNI</span>';
        return `
            <div class="p-2 bg-slate-700 bg-opacity-50 rounded text-xs">
                <div class="flex items-center justify-between mb-1">
                    <span class="font-mono text-gray-300">${escapeHtml(r.ja3.slice(0, 16))}…</span>
                    ${labelBlock}
                </div>
                <div class="text-gray-400 flex flex-wrap gap-x-3">
                    <span>SNI: ${sni}</span>
                    <span>Hits: <span class="text-gray-200">${r.count}</span></span>
                    ${m && m.source ? `<span>Source: <span class="text-gray-200">${escapeHtml(m.source)}</span></span>` : ''}
                </div>
            </div>`;
    }).join('');
    return `
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3 flex items-center gap-2">
                <span>🔐</span> TLS Fingerprints (JA3) — ${records.length}
            </h4>
            <div class="space-y-2">${rows}</div>
        </div>`;
}

function renderHostIRCSection(sessions, ip) {
    if (!sessions || sessions.length === 0) return '';
    const rows = sessions.slice(0, 5).map(s => {
        const channels = (s.channels && s.channels.length)
            ? s.channels.map(c => `<span class="inline-block px-1.5 py-0.5 mr-1 rounded bg-slate-700 text-cyan-300">${escapeHtml(c)}</span>`).join('')
            : '<span class="text-gray-500">no channels</span>';
        const banner = (s.server_banner && s.server_banner.length)
            ? `<div class="mt-1 text-gray-400 italic">"${escapeHtml(s.server_banner[0]).slice(0, 200)}"</div>`
            : '';
        const recent = (s.recent_messages || []).slice(-5).map(m => `
            <div class="font-mono text-xs ${m.direction === 'c2s' ? 'text-cyan-300' : 'text-green-300'}">
                ${m.direction === 'c2s' ? '→' : '←'} ${escapeHtml(m.command)} ${escapeHtml((m.params || []).join(' '))}
            </div>`).join('');
        return `
            <div class="p-2 bg-slate-700 bg-opacity-50 rounded text-xs">
                <div class="flex items-center justify-between mb-1">
                    <span class="font-mono">${escapeHtml(s.client_ip)} → ${escapeHtml(s.server_ip)}:${s.server_port}</span>
                    <span class="text-gray-400">nick <span class="text-yellow-300">${escapeHtml(s.nick || '?')}</span></span>
                </div>
                <div class="text-gray-400 mb-1">Channels: ${channels}</div>
                ${banner}
                ${recent ? `<div class="mt-2 p-2 bg-slate-900 rounded space-y-0.5">${recent}</div>` : ''}
            </div>`;
    }).join('');
    return `
        <div class="p-4 bg-orange-900 bg-opacity-20 border border-orange-700 rounded-lg">
            <h4 class="text-sm font-semibold text-orange-300 mb-3 flex items-center gap-2">
                <span>💬</span> IRC Sessions (DPI) — ${sessions.length}
                <span class="text-xs font-normal text-gray-400">MITRE T1071.001</span>
            </h4>
            <div class="space-y-2">${rows}</div>
        </div>`;
}

function renderHostAlertSection(alerts, ip) {
    if (!alerts || alerts.length === 0) return '';
    const recent = alerts.slice(-10).reverse();
    const rows = recent.map(a => {
        const borderColor = {
            critical: 'border-red-600',
            high: 'border-orange-600',
            medium: 'border-yellow-600',
            low: 'border-blue-600',
            info: 'border-slate-600',
        }[a.level] || 'border-slate-600';
        const badgeColor = {
            critical: 'bg-red-900 text-red-300',
            high: 'bg-orange-900 text-orange-300',
            medium: 'bg-yellow-900 text-yellow-300',
            low: 'bg-blue-900 text-blue-300',
            info: 'bg-slate-700 text-gray-300',
        }[a.level] || 'bg-slate-700 text-gray-300';
        const ts = a.timestamp ? new Date(a.timestamp).toLocaleTimeString() : '';
        return `
            <div class="p-2 bg-slate-700 bg-opacity-50 rounded border-l-4 ${borderColor} text-xs">
                <div class="flex items-center justify-between mb-1">
                    <span class="px-1.5 py-0.5 rounded text-[10px] font-semibold uppercase ${badgeColor}">${escapeHtml(a.level)}</span>
                    <span class="text-gray-500">${ts}</span>
                </div>
                <div class="text-gray-200">${escapeHtml(a.message || '')}</div>
                ${a.details ? formatAlertDetails(a.details) : ''}
            </div>`;
    }).join('');
    return `
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3 flex items-center gap-2">
                <span>⚠</span> Alerts involving this host (${alerts.length})
            </h4>
            <div class="space-y-2">${rows}</div>
        </div>`;
}

/**
 * Show traffic connection detail modal
 */
function showTrafficConnectionDetail(connDataStr) {
    const modal = document.getElementById('traffic-connection-modal');
    const content = document.getElementById('traffic-connection-modal-content');

    if (!modal || !content) return;

    let conn;
    try {
        conn = typeof connDataStr === 'string' ? JSON.parse(connDataStr) : connDataStr;
    } catch (e) {
        console.error('Error parsing connection data:', e);
        return;
    }

    const duration = conn.duration_seconds ? formatDuration(conn.duration_seconds) : 'N/A';
    const firstSeen = conn.first_seen ? new Date(conn.first_seen).toLocaleString() : 'N/A';
    const lastSeen = conn.last_seen ? new Date(conn.last_seen).toLocaleString() : 'N/A';

    content.innerHTML = `
        <!-- Connection Header -->
        <div class="p-4 bg-slate-800 rounded-lg">
            <div class="flex items-center justify-center gap-3 text-lg font-mono mb-4">
                <span class="text-cyan-400">${escapeHtml(conn.src_ip)}:${conn.src_port}</span>
                <span class="text-gray-500">→</span>
                <span class="text-green-400">${escapeHtml(conn.dst_ip)}:${conn.dst_port}</span>
            </div>
            <div class="flex justify-center">
                <span class="px-3 py-1 bg-blue-900 text-blue-300 rounded-full text-sm font-semibold">
                    ${escapeHtml(conn.protocol?.toUpperCase() || 'UNKNOWN')}
                </span>
            </div>
        </div>

        <!-- Statistics -->
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3">Statistics</h4>
            <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 text-center text-sm">
                <div class="bg-slate-700 rounded p-2">
                    <div class="text-cyan-400 font-bold">${formatBytes(conn.bytes_sent || 0)}</div>
                    <div class="text-xs text-gray-500">Bytes Sent</div>
                </div>
                <div class="bg-slate-700 rounded p-2">
                    <div class="text-green-400 font-bold">${formatBytes(conn.bytes_recv || 0)}</div>
                    <div class="text-xs text-gray-500">Bytes Received</div>
                </div>
                <div class="bg-slate-700 rounded p-2">
                    <div class="text-blue-400 font-bold">${conn.packets_sent || 0}</div>
                    <div class="text-xs text-gray-500">Packets Sent</div>
                </div>
                <div class="bg-slate-700 rounded p-2">
                    <div class="text-purple-400 font-bold">${conn.packets_recv || 0}</div>
                    <div class="text-xs text-gray-500">Packets Received</div>
                </div>
            </div>
        </div>

        <!-- Duration -->
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3">Duration</h4>
            <div class="text-center">
                <div class="text-2xl font-bold text-yellow-400">${duration}</div>
                <div class="text-xs text-gray-500 mt-1">Connection duration</div>
            </div>
        </div>

        <!-- Flags -->
        ${conn.flags && conn.flags.length > 0 ? `
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3">TCP Flags</h4>
            <div class="flex flex-wrap gap-2">
                ${conn.flags.map(flag => `
                    <span class="px-2 py-1 bg-orange-900 text-orange-300 rounded text-xs font-mono">${escapeHtml(flag)}</span>
                `).join('')}
            </div>
        </div>
        ` : ''}

        <!-- Timeline -->
        <div class="p-4 bg-slate-800 rounded-lg">
            <h4 class="text-sm font-semibold text-gray-300 mb-3">Timeline</h4>
            <div class="grid grid-cols-2 gap-4 text-sm">
                <div>
                    <div class="text-gray-500">First Seen</div>
                    <div class="text-white">${firstSeen}</div>
                </div>
                <div>
                    <div class="text-gray-500">Last Seen</div>
                    <div class="text-white">${lastSeen}</div>
                </div>
            </div>
        </div>

        <!-- Quick Actions -->
        <div class="flex gap-2">
            <button onclick="showTrafficHostDetail('${escapeHtml(conn.src_ip)}')"
                    class="flex-1 px-3 py-2 bg-cyan-600 hover:bg-cyan-700 text-white rounded-lg text-sm transition-colors">
                View Source Host
            </button>
            <button onclick="showTrafficHostDetail('${escapeHtml(conn.dst_ip)}')"
                    class="flex-1 px-3 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm transition-colors">
                View Dest Host
            </button>
        </div>
    `;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
}

/**
 * Close traffic connection detail modal
 */
function closeTrafficConnectionModal() {
    const modal = document.getElementById('traffic-connection-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
}

/**
 * Show traffic port detail modal
 */
async function showTrafficPortDetail(port, portHosts) {
    const modal = document.getElementById('traffic-port-modal');
    const portTitle = document.getElementById('traffic-port-modal-port');
    const serviceTitle = document.getElementById('traffic-port-modal-service');
    const content = document.getElementById('traffic-port-modal-content');

    if (!modal || !content) return;

    const portNum = parseInt(port);
    portTitle.textContent = port;

    // Get service name
    const commonPorts = {
        20: 'FTP Data', 21: 'FTP', 22: 'SSH', 23: 'Telnet', 25: 'SMTP',
        53: 'DNS', 67: 'DHCP Server', 68: 'DHCP Client', 69: 'TFTP',
        80: 'HTTP', 110: 'POP3', 119: 'NNTP', 123: 'NTP', 135: 'MS-RPC',
        137: 'NetBIOS-NS', 138: 'NetBIOS-DGM', 139: 'NetBIOS-SSN',
        143: 'IMAP', 161: 'SNMP', 162: 'SNMP Trap', 389: 'LDAP',
        443: 'HTTPS', 445: 'SMB', 465: 'SMTPS', 514: 'Syslog',
        587: 'SMTP Submission', 636: 'LDAPS', 993: 'IMAPS', 995: 'POP3S',
        1080: 'SOCKS', 1433: 'MSSQL', 1521: 'Oracle', 3306: 'MySQL',
        3389: 'RDP', 5432: 'PostgreSQL', 5900: 'VNC', 6379: 'Redis',
        8080: 'HTTP Proxy', 8443: 'HTTPS Alt', 27017: 'MongoDB'
    };

    const suspiciousInfo = SUSPICIOUS_PORT_INFO[portNum];
    const serviceName = suspiciousInfo ? suspiciousInfo.name : (commonPorts[portNum] || 'Unknown Service');
    serviceTitle.textContent = serviceName;

    content.innerHTML = '<div class="text-center py-8"><div class="animate-spin w-8 h-8 border-2 border-cyan-400 border-t-transparent rounded-full mx-auto"></div><p class="text-gray-400 mt-2">Loading port details...</p></div>';

    modal.classList.remove('hidden');
    modal.classList.add('flex');

    try {
        // Fetch hosts data to get more info about connections on this port
        const response = await fetch('/api/traffic/hosts?limit=100&sort=bytes');
        const data = await response.json();

        if (!data.success || !data.hosts) {
            content.innerHTML = '<p class="text-red-400 text-center py-8">Failed to load port details</p>';
            return;
        }

        // Find hosts using this port
        const hostsUsingPort = data.hosts.filter(h => h.ports_contacted && h.ports_contacted.includes(portNum));

        let html = '';

        // Security warning if suspicious
        if (suspiciousInfo) {
            const severityColors = {
                critical: 'bg-red-900 border-red-500 text-red-300',
                high: 'bg-orange-900 border-orange-500 text-orange-300',
                medium: 'bg-yellow-900 border-yellow-500 text-yellow-300',
                low: 'bg-blue-900 border-blue-500 text-blue-300'
            };
            html += `
                <div class="p-3 ${severityColors[suspiciousInfo.severity]} border-l-4 rounded">
                    <div class="flex items-center space-x-2 mb-1">
                        <span class="text-lg">⚠️</span>
                        <span class="font-semibold uppercase text-xs">${suspiciousInfo.severity} Severity</span>
                        <span class="text-xs px-2 py-0.5 bg-black bg-opacity-30 rounded">${escapeHtml(suspiciousInfo.category)}</span>
                    </div>
                    <p class="text-sm">${escapeHtml(suspiciousInfo.reason)}</p>
                </div>
            `;
        }

        // Port statistics
        html += `
            <div class="grid grid-cols-2 gap-3">
                <div class="bg-slate-800 bg-opacity-50 p-3 rounded">
                    <div class="text-xs text-gray-400 uppercase">Total Hosts</div>
                    <div class="text-2xl font-bold text-cyan-400">${hostsUsingPort.length}</div>
                </div>
                <div class="bg-slate-800 bg-opacity-50 p-3 rounded">
                    <div class="text-xs text-gray-400 uppercase">Service</div>
                    <div class="text-lg font-semibold text-white">${escapeHtml(serviceName)}</div>
                </div>
            </div>
        `;

        // Hosts using this port
        if (hostsUsingPort.length > 0) {
            html += `
                <div>
                    <h4 class="text-sm font-semibold text-gray-300 mb-2">Hosts Using This Port</h4>
                    <div class="space-y-1 max-h-60 overflow-y-auto">
                        ${hostsUsingPort.map(host => {
                            const totalBytes = host.total_bytes || 0;
                            return `
                                <div class="flex items-center justify-between p-2 bg-slate-700 bg-opacity-30 rounded hover:bg-slate-600 hover:bg-opacity-50 transition-colors cursor-pointer" onclick="closeTrafficPortModal(); showTrafficHostDetail('${escapeHtml(host.ip)}')">
                                    <div class="flex items-center space-x-2">
                                        <span class="font-mono text-cyan-400">${escapeHtml(host.ip)}</span>
                                        ${host.hostname ? `<span class="text-gray-500 text-xs">(${escapeHtml(host.hostname)})</span>` : ''}
                                    </div>
                                    <div class="text-xs text-gray-400">
                                        ${formatBytes(totalBytes)}
                                    </div>
                                </div>
                            `;
                        }).join('')}
                    </div>
                </div>
            `;
        } else {
            html += '<p class="text-gray-400 text-center py-4">No active hosts on this port</p>';
        }

        content.innerHTML = html;

    } catch (error) {
        console.error('Error loading port details:', error);
        content.innerHTML = '<p class="text-red-400 text-center py-8">Error loading port details</p>';
    }
}

/**
 * Close traffic port detail modal
 */
function closeTrafficPortModal() {
    const modal = document.getElementById('traffic-port-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
}

// ============================================================================
// WARDRIVING FUNCTIONS
// ============================================================================

let _wardrivingInterval = null;

async function loadWardrivingData() {
    try {
        const [statusRes, sessionsRes] = await Promise.all([
            fetch('/api/wardriving/status'),
            fetch('/api/wardriving/sessions')
        ]);
        const status = await statusRes.json();
        const sessionsData = await sessionsRes.json();

        updateWardrivingUI(status);
        renderWardrivingSessions(sessionsData.sessions || []);
        loadWardrivingOnBootState();
        loadHuginnConfig();

        if (status.running) {
            if (!_wardrivingInterval) {
                _wardrivingInterval = setInterval(refreshWardrivingStatus, 3000);
            }
            await loadWardrivingTableByType();
        } else {
            if (_wardrivingInterval) {
                clearInterval(_wardrivingInterval);
                _wardrivingInterval = null;
            }
            // Still load networks to show previous session data
            await loadWardrivingTableByType();
        }
    } catch (e) {
        console.error('[Wardriving] Load error:', e);
    }
}

async function refreshWardrivingStatus() {
    try {
        const res = await fetch('/api/wardriving/status');
        const status = await res.json();
        updateWardrivingUI(status);
        if (status.running) {
            loadWardrivingTableByType();
        } else if (_wardrivingInterval) {
            clearInterval(_wardrivingInterval);
            _wardrivingInterval = null;
        }
    } catch (e) {
        console.error('[Wardriving] Refresh error:', e);
    }
}

function updateWardrivingUI(status) {
    const badge = document.getElementById('wd-status-badge');

    // Sync running state and toggle button
    _wardrivingRunning = !!status.running;
    updateWardrivingToggleButton();

    // Map "Backfill GPS" button is only shown when enabled in config
    applyWardrivingBackfillVisibility(!!status.allow_backfill);

    if (status.running) {
        if (badge) { badge.textContent = 'Running'; badge.className = 'px-2 py-1 bg-emerald-600 bg-opacity-30 text-emerald-400 text-xs rounded-full animate-pulse'; }
    } else {
        if (badge) { badge.textContent = 'Stopped'; badge.className = 'px-2 py-1 bg-gray-600 bg-opacity-30 text-gray-400 text-xs rounded-full'; }
    }

    // GPS
    const gps = status.gps || {};
    const gpsStatus = document.getElementById('wd-gps-status');
    const gpsCoords = document.getElementById('wd-gps-coords');
    const gpsSats = document.getElementById('wd-gps-sats');
    const satsInView = gps.satellites_in_view || 0;
    const satsUsed = gps.satellites || 0;
    if (gpsStatus) {
        if (gps.has_fix) {
            gpsStatus.textContent = 'GPS-Fix OK';
            gpsStatus.className = 'text-sm font-bold text-emerald-400';
        } else if (gps.connected && status.running) {
            gpsStatus.textContent = satsInView > 0 ? `Searching (${satsInView} visible)` : 'Searching...';
            gpsStatus.className = 'text-sm font-bold text-yellow-400';
        } else if (gps.connected) {
            gpsStatus.textContent = 'Connected';
            gpsStatus.className = 'text-sm font-bold text-cyan-400';
        } else {
            gpsStatus.textContent = 'No GPS';
            gpsStatus.className = 'text-sm font-bold text-red-400';
        }
    }
    if (gpsCoords) {
        gpsCoords.textContent = (gps.latitude && gps.longitude) ? `${gps.latitude.toFixed(5)}, ${gps.longitude.toFixed(5)}` : '-';
    }
    if (gpsSats) {
        const parts = [`Sats: ${satsUsed}/${satsInView}`];
        if (gps.snr_max != null) parts.push(`SNR ${gps.snr_max} dB`);
        if (gps.hdop != null && gps.hdop < 50) parts.push(`HDOP ${gps.hdop.toFixed(1)}`);
        gpsSats.textContent = parts.join(' · ');
    }

    // Speed & direction
    const speedEl = document.getElementById('wd-speed-val');
    const headEl = document.getElementById('wd-heading-val');
    if (speedEl) {
        speedEl.textContent = (gps.speed_kmh != null && gps.has_fix) ? formatWardrivingSpeed(gps.speed_kmh) : '—';
    }
    if (headEl) {
        if (gps.course != null && gps.has_fix) {
            const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
            const idx = Math.round(gps.course / 45) % 8;
            headEl.textContent = `${dirs[idx]} (${Math.round(gps.course)}°)`;
        } else {
            headEl.textContent = '—';
        }
    }

    // Device name
    const dnEl = document.getElementById('wd-device-name');
    if (dnEl && !dnEl.matches(':focus') && status.device_name) {
        dnEl.value = status.device_name;
    }

    // Stats
    const stats = status.stats || {};
    updateElement('wd-total-networks', String(stats.total_networks || 0));
    updateElement('wd-networks-per-scan', `${status.networks_this_scan || 0} per scan`);
    updateElement('wd-open-count', String(stats.open_networks || 0));
    updateElement('wd-wep-count', String(stats.wep_networks || 0));
    updateElement('wd-wpa-count', String(stats.wpa_networks || 0));
    updateElement('wd-band24', String(stats.band_2_4ghz || 0));
    updateElement('wd-band5', String(stats.band_5ghz || 0));
    updateElement('wd-band6', String(stats.band_6ghz || 0));
    updateElement('wd-scans-done', `Scans: ${status.scans_completed || 0}`);

    // BT, Cell, Camera counts
    updateElement('wd-bt-count', String(stats.bluetooth_devices || status.bluetooth_count || 0));
    updateElement('wd-cell-count', String(stats.cell_towers || status.cell_count || 0));
    updateElement('wd-camera-count', String(stats.cameras || 0));
    // Zigbee / 802.15.4 — unique devices in the DB, falling back to the live
    // session count from companions before the first DB stats roll-up.
    updateElement('wd-zigbee-count', String(stats.zigbee_devices || status.zigbee_count || 0));

    // Interfaces
    const ifInfo = document.getElementById('wd-interfaces-info');
    if (status.interfaces && status.interfaces.length > 0) {
        if (ifInfo) ifInfo.textContent = `Interfaces: ${status.interfaces.join(', ')}`;
    }

    // ESP companion status bars — one per connected companion
    _renderCompanionBars(status);

    // WiFi Adapters status bar
    _renderWifiAdaptersBar(status);

    // Serial ESP32 config card
    updateSerialStatus(status);

    // Collapsed diagnostics panel at the bottom of the tab
    renderWardrivingDiagnostics(status);
}

// --- Wardriving diagnostics panel -----------------------------------------
// Everything /api/wardriving/status exposes, grouped, collapsed by default.
// Mirrors the panel on the phone-access AP page (web/wardrive_mobile.html) and
// adds the antenna Coverage group, which only the full dashboard has room for.
// GPS leads: SNR max and satellites used-vs-in-view are what separate a
// weak-signal problem from a receiver that keeps restarting when it can see
// satellites but never fixes.
let _wdDiagLastStatus = null;
let _wdDiagBound = false;
// Deep payload from /api/wardriving/diagnostics (radios, power, GPS detail,
// errors). Fetched only while the panel is open — it walks sysfs and shells out
// to vcgencmd, so it must not ride the 3 s status poll.
let _wdDiagExtra = null;
let _wdDiagExtraAt = 0;
let _wdDiagExtraBusy = false;
const _WD_DIAG_EXTRA_TTL = 8000;

function _wdFetchDiagExtra(force) {
    const panel = document.getElementById('wd-diag');
    if (!panel || !panel.open || _wdDiagExtraBusy) return;
    if (!force && Date.now() - _wdDiagExtraAt < _WD_DIAG_EXTRA_TTL) return;
    _wdDiagExtraBusy = true;
    fetch('/api/wardriving/diagnostics', { cache: 'no-store' })
        .then(r => r.ok ? r.json() : null)
        .then(d => {
            if (d && !d.error) {
                _wdDiagExtra = d;
                _wdDiagExtraAt = Date.now();
                if (_wdDiagLastStatus) renderWardrivingDiagnostics(_wdDiagLastStatus);
            }
        })
        .catch(() => { /* panel degrades to the status-only groups */ })
        .finally(() => { _wdDiagExtraBusy = false; });
}

function _wdHas(v) { return v !== undefined && v !== null && v !== ''; }

function _wdAge(ts) {
    if (typeof ts !== 'number' || !isFinite(ts) || ts <= 0) return null;
    const s = Math.max(0, Math.round(Date.now() / 1000 - ts));
    if (s < 60) return `${s}s ago`;
    if (s < 3600) return `${Math.floor(s / 60)}m ago`;
    return `${Math.floor(s / 3600)}h${Math.floor(s / 60) % 60}m ago`;
}

// True when an epoch-seconds timestamp is older than `maxAge` seconds.
function _wdStale(ts, maxAge) {
    if (typeof ts !== 'number' || !isFinite(ts) || ts <= 0) return false;
    return (Date.now() / 1000 - ts) > maxAge;
}

function _wdDur(sec) {
    if (typeof sec !== 'number' || !isFinite(sec) || sec < 0) return null;
    const t = Math.round(sec), h = Math.floor(t / 3600), m = Math.floor(t / 60) % 60;
    return h ? `${h}h ${m}m` : `${m}m ${t % 60}s`;
}

// One titled group of key/value rows. Rows with no value are dropped, and a
// group with nothing left to show is skipped entirely.
// Polar sky plot of satellites by azimuth/elevation, coloured per
// constellation — the graphical half of the GSV data u-center draws. North is
// up, zenith at the centre, horizon at the outer ring. Fill opacity tracks SNR
// so a weak-but-tracked satellite reads as faint; an untracked one (no SNR)
// shows as a hollow ring. Colours are inline (SVG attrs / style), not Tailwind
// classes, so the purged tailwind.css bundle needs no rebuild.
const _WD_SKY_COLORS = {
    GPS: '#34d399', GLONASS: '#f87171', Galileo: '#60a5fa',
    BeiDou: '#fbbf24', QZSS: '#a78bfa', NavIC: '#f472b6', combined: '#94a3b8'
};

function _wdSkyPlot(sky) {
    const pts = (sky || []).filter(s => _wdHas(s.az) && _wdHas(s.elev));
    if (!pts.length) return '';
    const S = 220, c = S / 2, R = c - 16;   // leave a margin for cardinal labels
    // Elevation rings at 0°, 30°, 60° (radius = (90 - elev) / 90).
    const rings = [1, 2 / 3, 1 / 3].map(f =>
        `<circle cx="${c}" cy="${c}" r="${(R * f).toFixed(1)}" fill="none" stroke="#334155" stroke-width="1"/>`
    ).join('');
    const card = [['N', 0], ['E', 90], ['S', 180], ['W', 270]].map(([lab, az]) => {
        const a = az * Math.PI / 180;
        const lx = c + (R + 9) * Math.sin(a), ly = c - (R + 9) * Math.cos(a);
        return `<text x="${lx.toFixed(1)}" y="${(ly + 3).toFixed(1)}" fill="#64748b" font-size="10" text-anchor="middle">${lab}</text>`;
    }).join('');
    const dots = pts.map(s => {
        const elev = Math.max(0, Math.min(90, s.elev));
        const r = R * (90 - elev) / 90;
        const a = s.az * Math.PI / 180;
        const x = c + r * Math.sin(a), y = c - r * Math.cos(a);
        const col = _WD_SKY_COLORS[s.constellation] || '#94a3b8';
        const hasSnr = _wdHas(s.snr) && s.snr > 0;
        const op = hasSnr ? (0.3 + 0.7 * Math.min(1, s.snr / 50)) : 0.35;
        const fill = hasSnr ? col : 'none';
        const tip = `${s.constellation} PRN ${s.prn} · el ${s.elev}° az ${s.az}°`
            + (hasSnr ? ` · SNR ${s.snr} dB` : ' · untracked');
        return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.2" fill="${fill}" stroke="${col}" stroke-width="1" opacity="${op.toFixed(2)}"><title>${escapeHtml(tip)}</title></circle>`;
    }).join('');
    const svg = `<svg viewBox="0 0 ${S} ${S}" class="w-full" style="max-width:240px" xmlns="http://www.w3.org/2000/svg">
        <circle cx="${c}" cy="${c}" r="${R}" fill="#0f172a"/>
        ${rings}
        <line x1="${c}" y1="${c - R}" x2="${c}" y2="${c + R}" stroke="#334155" stroke-width="1"/>
        <line x1="${c - R}" y1="${c}" x2="${c + R}" y2="${c}" stroke="#334155" stroke-width="1"/>
        ${card}${dots}
    </svg>`;
    const present = [...new Set(pts.map(s => s.constellation))];
    const legend = present.map(name => {
        const col = _WD_SKY_COLORS[name] || '#94a3b8';
        return `<span class="inline-flex items-center gap-1 mr-2"><span style="width:8px;height:8px;border-radius:9999px;background:${col};display:inline-block"></span>${escapeHtml(name)}</span>`;
    }).join('');
    return `<div class="min-w-0">
        <h4 class="text-xs uppercase tracking-wide text-gray-500 font-semibold mb-2 pb-1 border-b border-slate-700 flex items-center justify-between">
            <span>GPS sky view</span>
            <button onclick="wdOpenSkyView()" title="Fullscreen sky view with stars"
                class="normal-case tracking-normal text-[11px] font-normal text-sky-400 hover:text-sky-300">⛶ Fullscreen</button>
        </h4>
        <div class="flex flex-col items-center">${svg}
            <div class="text-[10px] text-gray-400 mt-1 flex flex-wrap justify-center">${legend}</div>
        </div>
    </div>`;
}

// Open the fullscreen sky view (stars + satellites), seeded from the deep
// diagnostics payload the panel already holds so the first frame isn't blank.
function wdOpenSkyView() {
    if (!window.RagnarSkyView) return;
    const gps = (_wdDiagExtra && _wdDiagExtra.gps) || {};
    window.RagnarSkyView.open({ sky: gps.sky || [], status: gps.status || {} });
}
window.wdOpenSkyView = wdOpenSkyView;

function _wdDiagGroup(title, rows) {
    const kept = rows.filter(r => _wdHas(r[1]));
    if (!kept.length) return '';
    const body = kept.map(([k, v, tone]) => {
        const cls = tone === 'warn' ? 'text-red-400'
                  : tone === 'good' ? 'text-emerald-400' : 'text-gray-200';
        return `<div class="flex items-baseline gap-3 py-0.5">
            <span class="text-gray-500 whitespace-nowrap">${escapeHtml(String(k))}</span>
            <span class="${cls} ml-auto text-right font-mono break-all">${escapeHtml(String(v))}</span>
        </div>`;
    }).join('');
    return `<div class="min-w-0">
        <h4 class="text-xs uppercase tracking-wide text-gray-500 font-semibold mb-2 pb-1 border-b border-slate-700">${escapeHtml(title)}</h4>
        <div class="text-xs">${body}</div>
    </div>`;
}

function renderWardrivingDiagnostics(status) {
    const panel = document.getElementById('wd-diag');
    const body = document.getElementById('wd-diag-body');
    if (!panel || !body) return;

    _wdDiagLastStatus = status || {};
    const st = _wdDiagLastStatus;
    const gps = st.gps || {};
    const stats = st.stats || {};

    // Headline stays readable while collapsed so a glance often suffices.
    const note = document.getElementById('wd-diag-note');
    if (note) {
        let hint = gps.has_fix ? 'GPS fix' : (gps.connected ? 'GPS searching' : 'no GPS');
        if (st.error || gps.error) hint += ' · error';
        note.textContent = hint;
    }

    // Re-render on expand instead of keeping the DOM warm while hidden.
    if (!_wdDiagBound) {
        _wdDiagBound = true;
        panel.addEventListener('toggle', () => {
            if (!panel.open) return;
            _wdFetchDiagExtra(true);
            if (_wdDiagLastStatus) renderWardrivingDiagnostics(_wdDiagLastStatus);
        });
    }
    if (!panel.open) return;
    _wdFetchDiagExtra(false);   // refresh the deep payload while open

    const sats = (_wdHas(gps.satellites) || _wdHas(gps.satellites_in_view))
        ? `${gps.satellites || 0} used / ${gps.satellites_in_view || 0} in view` : null;

    const groups = [];

    groups.push(_wdDiagGroup('GPS', [
        ['Fix', gps.has_fix ? 'yes' : 'no', gps.has_fix ? 'good' : 'warn'],
        ['Fix quality', gps.fix_quality],
        ['Satellites', sats],
        ['SNR max', _wdHas(gps.snr_max) ? `${gps.snr_max} dB` : null],
        ['HDOP', gps.hdop],
        ['Latitude', _wdHas(gps.latitude) ? Number(gps.latitude).toFixed(6) : null],
        ['Longitude', _wdHas(gps.longitude) ? Number(gps.longitude).toFixed(6) : null],
        ['Altitude', _wdHas(gps.altitude) ? `${Number(gps.altitude).toFixed(1)} m` : null],
        ['Speed', _wdHas(gps.speed_kmh) ? formatWardrivingSpeed(gps.speed_kmh) : null],
        ['Course', _wdHas(gps.course) ? `${Number(gps.course).toFixed(0)}°` : null],
        ['Connected', gps.connected ? 'yes' : 'no'],
        ['Source', gps.source],
        ['Port', gps.port],
        ['Last update', _wdAge(gps.last_update)],
        // last_sentence is a TIMESTAMP of the last NMEA sentence, not its text
        // — rendering it raw printed a bare epoch float on the device. Flag it
        // red once it goes stale: a feed that stopped looks exactly like a weak
        // one in the numbers above, which just sit at their last value.
        ['Last NMEA', _wdAge(gps.last_sentence),
            _wdStale(gps.last_sentence, 30) ? 'warn' : null],
        ['Time to first fix', _wdHas(gps.ttff_seconds) ? `${gps.ttff_seconds}s` : null],
        ['Searching for', _wdHas(gps.searching_seconds)
            ? `${_wdDur(gps.searching_seconds)} (no fix yet)` : null,
            gps.searching_seconds > 120 ? 'warn' : null],
        ['GPS error', gps.error, 'warn']
    ]));

    // Per-constellation GSV breakdown + serial plumbing, from the deeper
    // /api/wardriving/diagnostics payload.
    const ex = _wdDiagExtra || {};
    const exGps = ex.gps || {};
    if ((exGps.constellations || []).length) {
        groups.push(_wdDiagGroup('GPS constellations',
            exGps.constellations.map(c => [
                c.constellation,
                `${c.in_view} in view` + (_wdHas(c.snr_max) ? ` · SNR ${c.snr_max} dB` : '')
            ])));
    }
    if ((exGps.sky || []).length) {
        const skyHtml = _wdSkyPlot(exGps.sky);
        if (skyHtml) groups.push(skyHtml);
    }

    const strongest = stats.strongest || null;
    groups.push(_wdDiagGroup('Session', [
        ['Session', st.session_id],
        ['Duration', _wdDur(stats.duration_seconds)],
        ['Networks', stats.total_networks],
        ['Open / WEP / WPA', _wdHas(stats.total_networks)
            ? `${stats.open_networks || 0} / ${stats.wep_networks || 0} / ${stats.wpa_networks || 0}` : null],
        ['2.4 / 5 / 6 GHz', _wdHas(stats.total_networks)
            ? `${stats.band_2_4ghz || 0} / ${stats.band_5ghz || 0} / ${stats.band_6ghz || 0}` : null],
        ['Bluetooth', stats.bluetooth_devices],
        ['Cell towers', stats.cell_towers],
        ['Thread / Zigbee', stats.zigbee_devices],
        ['Cameras', stats.cameras],
        ['GPS trackpoints', stats.gps_trackpoints],
        ['Strongest', strongest ? `${strongest.ssid || strongest.bssid || '?'}` +
            (_wdHas(strongest.best_rssi) ? ` (${strongest.best_rssi} dBm)` : '') : null],
        ['Database', stats.db_path]
    ]));

    const scanRows = [
        ['Running', st.running ? 'yes' : 'no', st.running ? 'good' : 'warn'],
        ['Band mode', st.band_mode],
        ['Scans completed', st.scans_completed],
        ['Networks last scan', st.networks_this_scan],
        ['Last scan', _wdAge(st.last_scan_time),
            (st.running && _wdStale(st.last_scan_time, 60)) ? 'warn' : null],
        ['Interfaces', (st.interfaces || []).join(', ')],
        ['Engine error', st.error, 'warn']
    ];
    (st.interface_details || []).forEach(d => {
        const bits = [];
        if (_wdHas(d.networks)) bits.push(`${d.networks} nets`);
        if (d.driver) bits.push(d.driver);
        if (d.bands) bits.push([].concat(d.bands).join('/'));
        if (d.is_usb) bits.push('USB');
        if (d.manufacturer) bits.push(d.manufacturer);
        scanRows.push([`  ${d.name}`, bits.join(' · ')]);
    });
    groups.push(_wdDiagGroup('Scanning', scanRows));

    // Antenna coverage — which adapter is actually pulling its weight.
    const cov = st.coverage || {};
    const perIface = cov.per_interface || {};
    const covRows = [['Seen by 2+ adapters', cov.overlap]];
    Object.keys(perIface).forEach(name => {
        const c = perIface[name] || {};
        const bits = [];
        if (_wdHas(c.unique)) bits.push(`${c.unique} uniq`);
        if (_wdHas(c.only_here)) bits.push(`${c.only_here} only here`);
        if (_wdHas(c.best_rssi_median)) bits.push(`med ${Number(c.best_rssi_median).toFixed(0)} dBm`);
        covRows.push([`  ${name}`, bits.join(' · ')]);
    });
    groups.push(_wdDiagGroup('Coverage', covRows));

    const comps = st.companions || [];
    const compRows = [['Companions', comps.length || null]];
    comps.forEach(c => {
        const bits = [c.connected ? 'up' : 'down'];
        if (_wdHas(c.networks)) bits.push(`${c.networks} nets`);
        if (_wdHas(c.networks_24) || _wdHas(c.networks_5)) {
            bits.push(`${c.networks_24 || 0}/${c.networks_5 || 0} 2.4/5`);
        }
        if (c.esp_mode) bits.push(c.esp_mode);
        if (_wdHas(c.esp_ble_count)) bits.push(`${c.esp_ble_count} BLE`);
        if (c.esp_zigbee_count) bits.push(`${c.esp_zigbee_count} Zig`);
        if (c.mesh_node_count) bits.push(`${c.mesh_node_count} nodes`);
        if (c.coordinator_board) bits.push(c.coordinator_board);
        if (c.coordinator_fw) bits.push(`fw ${c.coordinator_fw}`);
        compRows.push([`  ${c.name || c.port || 'companion'}`, bits.join(' · ')]);
        (c.esp_alerts || []).slice(-3).forEach((a, i) => {
            compRows.push([`    alert ${i + 1}`,
                typeof a === 'string' ? a : JSON.stringify(a), 'warn']);
        });
    });
    groups.push(_wdDiagGroup('Companions', compRows));

    // Radios — every wireless interface present, and when one is NOT scanning,
    // the reason. This is what turns "only wlan0 is listed" from a mystery into
    // a statement (rfkill-blocked / held as uplink / lent to the AP / unclaimed).
    const radios = ex.radios || [];
    if (radios.length) {
        const rows = [];
        radios.forEach(r => {
            const bits = [];
            if (r.driver) bits.push(r.driver);
            if (r.mode) bits.push(r.mode);
            if (r.operstate) bits.push(r.operstate);
            if (r.usb && r.usb.max_power_ma) bits.push(`${r.usb.max_power_ma} mA`);
            if (r.usb && (r.usb.product || r.usb.manufacturer)) {
                bits.push(r.usb.product || r.usb.manufacturer);
            }
            rows.push([r.name, (r.scanning ? 'scanning' : 'idle') +
                (bits.length ? ' · ' + bits.join(' · ') : ''),
                r.scanning ? 'good' : 'warn']);
            if (r.excluded_reason) rows.push([`  why not`, r.excluded_reason, 'warn']);
        });
        groups.push(_wdDiagGroup('Radios', rows));
    }

    // Power — declared USB draw per device plus Pi supply health. bMaxPower is
    // the descriptor's declared draw, not a measurement; no Pi meters per-port
    // current. It is still the figure the host budgets against.
    const pw = ex.power || {};
    if (Object.keys(pw).length) {
        const rows = [];
        if (pw.model) rows.push(['Board', pw.model]);
        (pw.usb_devices || []).forEach(d => {
            const label = d.product || d.manufacturer || d.usb_id || d.id;
            const bits = [];
            if (_wdHas(d.max_power_ma)) bits.push(`${d.max_power_ma} mA`);
            if (d.interfaces && d.interfaces.length) bits.push(d.interfaces.join(', '));
            if (d.speed_mbps) bits.push(`${d.speed_mbps} Mb/s`);
            rows.push([`  ${label}`, bits.join(' · ')]);
        });
        if (_wdHas(pw.usb_declared_ma)) {
            rows.push(['USB declared total', `${pw.usb_declared_ma} mA` +
                (pw.usb_count ? ` (${pw.usb_count} devices)` : ''),
                pw.usb_declared_ma > 600 ? 'warn' : null]);
        }
        if (pw.usb_max_current_enabled === false) {
            rows.push(['usb_max_current_enable', 'not set', 'warn']);
        } else if (pw.usb_max_current_enabled === true) {
            rows.push(['usb_max_current_enable', 'set', 'good']);
        }
        const thr = pw.throttled;
        if (thr) {
            rows.push(['Supply', thr.healthy ? 'healthy' : 'see flags below',
                thr.healthy ? 'good' : 'warn']);
            if ((thr.now || []).length) rows.push(['  Right now', thr.now.join(', '), 'warn']);
            if ((thr.occurred || []).length) rows.push(['  Since boot', thr.occurred.join(', '), 'warn']);
            rows.push(['  throttled flags', thr.raw]);
        }
        if (_wdHas(pw.core_volts)) rows.push(['Core voltage', `${pw.core_volts} V`]);
        if (_wdHas(pw.temp_c)) rows.push(['Temperature', `${pw.temp_c} °C`]);
        if (pw.pmic && _wdHas(pw.pmic.total_watts)) {
            rows.push(['Board power (PMIC)', `${pw.pmic.total_watts} W`]);
        }
        groups.push(_wdDiagGroup('Power', rows));
    }

    // Errors — everything currently complaining, in one place.
    const errs = ex.errors || [];
    if (errs.length) {
        groups.push(_wdDiagGroup('Errors',
            errs.map(e => [e.source, e.message, 'warn'])));
    }

    groups.push(_wdDiagGroup('Device', [
        ['Device name', st.device_name],
        ['Bluetooth seen', st.bluetooth_count],
        ['Cells seen', st.cell_count],
        ['GPS backfill', _wdHas(st.allow_backfill) ? (st.allow_backfill ? 'allowed' : 'off') : null]
    ]));

    const html = groups.filter(Boolean).join('');
    body.innerHTML = html
        // gap-6 (not gap-x-8/gap-y-5): web/css/tailwind.css is a prebuilt,
        // purged bundle and there is no local Tailwind CLI to rebuild it, so
        // every class here must already exist in that file.
        ? `<div class="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">${html}</div>`
        : '<p class="text-gray-500 text-sm">No diagnostics available yet.</p>';
}

// Render one status bar per connected USB companion. The backend exposes a
// full per-device list in status.companions; we render each separately rather
// than collapsing them into one aggregated bar (which showed up as e.g.
// "Piglet, Piglet" on a single line with summed counts).
const _ESP_MODE_LABELS = {
    wifi: 'WiFi', 'ble-flipper': '🐬 Flipper', 'ble-airtag': '🏷️ AirTag',
    'ble-skimmer': '💳 Skimmer', pineap: '🍍 PineAP', ble: 'BLE',
    stations: 'Stations', wardrive: '🏎️ Wardrive (fast)', zigbee: '🐝 Zigbee / Thread'
};

function _renderCompanionBars(status) {
    const container = document.getElementById('wd-esp-companions');
    if (!container) return;
    const companions = Array.isArray(status.companions) ? status.companions : [];

    if (companions.length === 0) {
        container.innerHTML =
            `<div class="bg-slate-800/40 border border-slate-700 rounded-lg px-4 py-2 flex items-center gap-3 flex-wrap">
                <span class="text-xs font-bold text-purple-400">Companion</span>
                <span class="w-2 h-2 rounded-full bg-gray-500 animate-pulse"></span>
                <span class="text-xs text-gray-400">Ragnar looking for Huginn or Piglet...</span>
            </div>`;
        return;
    }

    // "Unique" (ESP-only networks vs local adapters) is a session-wide
    // aggregate, so it can only be attributed to a device when exactly one
    // companion is connected. With several, we omit it from the per-bar view.
    const single = companions.filter(c => c.connected).length === 1;
    container.innerHTML = companions
        .map(c => _companionBarHtml(c, single, status))
        .join('');
}

function _companionBarHtml(c, single, status) {
    const name     = c.name || 'Companion';
    const isPiglet = name === 'Piglet' || name === 'Piglet Coordinator';
    const isCoord  = name === 'Piglet Coordinator';
    const isHuginn = name === 'Huginn';
    const isZigbeeRole = isHuginn && c.role === 'zigbee';
    const dotColor = c.connected ? 'bg-green-500' : 'bg-gray-500';

    const chips = [];
    const sep = '<span class="text-xs text-gray-500">|</span>';

    // Mode — only Huginn / Piglet Core switch scan modes; hidden for Piglet.
    if (c.connected && !isPiglet) {
        const mode = _ESP_MODE_LABELS[c.esp_mode] || c.esp_mode || '';
        chips.push(`${sep}
            <span class="text-xs text-gray-400">Mode:</span>
            <span class="text-xs font-bold text-amber-400">${escapeHtml(mode)}</span>`);
    }

    // WiFi / Records — Coordinator shows mesh records + distinct BSSIDs.
    if (c.connected && isCoord) {
        const nodes = Array.isArray(c.coordinator_nodes) ? c.coordinator_nodes : [];
        const totalRx = nodes.reduce((a, n) => a + (n.records_rx || 0), 0);
        chips.push(`${sep}
            <span class="text-xs text-gray-400">Records:</span>
            <span class="text-xs font-bold text-emerald-400">${totalRx}</span>`);
        if (single) {
            chips.push(`${sep}
                <span class="text-xs text-gray-400">WiFi:</span>
                <span class="text-xs font-bold text-emerald-400">${status.serial_seen_unique || 0}</span>`);
        }
    } else if (c.connected && isZigbeeRole) {
        // Dedicated Zigbee/Thread node — WiFi/BLE are parked, so show only the
        // 802.15.4 tally (matches what this node actually captures).
        chips.push(`${sep}
            <span class="text-xs text-gray-400">Zigbee / Thread:</span>
            <span class="text-xs font-bold text-teal-400">${c.esp_zigbee_count || 0}</span>`);
    } else if (c.connected) {
        chips.push(`${sep}
            <span class="text-xs text-gray-400">WiFi:</span>
            <span class="text-xs font-bold text-emerald-400">${c.networks || 0}</span>`);
        // Per-band breakdown. Dual-band boards (Huginn on a C5) always show the
        // 2.4/5 split so the two bands are legible; a 2.4-only board (ESP32-S3)
        // only gets the split once a 5 GHz network has actually been seen.
        if (isHuginn || (c.networks_5 || 0) > 0) {
            chips.push(`<span class="text-xs text-cyan-400">${c.networks_24 || 0}</span>
                <span class="text-xs text-gray-500">2.4G</span>
                <span class="text-xs text-purple-400">${c.networks_5 || 0}</span>
                <span class="text-xs text-gray-500">5G</span>`);
        }
    }

    // BLE — hidden for Piglet / Coordinator (WiFi-only) and for a Zigbee node.
    if (c.connected && !isPiglet && !isZigbeeRole) {
        chips.push(`<span class="text-xs text-gray-400">BLE:</span>
            <span class="text-xs font-bold text-blue-400">${c.esp_ble_count || 0}</span>`);
    }

    // Zigbee chip for a normal companion that happens to report 802.15.4 (the
    // dedicated Zigbee node already shows its tally above).
    if (c.connected && !isZigbeeRole && c.esp_zigbee_count) {
        chips.push(`<span class="text-xs text-gray-400">Zig:</span>
            <span class="text-xs font-bold text-teal-400">${c.esp_zigbee_count}</span>`);
    }

    // Unique — session aggregate, only meaningful for a lone companion.
    if (c.connected && single && !(isPiglet && !isCoord)) {
        chips.push(`<span class="text-xs text-gray-400">Unique:</span>
            <span class="text-xs font-bold text-cyan-400">${status.serial_unique || 0}</span>`);
    }

    // Mesh node count — Piglet Core / Coordinator.
    if (c.connected && c.mesh_node_count > 0) {
        chips.push(`${sep}
            <span class="text-xs text-gray-400">Mesh:</span>
            <span class="text-xs font-bold text-orange-400">${c.mesh_node_count}</span>
            <span class="text-xs text-gray-500">nodes</span>`);
    }

    let alertHtml = '';
    if (c.connected && Array.isArray(c.esp_alerts) && c.esp_alerts.length > 0) {
        const latest = c.esp_alerts[c.esp_alerts.length - 1];
        alertHtml = `<span class="text-xs font-bold text-red-400 ml-2">⚠️ ${escapeHtml(latest.alert || '')}</span>`;
    }

    const statusText = c.connected
        ? ''
        : '<span class="text-xs text-gray-400">Ragnar looking for Huginn or Piglet...</span>';

    // Role selector (Huginn only). One C5 can't do WiFi + 802.15.4 at once, so a
    // dedicated second Huginn can be flipped to Zigbee/Thread-only here.
    let roleHtml = '';
    if (c.connected && name === 'Huginn') {
        const role = c.role === 'zigbee' ? 'zigbee' : 'wardrive';
        roleHtml = `<span class="ml-auto flex items-center gap-1">
            <span class="text-xs text-gray-500">Role:</span>
            <select onchange="setCompanionRole('${escapeHtml(c.port)}', this.value)"
                title="What this Huginn does. One ESP32-C5 shares a single 2.4 GHz radio, so it can wardrive WiFi+BLE OR sniff Zigbee/Thread — not both. Use a second Huginn for Zigbee."
                class="text-xs bg-slate-900 border border-slate-600 rounded px-1 py-0.5 text-gray-200 focus:border-teal-500 focus:outline-none">
                <option value="wardrive" ${role === 'wardrive' ? 'selected' : ''}>WiFi + BLE</option>
                <option value="zigbee" ${role === 'zigbee' ? 'selected' : ''}>Zigbee / Thread only</option>
            </select>
        </span>`;
    }

    return `<div class="bg-slate-800/40 border border-slate-700 rounded-lg px-4 py-2 flex items-center gap-3 flex-wrap">
            <span class="text-xs font-bold text-purple-400">${escapeHtml(name)}</span>
            ${statusText}
            <span class="w-2 h-2 rounded-full ${dotColor} animate-pulse"></span>
            ${chips.join('\n')}
            ${alertHtml}
            ${roleHtml}
        </div>${_coordNodesHtml(c)}`;
}

// Flip a Huginn companion between WiFi+BLE wardriving and Zigbee/Thread-only.
// Applied live server-side (the listener re-sends the mode command).
async function setCompanionRole(port, role) {
    try {
        await postAPI('/api/wardriving/companion_role', { port, role });
    } catch (e) {
        console.error('[Wardriving] set companion role failed:', e);
    }
}

// Per-node breakdown for a Piglet Coordinator / Core, rendered beneath its bar.
function _coordNodesHtml(c) {
    const nodes = Array.isArray(c.coordinator_nodes) ? c.coordinator_nodes : [];
    if (nodes.length === 0) return '';
    const total = nodes.length;
    const totalRx = nodes.reduce((a, n) => a + (n.records_rx || 0), 0);
    const boardParts = [];
    if (c.coordinator_board) boardParts.push(c.coordinator_board);
    if (c.coordinator_fw)    boardParts.push(c.coordinator_fw);
    const chips = nodes.map(n => {
        const mac = (n.mac || '').toUpperCase();
        const rx  = (n.records_rx || 0).toLocaleString();
        const age = Number(n.age_s || 0);
        let ageColor = 'text-emerald-400';
        if (age > 60)      ageColor = 'text-gray-500';
        else if (age > 30) ageColor = 'text-orange-400';
        const idx = (n.idx !== undefined) ? `#${n.idx}` : '';
        return `<span class="inline-flex items-center gap-2 bg-slate-900/60 border border-slate-700 rounded px-2 py-1">
            <span class="text-xs font-bold text-purple-300">node ${idx}</span>
            <span class="text-xs text-gray-400 font-mono">${escapeHtml(mac)}</span>
            <span class="text-xs text-gray-500">·</span>
            <span class="text-xs font-bold text-cyan-400">${rx}</span>
            <span class="text-xs text-gray-500">rx</span>
            <span class="text-xs text-gray-500">·</span>
            <span class="text-xs ${ageColor}">${age}s</span>
        </span>`;
    }).join('');
    return `<div class="bg-slate-800/30 border border-slate-700 rounded-lg px-4 py-2">
            <div class="flex items-center gap-2 mb-2">
                <span class="text-xs font-bold text-orange-400">🌐 Mesh nodes</span>
                <span class="text-xs text-gray-400">${total} connected — ${totalRx.toLocaleString()} records total</span>
                <span class="text-xs text-gray-500 ml-auto">${escapeHtml(boardParts.join(' · '))}</span>
            </div>
            <div class="flex flex-wrap gap-2">${chips}</div>
        </div>`;
}

function _renderWifiAdaptersBar(status) {
    const bar = document.getElementById('wd-adapters-bar');
    if (!bar) return;
    const details = status.interface_details;
    if (!details || details.length === 0) {
        bar.classList.add('hidden');
        return;
    }
    bar.classList.remove('hidden');
    const bandColors = {'2.4GHz': 'text-emerald-400', '5GHz': 'text-purple-400', '6GHz': 'text-pink-400'};
    const cov = status.coverage || {};
    const perIf = cov.per_interface || {};
    const bandMode = status.band_mode || 'redundant';

    // Color RSSI: stronger (less negative) is better. -50 great, -90 unusable.
    const rssiColor = (v) => {
        if (v == null || v === 0) return 'text-gray-500';
        if (v >= -55) return 'text-emerald-400';
        if (v >= -70) return 'text-yellow-400';
        return 'text-orange-400';
    };

    const cards = details.map(d => {
        const icon = d.is_usb ? '🔌' : '📡';
        const label = d.manufacturer || d.product || d.driver || d.name;
        // In split mode highlight the band(s) this adapter actually sweeps;
        // grey out the bands it could do but isn't assigned to. In redundant
        // mode every band stays lit (current behavior).
        const sweepSet = new Set((d.sweep_bands || []).map(b => b + 'GHz'));
        const bands = (d.bands || []).map(b => {
            const inSweep = bandMode !== 'split' || sweepSet.has(b);
            const colorClass = inSweep ? (bandColors[b] || 'text-gray-400') : 'text-gray-600';
            const bg = inSweep ? 'bg-slate-700' : 'bg-slate-800/60';
            return `<span class="px-1.5 py-0.5 rounded text-[10px] font-bold ${bg} ${colorClass}">${b}</span>`;
        }).join(' ');
        const nets = d.networks || 0;
        const c = perIf[d.name];
        let coverageRow = '';
        if (c) {
            const median = c.best_rssi_median;
            const avg = c.best_rssi_avg;
            coverageRow = `
            <div class="w-full flex items-center gap-3 flex-wrap pl-7 pt-1 text-[11px]">
                <span class="text-gray-400">Only here:</span>
                <span class="font-bold ${c.only_here > 0 ? 'text-cyan-300' : 'text-gray-500'}">${c.only_here}</span>
                <span class="text-gray-600">·</span>
                <span class="text-gray-400">Median RSSI:</span>
                <span class="font-bold ${rssiColor(median)}">${median != null ? median + ' dBm' : '—'}</span>
                <span class="text-gray-600">·</span>
                <span class="text-gray-400">Avg:</span>
                <span class="font-bold ${rssiColor(avg)}">${avg != null ? avg + ' dBm' : '—'}</span>
            </div>`;
        }
        let diagRow = '';
        if (nets === 0 && (d.scan_error || (d.current_type && d.current_type !== 'managed'))) {
            const bits = [];
            if (d.current_type && d.current_type !== 'managed') {
                bits.push(`mode=<span class="text-orange-400 font-bold">${escapeHtml(d.current_type)}</span>`);
            }
            if (d.scan_error) {
                bits.push(`<span class="text-red-400">${escapeHtml(d.scan_error)}</span>`);
            }
            diagRow = `
            <div class="w-full flex items-center gap-2 flex-wrap pl-7 pt-1 text-[11px]">
                <span class="text-gray-400">⚠ Scan failing:</span>
                ${bits.join(' <span class="text-gray-600">·</span> ')}
            </div>`;
        }
        return `<div class="bg-slate-800/40 border border-slate-700 rounded-lg px-4 py-2 flex items-center gap-3 flex-wrap">
            <span class="text-sm">${icon}</span>
            <span class="text-xs font-bold text-cyan-400">${escapeHtml(d.name)}</span>
            <span class="text-xs text-gray-400">${escapeHtml(label)}</span>
            <span class="flex gap-1">${bands}</span>
            <span class="text-xs text-gray-500">|</span>
            <span class="text-xs text-gray-400">Networks:</span>
            <span class="text-xs font-bold text-emerald-400">${nets}</span>
            ${coverageRow}
            ${diagRow}
        </div>`;
    }).join('');

    // Overlap summary — only meaningful with 2+ scanner interfaces present
    let summary = '';
    if (details.length >= 2 && cov.overlap != null) {
        const ifNames = details.map(d => d.name);
        const winnerByMedian = ifNames
            .filter(n => perIf[n] && perIf[n].best_rssi_median)
            .sort((a, b) => perIf[b].best_rssi_median - perIf[a].best_rssi_median)[0];
        const winnerByUnique = ifNames
            .filter(n => perIf[n])
            .sort((a, b) => perIf[b].unique - perIf[a].unique)[0];
        const winnerChip = (label, name) => name
            ? `<span class="text-gray-400">${label}:</span> <span class="font-bold text-cyan-300">${escapeHtml(name)}</span>`
            : '';
        summary = `<div class="bg-slate-800/20 border border-slate-700/50 rounded-lg px-4 py-1.5 flex items-center gap-4 flex-wrap text-[11px] mt-1">
            <span class="text-gray-400">Shared (both saw):</span>
            <span class="font-bold text-emerald-400">${cov.overlap}</span>
            <span class="text-gray-600">·</span>
            ${winnerChip('Best signal', winnerByMedian)}
            <span class="text-gray-600">·</span>
            ${winnerChip('Widest coverage', winnerByUnique)}
        </div>`;
    }

    // Header chip showing current band mode (only when meaningful: >=2 adapters).
    // Clickable to flip mode + restart wardriving so the change takes effect.
    let modeHeader = '';
    if (details.length >= 2) {
        const modeLabel = bandMode === 'split'
            ? '<span class="text-emerald-400 font-bold">Split bands</span> <span class="text-gray-500">(each adapter on its own band — faster cycles, no redundant sweeps)</span>'
            : '<span class="text-yellow-400 font-bold">Redundant</span> <span class="text-gray-500">(every adapter sweeps every band — more reliable, slower)</span>';
        const toggleTo = bandMode === 'split' ? 'redundant' : 'split';
        modeHeader = `<div class="text-[11px] mb-1 flex items-center gap-2">
            <span>Scan mode: ${modeLabel}</span>
            <button onclick="toggleWardrivingBandMode('${toggleTo}')" class="px-2 py-0.5 rounded bg-slate-700 hover:bg-slate-600 text-cyan-300 text-[10px] font-bold border border-slate-600">switch to ${toggleTo}</button>
        </div>`;
    }
    bar.innerHTML = modeHeader + cards + summary;
}

async function toggleWardrivingBandMode(newMode) {
    if (!confirm(`Switch wardriving to "${newMode}" mode?\n\nThis stops and restarts the current session — your data is preserved (same DB), but the running session ID will change.`)) return;
    try {
        // 1. Persist config so the new mode survives reboots
        const cfgRes = await fetch('/api/config', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({wardriving_band_mode: newMode})
        });
        if (!cfgRes.ok) throw new Error('config write failed');

        // 2. Stop the current session — engine reads band_mode at start()
        await fetch('/api/wardriving/stop', {method: 'POST'});

        // 3. Start a new session that picks up the new mode
        const startRes = await fetch('/api/wardriving/start', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({})
        });
        const data = await startRes.json();
        if (data.error) {
            alert('Start failed: ' + data.error);
            return;
        }
        if (typeof addConsoleMessage === 'function') {
            addConsoleMessage(`Wardriving band mode → ${newMode}`, 'success');
        }
    } catch (e) {
        alert('Band-mode switch failed: ' + e.message);
    }
}

async function saveWardrivingDeviceName(name) {
    try {
        await fetch('/api/wardriving/device_name', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({name: name})
        });
    } catch (e) {
        console.error('[Wardriving] Save device name error:', e);
    }
}

async function wipeWardrivingData() {
    if (!confirm('Are you sure you want to delete ALL wardriving data?\n\nThis will permanently remove all session databases and cannot be undone.')) return;
    if (!confirm('This is your last chance. Really wipe all wardriving data?')) return;
    try {
        const res = await fetch('/api/wardriving/wipe', { method: 'POST' });
        const data = await res.json();
        if (data.error) {
            alert('Error: ' + data.error);
        } else {
            alert('Wardriving data wiped. ' + (data.deleted || 0) + ' files deleted.');
            if (typeof loadWardrivingSessions === 'function') loadWardrivingSessions();
        }
    } catch (e) {
        alert('Wipe failed: ' + e.message);
    }
}

function applyWardrivingEnabledState(enabled) {
    document.querySelectorAll('.wardriving-feature').forEach(el => {
        el.classList.toggle('hidden', !enabled);
    });
    const body = document.getElementById('wardriving-config-body');
    if (body) body.classList.toggle('hidden', !enabled);
    const toggle = document.getElementById('wardriving-enable-toggle');
    if (toggle) toggle.checked = !!enabled;
}

async function toggleWardrivingEnabled(checkbox) {
    const enabled = !!checkbox.checked;
    applyWardrivingEnabledState(enabled);
    try {
        await postAPI('/api/config', { wardriving_enabled: enabled });
        addConsoleMessage('Wardriving ' + (enabled ? 'enabled' : 'disabled'), 'success');
    } catch (e) {
        console.error('[Wardriving] enable toggle error:', e);
        addConsoleMessage('Failed to update wardriving setting', 'error');
        applyWardrivingEnabledState(!enabled);
    }
}

async function toggleWardrivingOnBoot() {
    const cb = document.getElementById('wardriving-on-boot');
    if (!cb) return;
    try {
        const res = await fetch('/api/wardriving/on_boot', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({enabled: cb.checked})
        });
        const data = await res.json();
        if (!data.success) {
            cb.checked = !cb.checked;
        }
    } catch (e) {
        console.error('[Wardriving] on_boot toggle error:', e);
        cb.checked = !cb.checked;
    }
}

async function loadWardrivingOnBootState() {
    try {
        const res = await fetch('/api/wardriving/on_boot');
        const data = await res.json();
        const cb = document.getElementById('wardriving-on-boot');
        if (cb) cb.checked = !!data.wardriving_on_boot;
    } catch (e) { /* silent */ }
}

// ---- Bluetooth provisioning (mobile-app discovery) ----
// Advertises a BLE GATT service so the Ragnar mobile app can find this box and
// read its IP. Off by default (shares the adapter with the BLE overlay
// scanner). See ble_provisioning.py + docs/ble_provisioning.md.
function _bleProvStatusText(d) {
    if (!d.enabled) return 'Disabled.';
    if (d.autostopped) return 'Provisioned — advertising stopped to free the radio. Tap Re-advertise for another device.';
    if (d.running) return 'Advertising as ' + (d.name || 'Ragnar') + (d.active_adapter ? ' on ' + d.active_adapter : '') + '.';
    if (d.error) return 'Enabled, but not advertising: ' + d.error + (d.hint ? ' — ' + d.hint : '');
    // Still registering with BlueZ — slow boards can take a while. Anything
    // else with no error is a state we have not heard back about yet.
    if (d.starting) return 'Starting — registering with BlueZ…';
    return 'Enabling…';
}

// Poll until the peripheral settles. Registration on a slow board (Pi Zero 2 W)
// can outlast the request that started it, and a single follow-up read then
// caught it mid-start and left "Enabling…" on screen permanently.
function _bleProvPollUntilSettled(tries) {
    tries = (typeof tries === 'number') ? tries : 8;
    if (tries <= 0) return;
    setTimeout(async () => {
        let d = null;
        try {
            const res = await fetch('/api/ble/provisioning');
            d = await res.json();
        } catch (e) { /* transient; keep trying */ }
        await loadBleProvisioning();
        // Keep going only while it is still coming up.
        if (d && d.enabled && !d.running && !d.error) {
            _bleProvPollUntilSettled(tries - 1);
        }
    }, 1500);
}

async function loadBleProvisioning() {
    try {
        const res = await fetch('/api/ble/provisioning');
        const d = await res.json();
        const cb = document.getElementById('ble-provisioning-enabled');
        if (cb) cb.checked = !!d.enabled;
        const asCb = document.getElementById('ble-provisioning-autostop');
        if (asCb) asCb.checked = !!d.autostop;
        const sel = document.getElementById('ble-provisioning-adapter');
        if (sel) {
            // Rebuild options: Auto + each controller, tagging the built-in one.
            const current = d.adapter || '';
            sel.innerHTML = '<option value="">Auto — prefer built-in radio</option>';
            (d.adapters || []).forEach(a => {
                const o = document.createElement('option');
                o.value = a.hci;
                o.textContent = a.hci + (a.builtin ? ' (built-in)' : (a.bus ? ' (' + a.bus + ')' : '')) + (a.address ? ' — ' + a.address : '');
                sel.appendChild(o);
            });
            sel.value = current;
        }
        // Show the Re-advertise button only once it has auto-stopped.
        const rebtn = document.getElementById('ble-provisioning-readvertise');
        if (rebtn) rebtn.classList.toggle('hidden', !(d.enabled && d.autostopped));
        // Under-voltage warning: running BLE + a USB radio on a weak PSU can
        // reset the whole Pi. Surface it so a "crash" reads as power, not code.
        const pw = document.getElementById('ble-provisioning-power');
        if (pw) {
            if (d.power && d.power.message) {
                pw.textContent = '⚠ ' + d.power.message;
                pw.classList.remove('hidden');
            } else {
                pw.classList.add('hidden');
            }
        }
        const st = document.getElementById('ble-provisioning-status');
        if (st) st.textContent = _bleProvStatusText(d);
    } catch (e) { /* silent */ }
}

async function setBleProvisioningAutostop(cb) {
    const enabled = !!(document.getElementById('ble-provisioning-enabled') || {}).checked;
    try {
        await postAPI('/api/ble/provisioning/toggle', { enabled, autostop: !!cb.checked });
        addConsoleMessage('Auto-stop after provisioning ' + (cb.checked ? 'on' : 'off'), 'success');
        setTimeout(loadBleProvisioning, 600);
    } catch (e) {
        console.error('[BLE] autostop set error:', e);
        addConsoleMessage('Failed to set auto-stop', 'error');
        cb.checked = !cb.checked;
    }
}

async function readvertiseBle() {
    try {
        await postAPI('/api/ble/provisioning/toggle', { enabled: true });
        addConsoleMessage('Re-advertising over Bluetooth', 'success');
        setTimeout(loadBleProvisioning, 600);
    } catch (e) {
        console.error('[BLE] re-advertise error:', e);
        addConsoleMessage('Failed to re-advertise', 'error');
    }
}

async function toggleBleProvisioning(checkbox) {
    const enabled = !!checkbox.checked;
    const st = document.getElementById('ble-provisioning-status');
    if (st) st.textContent = enabled ? 'Enabling…' : 'Disabling…';
    try {
        const res = await postAPI('/api/ble/provisioning/toggle', { enabled });
        addConsoleMessage('Bluetooth provisioning ' + (enabled ? 'enabled' : 'disabled'), 'success');
        if (res && st) st.textContent = _bleProvStatusText(Object.assign({ enabled: enabled }, res));
        // Re-read for the active adapter / advertised name once settled.
        setTimeout(loadBleProvisioning, 600);
        // Keep watching while it is still registering.
        if (enabled && res && !res.running) _bleProvPollUntilSettled();
    } catch (e) {
        console.error('[BLE] provisioning toggle error:', e);
        addConsoleMessage('Failed to update Bluetooth provisioning', 'error');
        checkbox.checked = !enabled;
        if (st) st.textContent = 'Failed to update.';
    }
}

async function setBleProvisioningAdapter(sel) {
    const enabled = !!(document.getElementById('ble-provisioning-enabled') || {}).checked;
    try {
        await postAPI('/api/ble/provisioning/toggle', { enabled, adapter: sel.value });
        addConsoleMessage('Bluetooth adapter set to ' + (sel.value || 'auto'), 'success');
        setTimeout(loadBleProvisioning, 600);
    } catch (e) {
        console.error('[BLE] adapter set error:', e);
        addConsoleMessage('Failed to set Bluetooth adapter', 'error');
    }
}

// GPS backfill is gated: the map "Backfill GPS" button stays hidden until the
// user opts in here. Backfilled positions are estimates (not WDGWARS-legal) and
// are excluded from WiGLE export, so this defaults off.
function applyWardrivingBackfillVisibility(allow) {
    const btn = document.getElementById('wd-map-backfill-btn');
    if (btn) btn.classList.toggle('hidden', !allow);
}

async function toggleWardrivingBackfill() {
    const cb = document.getElementById('wardriving-allow-backfill');
    if (!cb) return;
    const enabled = !!cb.checked;
    try {
        await postAPI('/api/config', { wardriving_allow_backfill: enabled });
        applyWardrivingBackfillVisibility(enabled);
        addConsoleMessage(
            'GPS backfill ' + (enabled ? 'enabled — backfilled data is excluded from WiGLE export' : 'disabled'),
            enabled ? 'warning' : 'info'
        );
    } catch (e) {
        console.error('[Wardriving] backfill toggle error:', e);
        addConsoleMessage('Failed to update GPS backfill setting', 'error');
        cb.checked = !enabled;
    }
}

async function loadWardrivingBackfillState() {
    try {
        const res = await fetch('/api/config');
        const cfg = await res.json();
        const allow = !!cfg.wardriving_allow_backfill;
        const cb = document.getElementById('wardriving-allow-backfill');
        if (cb) cb.checked = allow;
        applyWardrivingBackfillVisibility(allow);
    } catch (e) { /* silent */ }
}

// Speed unit ('kmh' | 'mph') is display-only — recorded data stays in km/h.
// Applies the choice to the card toggle, the label emphasis, and the module-level
// _wdSpeedUnit used by formatWardrivingSpeed() for all live readouts.
function applyWardrivingSpeedUnitState(unit) {
    _wdSpeedUnit = (unit === 'mph') ? 'mph' : 'kmh';
    const cb = document.getElementById('wardriving-speed-unit');
    if (cb) cb.checked = (_wdSpeedUnit === 'mph');
    const kmhLabel = document.getElementById('wd-speed-unit-kmh-label');
    const mphLabel = document.getElementById('wd-speed-unit-mph-label');
    if (kmhLabel) kmhLabel.className = 'text-sm font-semibold ' + (_wdSpeedUnit === 'kmh' ? 'text-Ragnar-400' : 'text-gray-500');
    if (mphLabel) mphLabel.className = 'text-sm font-semibold ' + (_wdSpeedUnit === 'mph' ? 'text-Ragnar-400' : 'text-gray-500');
}

async function toggleWardrivingSpeedUnit() {
    const cb = document.getElementById('wardriving-speed-unit');
    if (!cb) return;
    const unit = cb.checked ? 'mph' : 'kmh';
    applyWardrivingSpeedUnitState(unit);
    try {
        await postAPI('/api/config', { wardriving_speed_unit: unit });
        addConsoleMessage('Wardriving speed unit set to ' + (unit === 'mph' ? 'mph' : 'km/h'), 'success');
    } catch (e) {
        console.error('[Wardriving] speed unit toggle error:', e);
        addConsoleMessage('Failed to update speed unit setting', 'error');
        applyWardrivingSpeedUnitState(unit === 'mph' ? 'kmh' : 'mph');
    }
}

async function loadWardrivingSpeedUnitState() {
    try {
        const res = await fetch('/api/config');
        const cfg = await res.json();
        applyWardrivingSpeedUnitState(cfg.wardriving_speed_unit === 'mph' ? 'mph' : 'kmh');
    } catch (e) { /* silent */ }
}

// ============================================================================
// ON-SCREEN KIOSK (Pi Flux / HDMI-DSI display)
// ============================================================================

let _kioskSettingsDebounce = null;
let _kioskPollTimer = null;

function _setKioskBadge(state) {
    const badge = document.getElementById('kiosk-service-badge');
    if (!badge) return;
    const styles = {
        active:     'bg-green-900 text-green-300',
        inactive:   'bg-gray-700 text-gray-300',
        activating: 'bg-amber-900 text-amber-300',
        deactivating: 'bg-amber-900 text-amber-300',
        failed:     'bg-red-900 text-red-300',
        not_installed: 'bg-gray-700 text-gray-400',
        unknown:    'bg-gray-700 text-gray-400',
    };
    badge.textContent = state || 'unknown';
    badge.className = 'text-xs px-2 py-0.5 rounded ' + (styles[state] || styles.unknown);
}

function _setKioskMessage(text, kind) {
    const el = document.getElementById('kiosk-status-message');
    if (!el) return;
    if (!text) { el.classList.add('hidden'); el.textContent = ''; return; }
    const tone = kind === 'error' ? 'text-red-400' : (kind === 'success' ? 'text-green-400' : 'text-amber-300');
    el.className = 'text-xs mt-2 ' + tone;
    el.textContent = text;
    el.classList.remove('hidden');
}

async function loadKioskState() {
    try {
        const data = await fetchAPI('/api/kiosk/status');
        // Hardware gate: the kiosk is a Ragnar Pi server feature. Chromium needs
        // ~1GB resident, so on a 512MB Pi Zero 2 W the card is not shown at all —
        // the backend refuses to enable it there anyway. The one exception is a
        // box that already has a kiosk installed from before the gate existed:
        // hiding the card there would leave no way to switch it off.
        const card = document.getElementById('kiosk-card');
        const incapable = data.capable === false;
        const legacyInstall = incapable && (data.installed || data.enabled);
        if (card) card.classList.toggle('hidden', incapable && !legacyInstall);
        if (incapable) {
            console.log('[Kiosk] unavailable on this hardware:', data.capability_reason);
            if (!legacyInstall) return;
            // Leave the toggle usable for turning it OFF only, and drop the
            // Reinstall button — the API refuses it on this hardware.
            const repairBtn = document.getElementById('kiosk-repair-btn');
            if (repairBtn) repairBtn.classList.add('hidden');
            _setKioskMessage((data.capability_reason || 'This board no longer supports the kiosk.') +
                             ' Turn it off to remove it.', 'error');
        }
        const enabledCb = document.getElementById('kiosk-enabled');
        const url = document.getElementById('kiosk-url');
        const rot = document.getElementById('kiosk-rotation');
        const cur = document.getElementById('kiosk-hide-cursor');
        const cfgPanel = document.getElementById('kiosk-config');
        if (enabledCb) enabledCb.checked = !!data.enabled;
        if (url && data.url) url.value = data.url;
        if (rot) rot.value = String(data.rotation ?? 0);
        if (cur) cur.checked = !!data.hide_cursor;
        if (cfgPanel) cfgPanel.classList.toggle('hidden', !data.enabled);
        _setKioskBadge(data.service_state || 'unknown');
    } catch (e) {
        _setKioskBadge('unknown');
    }
}

async function onKioskEnabledToggled(cb) {
    const enabled = !!cb.checked;
    const cfgPanel = document.getElementById('kiosk-config');
    if (cfgPanel) cfgPanel.classList.toggle('hidden', !enabled);
    _setKioskMessage(enabled ? 'Installing kiosk…' : 'Removing kiosk…', 'info');
    _setKioskBadge(enabled ? 'activating' : 'deactivating');
    try {
        const res = await fetch('/api/config', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({kiosk_enabled: enabled})
        });
        const data = await res.json();
        if (!data.success) {
            cb.checked = !enabled;
            if (cfgPanel) cfgPanel.classList.toggle('hidden', enabled);
            _setKioskMessage(data.error || 'Failed to update kiosk setting', 'error');
            return;
        }
        _pollKioskStatusUntilStable(enabled);
    } catch (e) {
        cb.checked = !enabled;
        if (cfgPanel) cfgPanel.classList.toggle('hidden', enabled);
        _setKioskMessage('Network error toggling kiosk: ' + e.message, 'error');
    }
}

function onKioskSettingChanged() {
    if (_kioskSettingsDebounce) clearTimeout(_kioskSettingsDebounce);
    _kioskSettingsDebounce = setTimeout(async () => {
        const url = document.getElementById('kiosk-url');
        const rot = document.getElementById('kiosk-rotation');
        const cur = document.getElementById('kiosk-hide-cursor');
        const payload = {
            kiosk_url: url ? url.value : 'http://localhost:8000',
            kiosk_rotation: rot ? parseInt(rot.value, 10) || 0 : 0,
            kiosk_hide_cursor: cur ? !!cur.checked : true,
        };
        try {
            const res = await fetch('/api/config', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(payload)
            });
            const data = await res.json();
            if (data.success) {
                _setKioskMessage('Settings saved — kiosk will pick up new values on next launch', 'info');
                _setKioskBadge('activating');
                _pollKioskStatusUntilStable(true);
            } else {
                _setKioskMessage(data.error || 'Failed to save kiosk settings', 'error');
            }
        } catch (e) {
            _setKioskMessage('Network error: ' + e.message, 'error');
        }
    }, 500);
}

// Where the answer actually is when the kiosk misbehaves. `journalctl -u
// ragnar-kiosk` is only worth naming when that unit exists: in autostart mode,
// and whenever the installer failed, it was never created — so the first thing
// everyone tried printed "-- No entries --" and the trail ended there.
function _kioskWhereToLook(status) {
    if (status && status.unit_exists) {
        return 'Check `journalctl -u ragnar-kiosk` on the Pi, or click Diagnose.';
    }
    return 'There is no kiosk service unit on this box'
        + (status && status.mode === 'autostart'
            ? ' (autostart mode runs inside your desktop session)' : '')
        + ', so `journalctl -u ragnar-kiosk` will be empty. Click Diagnose for the real state.';
}

function _pollKioskStatusUntilStable(expectEnabled, maxAttempts = 12) {
    // Stability differs by mode:
    //   service  → service_state reaches 'active' (enabled) or 'inactive' (disabled)
    //   autostart → installed=true is the success signal on enable; mode!=autostart on disable.
    if (_kioskPollTimer) clearTimeout(_kioskPollTimer);
    let attempts = 0;
    let lastStatus = null;
    const tick = async () => {
        attempts++;
        try {
            const data = await fetchAPI('/api/kiosk/status');
            lastStatus = data;
            _setKioskBadge(data.service_state || 'unknown');

            const isStableSuccess = (() => {
                if (expectEnabled) {
                    if (data.mode === 'service') return data.service_state === 'active';
                    if (data.mode === 'autostart') return data.installed === true;
                    return false;
                } else {
                    return data.installed === false || data.mode === 'not_installed';
                }
            })();
            const isStableFailure = data.service_state === 'failed';

            // A background install/teardown is still running. On a slow board
            // the installer apt-installs chromium and takes minutes, so the
            // attempt budget must not burn down while it works — otherwise a
            // healthy install reports "did not stabilize" at ~25s.
            if (data.busy) {
                const label = {
                    installing: 'Installing the kiosk (fetching chromium) — this can take several minutes…',
                    removing: 'Removing the kiosk…',
                    restarting: 'Restarting the kiosk…',
                    starting: 'Starting the kiosk…'
                }[data.phase] || 'Working…';
                const secs = data.elapsed ? ' (' + Math.round(data.elapsed) + 's)' : '';
                _setKioskMessage(label + secs, 'info');
                attempts = 0;                       // don't time out a live job
                _kioskPollTimer = setTimeout(tick, 2000);
                return;
            }

            // The job finished and reported why it failed. This is the case the
            // journal cannot answer: an installer failure means the unit was
            // never created, so `journalctl -u ragnar-kiosk` is empty.
            if (data.task_error) {
                _setKioskMessage(data.task_error, 'error');
                return;
            }

            if (isStableSuccess) {
                let msg;
                if (!expectEnabled) {
                    msg = 'Kiosk removed.';
                } else if (data.mode === 'autostart') {
                    msg = data.service_state === 'active'
                        ? 'Kiosk is running on the display.'
                        : 'Kiosk installed — launches on next desktop login.';
                } else {
                    msg = 'Kiosk is running on the display.';
                }
                _setKioskMessage(msg, 'success');
                setTimeout(() => _setKioskMessage('', null), 5000);
                return;
            }
            if (isStableFailure) {
                _setKioskMessage('Kiosk service failed. ' + _kioskWhereToLook(data), 'error');
                return;
            }
        } catch (e) { /* keep polling */ }
        if (attempts < maxAttempts) {
            _kioskPollTimer = setTimeout(tick, 2000);
        } else {
            // Genuinely stuck: no background job running, no reported error,
            // and the state never settled.
            _setKioskMessage('Kiosk state did not settle. ' + _kioskWhereToLook(lastStatus), 'error');
        }
    };
    _kioskPollTimer = setTimeout(tick, 1500);
}

// Re-run the kiosk installer and start it, whatever state the box is in — the
// same thing as `sudo bash scripts/install_kiosk.sh` followed by
// `systemctl enable --now ragnar-kiosk`. The toggle only reacts to a *change*,
// so this is the way back for a box whose config already says enabled.
async function repairKiosk() {
    const btn = document.getElementById('kiosk-repair-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Reinstalling…'; }
    try {
        const data = await postAPI('/api/kiosk/repair', {});
        _setKioskMessage(data.message || 'Reinstalling the kiosk…', 'info');
        const cb = document.getElementById('kiosk-enabled');
        if (cb) cb.checked = true;
        _pollKioskStatusUntilStable(true);
    } catch (e) {
        _setKioskMessage('Could not start the kiosk reinstall: ' + e.message, 'error');
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = 'Reinstall'; }
    }
}

// Run scripts/kiosk_doctor.sh on the box and show its report here, so "the
// screen is blank" can be diagnosed without an ssh session.
async function runKioskDoctor() {
    const btn = document.getElementById('kiosk-diagnose-btn');
    const out = document.getElementById('kiosk-doctor-report');
    if (btn) { btn.disabled = true; btn.textContent = 'Diagnosing…'; }
    if (out) {
        out.classList.remove('hidden');
        out.textContent = 'Running the kiosk doctor — this checks the browser, display, session and logs…';
    }
    try {
        const data = await postAPI('/api/kiosk/diagnose', {});
        if (out) {
            out.textContent = data.report || 'The kiosk doctor returned no output.';
            out.scrollTop = 0;
        }
        if (data.failed_checks > 0) {
            _setKioskMessage(`${data.failed_checks} check(s) failed — see the [FAIL] lines below.`, 'error');
        } else {
            _setKioskMessage('No failed checks. If the screen is still blank, the wrapper log '
                             + 'section of the report has the detail.', 'info');
        }
    } catch (e) {
        if (out) {
            out.textContent = 'Could not run the kiosk doctor: ' + e.message
                + '\n\nRun it directly on the Pi instead:\n  sudo bash scripts/kiosk_doctor.sh';
        }
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = 'Diagnose'; }
    }
}

// Kiosk-mode bootstrap: when the page is loaded with ?kiosk=1 (the chromium
// kiosk launches this way), add the body class so CSS can swap to the
// big-display layout. If the URL hash is #wardriving, start polling the
// wardriving live view.
(function initKioskModeBootstrap() {
    try {
        const params = new URLSearchParams(window.location.search);
        if (params.get('kiosk') !== '1') return;
        const applyClass = () => document.body && document.body.classList.add('kiosk-mode');
        if (document.body) {
            applyClass();
        } else {
            document.addEventListener('DOMContentLoaded', applyClass, { once: true });
        }
        if (window.location.hash === '#wardriving') {
            window.addEventListener('load', () => {
                _refreshKioskWardrivingView();
                setInterval(_refreshKioskWardrivingView, 2000);
            }, { once: true });
        }
    } catch (e) { /* no-op */ }
})();

function _fmtCoord(v, suffixes) {
    if (v === null || v === undefined || isNaN(v)) return '—';
    const abs = Math.abs(v);
    const dir = v >= 0 ? suffixes[0] : suffixes[1];
    return abs.toFixed(5) + '° ' + dir;
}

async function _refreshKioskWardrivingView() {
    try {
        const status = await fetch('/api/wardriving/status').then(r => r.json()).catch(() => ({}));
        const setText = (id, val) => {
            const el = document.getElementById(id);
            if (el) el.textContent = (val === undefined || val === null || val === '') ? '—' : String(val);
        };
        setText('kiosk-total-networks', status.total_networks ?? 0);
        setText('kiosk-scans-completed', status.scans_completed ?? 0);
        setText('kiosk-networks-this-scan', status.networks_this_scan ?? 0);
        setText('kiosk-bt-count', status.bluetooth_count ?? 0);
        setText('kiosk-cell-count', status.cell_count ?? 0);
        setText('kiosk-wd-running', status.running ? 'yes' : 'no');
        setText('kiosk-wd-interfaces', Array.isArray(status.interfaces) ? status.interfaces.join(', ') : '—');
        setText('kiosk-wd-band', status.band_mode || '—');
        setText('kiosk-wd-companion', status.companion_name || '—');
        setText('kiosk-wd-serial-networks', status.serial_networks ?? 0);
        setText('kiosk-wd-mesh', status.mesh_node_count ?? 0);

        const gps = status.gps || {};
        const fixEl = document.getElementById('kiosk-gps-fix');
        if (fixEl) {
            let label;
            if (!gps.connected) label = 'offline';
            else if (gps.has_fix) label = 'fix';
            else label = 'no fix';
            fixEl.textContent = label;
            fixEl.className = 'kiosk-row-value ' + (gps.has_fix ? 'kiosk-gps-fix-ok' : 'kiosk-gps-fix-none');
        }
        setText('kiosk-gps-lat', _fmtCoord(gps.latitude, ['N', 'S']));
        setText('kiosk-gps-lon', _fmtCoord(gps.longitude, ['E', 'W']));
        setText('kiosk-gps-sats', gps.satellites ?? '—');
        const speed = gps.speed_kmh;
        setText('kiosk-gps-speed', (typeof speed === 'number') ? formatWardrivingSpeed(speed) : '—');
        setText('kiosk-gps-port', gps.port || '—');
    } catch (e) {
        /* network blip — keep last values */
    }
}

async function importWigleCsv() {
    const fileInput = document.getElementById('wd-import-file');
    const resultDiv = document.getElementById('wd-import-result');
    if (!fileInput || !fileInput.files.length) {
        if (resultDiv) { resultDiv.textContent = 'Select a CSV file first.'; resultDiv.className = 'text-xs mt-2 text-yellow-400'; }
        return;
    }
    const formData = new FormData();
    formData.append('file', fileInput.files[0]);
    try {
        if (resultDiv) { resultDiv.textContent = 'Importing...'; resultDiv.className = 'text-xs mt-2 text-blue-400'; }
        const res = await fetch('/api/wardriving/import', { method: 'POST', body: formData });
        const data = await res.json();
        if (data.error) {
            if (resultDiv) { resultDiv.textContent = 'Error: ' + data.error; resultDiv.className = 'text-xs mt-2 text-red-400'; }
        } else {
            if (resultDiv) {
                resultDiv.textContent = `Imported: ${data.imported_wifi || 0} WiFi, ${data.imported_bluetooth || 0} BT, ${data.imported_cell || 0} Cell (${data.skipped || 0} skipped)`;
                resultDiv.className = 'text-xs mt-2 text-green-400';
            }
            loadWardrivingData();
        }
    } catch (e) {
        if (resultDiv) { resultDiv.textContent = 'Import failed: ' + e.message; resultDiv.className = 'text-xs mt-2 text-red-400'; }
    }
}

async function detectSerialPort() {
    const portInput = document.getElementById('wd-serial-port');
    const statusEl = document.getElementById('wd-serial-status');
    try {
        if (statusEl) { statusEl.textContent = 'Searching...'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-amber-900 text-amber-400'; }
        const res = await fetch('/api/wardriving/serial/detect');
        const data = await res.json();
        if (data.found && data.port) {
            if (portInput) portInput.value = data.port;
            if (statusEl) { statusEl.textContent = 'Found: ' + data.port; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-green-900 text-green-400'; }
        } else {
            if (statusEl) { statusEl.textContent = 'Not found'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-red-900 text-red-400'; }
            setTimeout(() => { if (statusEl) { statusEl.textContent = 'Disconnected'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400'; } }, 3000);
        }
    } catch (e) {
        console.error('[Wardriving] detect error:', e);
        if (statusEl) { statusEl.textContent = 'Error'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-red-900 text-red-400'; }
    }
}

async function toggleSerialListener() {
    const portInput = document.getElementById('wd-serial-port');
    const statusEl = document.getElementById('wd-serial-status');
    const btn = document.getElementById('wd-serial-btn');
    const isConnected = statusEl && statusEl.textContent === 'Connected';

    try {
        if (isConnected) {
            const res = await fetch('/api/wardriving/serial', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({action: 'stop'})
            });
            const data = await res.json();
            if (data.success) {
                if (statusEl) { statusEl.textContent = 'Disconnected'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400'; }
                if (btn) btn.textContent = 'Connect';
            }
        } else {
            const port = portInput ? portInput.value.trim() : '';
            if (!port) { alert('Enter a serial port (e.g. /dev/ttyUSB0 or COM3)'); return; }
            const res = await fetch('/api/wardriving/serial', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({action: 'start', port: port})
            });
            const data = await res.json();
            if (data.success) {
                if (statusEl) { statusEl.textContent = 'Connected'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-green-900 text-green-400'; }
                if (btn) btn.textContent = 'Disconnect';
            } else {
                alert('Serial error: ' + (data.error || 'Unknown'));
            }
        }
    } catch (e) {
        console.error('[Wardriving] serial toggle error:', e);
    }
}

function updateSerialStatus(status) {
    const statusEl = document.getElementById('wd-serial-status');
    const btn = document.getElementById('wd-serial-btn');
    const countEl = document.getElementById('wd-serial-count');
    const portInput = document.getElementById('wd-serial-port');
    if (status.serial_connected) {
        if (statusEl) { statusEl.textContent = 'Connected'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-green-900 text-green-400'; }
        if (btn) btn.textContent = 'Disconnect';
        if (portInput && status.serial_port) portInput.value = status.serial_port;
    } else {
        if (statusEl) { statusEl.textContent = 'Disconnected'; statusEl.className = 'text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400'; }
        if (btn) btn.textContent = 'Connect';
    }
    if (countEl) countEl.textContent = status.serial_networks || '0';
    _updateHuginnConfigBadge(status);
}

function _updateHuginnConfigBadge(status) {
    const stateEl = document.getElementById('wd-huginn-config-state');
    if (!stateEl) return;
    const companions = Array.isArray(status && status.companions) ? status.companions : [];
    const isHuginn = companions.some(c => c.connected && c.name === 'Huginn')
        || (status && status.companion_name === 'Huginn' && status.serial_connected);
    if (isHuginn) {
        stateEl.textContent = 'Live (Huginn connected)';
        stateEl.className = 'text-xs px-2 py-0.5 rounded-full bg-green-900 text-green-400';
    } else {
        stateEl.textContent = 'Saved (push on connect)';
        stateEl.className = 'text-xs px-2 py-0.5 rounded-full bg-gray-700 text-gray-400';
    }
}

async function loadHuginnConfig() {
    try {
        const res = await fetch('/api/wardriving/huginn_config');
        const data = await res.json();
        if (data.error) return;
        const sm = document.getElementById('wd-huginn-scan-ms');
        const bs = document.getElementById('wd-huginn-ble-spam');
        const sn = document.getElementById('wd-huginn-skimmer-names');
        if (sm) sm.value = (data.wifi_scan_duration_ms ?? '');
        if (bs) bs.value = (data.ble_spam_threshold ?? '');
        if (sn) sn.value = (data.skimmer_names ?? '');
        _updateHuginnConfigBadge({
            companion_name: data.companion,
            serial_connected: data.connected
        });
    } catch (e) {
        console.error('[Wardriving] huginn config load error:', e);
    }
}

async function saveHuginnConfig() {
    const sm = document.getElementById('wd-huginn-scan-ms');
    const bs = document.getElementById('wd-huginn-ble-spam');
    const sn = document.getElementById('wd-huginn-skimmer-names');
    const msg = document.getElementById('wd-huginn-config-msg');
    const body = {};
    if (sm && sm.value !== '') body.wifi_scan_duration_ms = parseInt(sm.value, 10);
    if (bs && bs.value !== '') body.ble_spam_threshold = parseInt(bs.value, 10);
    if (sn) body.skimmer_names = sn.value;
    try {
        if (msg) { msg.textContent = 'Saving…'; msg.className = 'text-xs text-gray-400'; }
        const res = await fetch('/api/wardriving/huginn_config', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(body)
        });
        const data = await res.json();
        if (!res.ok || data.error) {
            if (msg) { msg.textContent = 'Error: ' + (data.error || res.statusText); msg.className = 'text-xs text-red-400'; }
            return;
        }
        if (msg) {
            msg.textContent = data.live
                ? `Saved · pushed ${data.queued.length} command${data.queued.length === 1 ? '' : 's'} to Huginn`
                : 'Saved · will push on next Huginn connect';
            msg.className = 'text-xs text-emerald-400';
        }
    } catch (e) {
        console.error('[Wardriving] huginn config save error:', e);
        if (msg) { msg.textContent = 'Error: ' + e.message; msg.className = 'text-xs text-red-400'; }
    }
}

let _wdLastRenderedType = null;
function loadWardrivingTableByType() {
    const type = document.getElementById('wd-table-type')?.value || 'wifi';
    if (_wdLastRenderedType !== type) {
        // Type switch: tbody currently shows the previous type's rows, so we
        // must repaint regardless of the cached signature.
        delete _wdTableSignatures[type];
        _wdLastRenderedType = type;
    }
    if (type === 'wifi') loadWardrivingNetworks();
    else if (type === 'bluetooth') _loadWardrivingBluetooth();
    else if (type === 'cell') _loadWardrivingCellTable();
    else if (type === 'cameras') _loadWardrivingCameras();
    else if (type === 'zigbee') _loadWardrivingZigbee();
}

// Per-table render signature. We avoid re-rendering identical data on every
// 3s poll, which was causing flicker and scroll-jumps.
const _wdTableSignatures = {};

function _wdSig(type, items, keyFn) {
    // Cheap hash: count + sum-of-update-keys + last-id. Catches all real
    // changes (new rows, scan_count tick) without traversing the full set.
    let acc = items.length * 1000003;
    for (let i = 0; i < items.length; i++) acc = (acc + keyFn(items[i])) | 0;
    const last = items.length ? keyFn(items[items.length - 1]) : 0;
    return `${type}:${items.length}:${acc}:${last}`;
}

function _wdShouldRender(type, sig) {
    if (_wdTableSignatures[type] === sig) return false;
    _wdTableSignatures[type] = sig;
    return true;
}

// Reset the cached signature so a forced reload (session switch, type switch)
// always paints — necessary when the user wants to see a different dataset.
function _wdInvalidateTableCache() {
    for (const k in _wdTableSignatures) delete _wdTableSignatures[k];
}

// Replace tbody innerHTML while preserving the parent scroll container's
// scroll position. Without this, every poll snapped the user back to top.
function _wdSetTbodyHTML(tbody, html) {
    let scroller = tbody;
    while (scroller && scroller !== document.body) {
        const cs = window.getComputedStyle(scroller);
        if ((cs.overflowY === 'auto' || cs.overflowY === 'scroll') && scroller.scrollHeight > scroller.clientHeight) break;
        scroller = scroller.parentElement;
    }
    const top = scroller ? scroller.scrollTop : 0;
    const left = scroller ? scroller.scrollLeft : 0;
    tbody.innerHTML = html;
    if (scroller) { scroller.scrollTop = top; scroller.scrollLeft = left; }
}

const _WD_HEADERS = {
    wifi: '<tr><th class="px-3 py-2">SSID</th><th class="px-3 py-2">BSSID</th><th class="px-3 py-2">Security</th><th class="px-3 py-2">Ch</th><th class="px-3 py-2">Band</th><th class="px-3 py-2">Signal</th><th class="px-3 py-2 text-center">📷</th><th class="px-3 py-2 text-center">GPS</th><th class="px-3 py-2">Seen</th></tr>',
    bluetooth: '<tr><th class="px-3 py-2">Name</th><th class="px-3 py-2">MAC</th><th class="px-3 py-2">Type</th><th class="px-3 py-2">RSSI</th><th class="px-3 py-2 text-center">GPS</th><th class="px-3 py-2">First Seen</th><th class="px-3 py-2">Seen</th></tr>',
    cell: '<tr><th class="px-3 py-2">Provider</th><th class="px-3 py-2">Tech</th><th class="px-3 py-2">Cell ID</th><th class="px-3 py-2">MCC/MNC</th><th class="px-3 py-2">Signal</th><th class="px-3 py-2">Band</th><th class="px-3 py-2 text-center">GPS</th><th class="px-3 py-2">Seen</th></tr>',
    cameras: '<tr><th class="px-3 py-2">SSID</th><th class="px-3 py-2">BSSID</th><th class="px-3 py-2">Security</th><th class="px-3 py-2">Ch</th><th class="px-3 py-2">Band</th><th class="px-3 py-2">Signal</th><th class="px-3 py-2 text-center">GPS</th><th class="px-3 py-2">Seen</th></tr>',
    zigbee: '<tr><th class="px-3 py-2">Address</th><th class="px-3 py-2">Proto</th><th class="px-3 py-2">PAN ID</th><th class="px-3 py-2">Short</th><th class="px-3 py-2">Type</th><th class="px-3 py-2">Ch</th><th class="px-3 py-2">Signal</th><th class="px-3 py-2 text-center">LQI</th><th class="px-3 py-2 text-center">GPS</th><th class="px-3 py-2">Seen</th></tr>'
};

function _setWdTableHeaders(type) {
    const thead = document.getElementById('wd-table-head');
    if (thead) thead.innerHTML = _WD_HEADERS[type] || _WD_HEADERS.wifi;
}

async function loadWardrivingNetworks() {
    _setWdTableHeaders('wifi');
    try {
        const sid = _wdSelectedSessionId ? `&session_id=${encodeURIComponent(_wdSelectedSessionId)}` : '';
        const res = await fetch(`/api/wardriving/networks?limit=200${sid}`);
        const data = await res.json();
        const tbody = document.getElementById('wd-network-table');
        if (!tbody) return;

        const networks = data.networks || [];
        const sig = _wdSig('wifi', networks, n => (n.scan_count || 0) + (n.best_rssi || 0));
        if (!_wdShouldRender('wifi', sig)) return;
        if (networks.length === 0) {
            _wdSetTbodyHTML(tbody, '<tr><td colspan="9" class="text-center text-gray-500 py-8">No networks yet.</td></tr>');
            return;
        }

        const html = networks.map(n => {
            const secColor = !n.security || n.security === '--' ? 'text-green-400' :
                             n.security.includes('WEP') ? 'text-yellow-400' : 'text-blue-400';
            const sigColor = n.best_rssi > -50 ? 'text-emerald-400' :
                             n.best_rssi > -70 ? 'text-yellow-400' : 'text-red-400';
            const ssid = n.ssid || '<hidden>';
            const hasGps = n.best_lat && n.best_lon && n.best_lat !== 0 && n.best_lon !== 0;
            const gpsIcon = hasGps
                ? `<span title="${n.best_lat.toFixed(5)}, ${n.best_lon.toFixed(5)}" class="text-emerald-400 cursor-help">📍</span>`
                : '<span class="text-gray-600">—</span>';
            const camIcon = n.is_camera ? '<span class="text-pink-400">📷</span>' : '';
            return `<tr class="hover:bg-slate-800/50">
                <td class="px-3 py-1.5 font-mono text-xs" data-label="SSID">${escapeHtml(ssid)}</td>
                <td class="px-3 py-1.5 font-mono text-xs text-gray-400" data-label="BSSID">${n.bssid}</td>
                <td class="px-3 py-1.5 text-xs ${secColor}" data-label="Security">${n.security || 'Open'}</td>
                <td class="px-3 py-1.5 text-xs text-center" data-label="Ch">${n.channel || '-'}</td>
                <td class="px-3 py-1.5 text-xs" data-label="Band">${n.band || '-'}</td>
                <td class="px-3 py-1.5 text-xs ${sigColor}" data-label="Signal">${n.best_rssi} dBm</td>
                <td class="px-3 py-1.5 text-xs text-center" data-label="Camera">${camIcon || '—'}</td>
                <td class="px-3 py-1.5 text-xs text-center" data-label="GPS">${gpsIcon}</td>
                <td class="px-3 py-1.5 text-xs text-gray-400" data-label="Seen">${n.scan_count || 1}x</td>
            </tr>`;
        }).join('');

        _wdSetTbodyHTML(tbody, html);
        const info = document.getElementById('wd-table-info');
        if (info) info.classList.remove('hidden');
        updateElement('wd-showing', String(networks.length));
        updateElement('wd-total', String(data.total || networks.length));
    } catch (e) {
        console.error('[Wardriving] Networks error:', e);
    }
}

